  ui_story_5053_50530102_5_dialog_content = "Por aqui!",
  ui_story_5053_50530102_6_dialog_content = "Noite clara! Nos proteja!",
  ui_story_5053_50530102_7_dialog_content = "Não perca o foco na batalha, Caleb!",
  ui_story_5053_50530102_8_dialog_content = "Eu não recebo ordens de você! O que está acontecendo aqui...",
  ui_story_5053_50530102_9_dialog_content = "Abaixe suas armas, intrusos!",
  ui_story_5053_50530102_10_dialog_content = "Como você ousa começar uma briga na residência do City Lord?!",
  ui_story_5053_50530102_11_dialog_content = "Olá!",
  ui_story_5053_50530102_12_dialog_content = "AA monstro? O que é isso?!",
  ui_story_5053_50530102_13_dialog_content = "Vá se levantar!",
  ui_story_5053_50530102_14_dialog_content = "Está bem, está bem...",
  ui_story_5053_50530102_15_dialog_content = "Sch... wartz...!",
  ui_story_5053_50530102_16_dialog_content = "...",
  ui_story_5053_50530102_17_dialog_content = "Por que o escuro Angel ir atrás do meu pai o tempo todo?",
  ui_story_5053_50530102_18_dialog_content = "E continua chamando seu nome de família. Ele conhece vocês?",
  ui_story_5053_50530102_19_dialog_content = "Mas eu não reconheço nada...",
  ui_story_5053_50530102_20_dialog_content = "Aaaah—!",
  ui_story_5053_50530102_21_dialog_content = "A Lâmina do Soberano!",
  ui_story_5053_50530102_22_dialog_content = "Hum...",
  ui_story_5053_50530102_23_dialog_content = "Seu poder diminuiu muito desde nossa primeira batalha.",
  ui_story_5053_50530102_24_dialog_content = "Olá!",
  ui_story_5053_50530102_25_dialog_content = "No entanto, ainda muito incômodo.",
  ui_story_5053_50530102_26_dialog_content = "Por favor, deixe-me assumir o comando! Mesmo que minha habilidade psíquica esteja muito mais fraca agora, ainda posso coordenar!",
  ui_story_5053_50530102_27_dialog_content = "Obrigado, mas tenho outra perspectiva em mente.",
  ui_story_5053_50530102_28_dialog_content = "Você deve saber como lidar com isso, certo, Mia?",
  ui_story_5053_50530102_29_dialog_content = "Meu? Você está me dando o comando...?",
  ui_story_5053_50530102_30_dialog_content = "Vá com calma. Pense em mim como uma peça de xadrez em sua mão.",
  ui_story_5053_50530102_31_dialog_content = "Diga-me, para onde devo ir?",
  ui_story_5053_50530102_32_dialog_content = "Talvez... você pode continuar atraindo o anjo para frente, e então eu posso atacá-lo por trás?",
  ui_story_5053_50530102_33_dialog_content = "Insuficiente!",
  ui_story_5053_50530102_34_dialog_content = "Pois é...",
  ui_story_5053_50530102_35_dialog_content = "Você tem mais de uma peça de xadrez em suas mãos!",
  ui_story_5053_50530102_36_dialog_content = "Me desculpe, eu não posso...",
  ui_story_5053_50530102_37_dialog_content = "Relaxar, Mia, Você consegue!",
  ui_story_5053_50530102_38_dialog_content = "PlayerName...",
  ui_story_5053_50530102_39_dialog_content = "(Isso é praticamente um treinamento de cavaleiro. Você está tentando me orientar, padre?)",
  ui_story_5053_50530102_40_dialog_content = "(Não posso decepcioná-lo... E não posso desonrar os cavaleiros!)",
  ui_story_5053_50530102_41_dialog_content = "Sim, acho que entendi...",
  ui_story_5053_50530102_42_dialog_content = "Enquanto meu pai distrai o Escuro Angel... Jakine vai atacar de um lado e, tio, você ataca do outro.",
  ui_story_5053_50530102_43_dialog_content = "Vamos lançar uma ofensiva triangular para cercar o anjo... Isso deve funcionar, certo?",
  ui_story_5053_50530102_44_dialog_content = "Parece bom! Muito profissional, eu gosto.",
  ui_story_5053_50530102_45_dialog_content = "Não é um plano ruim. Vamos fazê-lo.",
  ui_story_5053_50530102_46_dialog_content = "Por aqui...",
  ui_story_5053_50530102_47_dialog_content = "O que você está? Por que você nos persegue?",
  ui_story_5053_50530102_48_dialog_content = "Sch... wartz...!!!",
  ui_story_5053_50530102_49_dialog_content = "(Está se segurando? Esta é a melhor janela para atacar!)",
  ui_story_5053_50530102_50_dialog_content = "Agora, pessoal!",
  ui_story_5053_50530102_51_dialog_content = "Desculpe...!",
  ui_story_5053_50530102_52_dialog_content = "Ative, Bola de Cristal!",
  ui_story_5053_50530102_53_dialog_content = "Conheça meu poder!",
  ui_story_5053_50530102_54_dialog_content = "Argh-!",
  ui_story_5053_50530102_55_dialog_content = "Bateu tudo. Somos simplesmente incríveis!",
  ui_story_5053_50530102_56_dialog_content = "Dói... dói...!",
  ui_story_5053_50530102_57_dialog_content = "Ela parece estar em agonia...",
  ui_story_5053_50530102_58_dialog_content = "Não fique todo mole comigo agora. O escuro Angel tem nos atacado sem motivo!",
  ui_story_5053_50530102_59_dialog_content = "Você está certo, sem piedade na batalha.",
  ui_story_5053_50530102_60_dialog_content = "Nosso ataque funcionou?",
  ui_story_5053_50530102_61_dialog_content = "Agh... Aaaaaaagh!",
  ui_story_5053_50530102_62_dialog_content = "Uau, que grito assustador.",
  ui_story_5053_50530102_63_dialog_content = "Oh não, está ligando e prestes a explodir!",
  ui_story_5053_50530102_64_dialog_content = "E agora...?!",
  ui_story_5053_50530102_65_dialog_content = "Você fez bem, Mia. Eu vou assumir agora.",
  ui_story_5053_50530102_66_dialog_content = "Pai...?",
  ui_story_5053_50530102_67_dialog_content = "Todos vocês, abaixe-se!",
  ui_story_5053_50530102_68_dialog_content = "Sch...",
  ui_story_5053_50530102_69_dialog_content = "Sch... wartz...!!!",
  ui_story_5053_50530102_70_dialog_content = "Você está tão desesperado para lutar comigo um contra um?",
  ui_story_5053_50530102_71_dialog_content = "Vou conceder o seu desejo, então.",
  ui_story_5053_50530102_72_dialog_content = "Agora, pegue seu epitáfio—!",
  ui_story_5053_50530102_73_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5053_50530102_74_dialog_content = "Ui... Ui...",
  ui_story_5053_50530102_75_dialog_content = "Pra onde ele foi?",
  ui_story_5053_50530102_76_dialog_content = "Provavelmente fugiu por um caminho lá fora.",
  ui_story_5053_50530102_77_dialog_content = "Isso foi incrível, Senhor Schwartz!",
  ui_story_5053_50530102_78_dialog_content = "Não importa o quão poderoso seja, o anjo deve estar gravemente ferido. Duvido que possa ir muito longe.",
  ui_story_5053_50530102_79_dialog_content = "...",
  ui_story_5053_50530102_80_dialog_content = "Você ainda está incomodado com o Dark Angel, Tio?",
  ui_story_5053_50530102_81_dialog_content = "Sua voz... Não importa, minha irmã nunca poderia ser um monstro.",
  ui_story_5053_50530102_82_dialog_content = "Aproveite o tempo agora para lançar seu feitiço, Jakine.",
  ui_story_5053_50530102_83_dialog_content = "Hã... Ah sim! Agora que o anjo intrometido finalmente se foi, posso tirar todo mundo daqui!",
  ui_story_5053_50530102_84_dialog_content = "Ad praesens! Ad praesens! Ad praesens!",
  ui_story_5053_50530102_85_dialog_content = "Voltemos à realidade!",
  ui_story_5053_50530102_86_dialog_content = "Abracadabra!",
  ui_story_5053_50530102_87_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530102_88_dialog_content = "Acho que não funcionou...",
  ui_story_5053_50530102_89_dialog_content = "Deixe-me tentar de novo!",
  ui_story_5053_50530102_90_dialog_content = "Ad praesens! Ad praesens! Ad praesens!",
  ui_story_5053_50530102_91_dialog_content = "Voltemos à realidade! Abracadabra!",
  ui_story_5053_50530102_92_dialog_content = "Você tem certeza de que acertou as palavras, Jakine?",
  ui_story_5053_50530102_93_dialog_content = "Claro! Todos estão de mãos dadas? Deixe-me verificar... Sim!",
  ui_story_5053_50530102_94_dialog_content = "Achei que falhou da última vez porque era tão caótico que nossas mãos não podiam estar todas unidas.",
  ui_story_5053_50530102_95_dialog_content = "Mas como é que ainda não funcionou desta vez?",
  ui_story_5053_50530102_96_dialog_content = "Você estava segurando o Cristal deste reino quando lançou o feitiço da última vez. Você esqueceu desta vez?",
  ui_story_5053_50530102_97_dialog_content = "Não, <color=#FFB400>você só precisa dele quando rebobinar o tempo</color>... Essa é a segurança contra falhas de emergência que minha mãe montou.",
  ui_story_5053_50530102_98_dialog_content = "Não é necessário para uma partida padrão como esta!",
  ui_story_5053_50530102_99_dialog_content = "Existem outras possibilidades?",
  ui_story_5053_50530102_100_dialog_content = "A menos que... <color=#FFB400>Nem todos nós estamos aqui</color>.",
  ui_story_5053_50530102_101_dialog_content = "Como assim?",
  ui_story_5053_50530102_102_dialog_content = "Por questões de segurança, uma pessoa deve ativar o Cristal para entrar e todos devem estar presentes para que todo o grupo saia.",
  ui_story_5053_50530102_103_dialog_content = "Mesmo que eu acidentalmente tenha quebrado essa regra com meu feitiço quando entramos, não posso fazer isso quando saímos!",
  ui_story_5053_50530102_104_dialog_content = "Todos nós estamos aqui, certo? não senti falta de ninguém...",
  ui_story_5053_50530102_105_dialog_content = "Alguém poderia ter sido puxado junto conosco?",
  ui_story_5053_50530102_106_dialog_content = "Ou talvez, antes de entrarmos, alguém entrou por outros meios.",
  ui_story_5053_50530102_107_dialog_content = "Mas o ativador faleceu há muito tempo, então isso é impossível, certo?",
  ui_story_5053_50530102_108_dialog_content = "...",
  ui_story_5053_50530102_109_dialog_content = "Meu senhor, v-você veio pessoalmente?!",
  ui_story_5053_50530102_110_dialog_content = "Peço desculpas por nossa incompetência ter perturbado sua paz.",
  ui_story_5053_50530102_111_dialog_content = "Está tudo bem. Você pode me contar o que aconteceu?",
  ui_story_5053_50530102_112_dialog_content = "Claro. Vários indivíduos desconhecidos invadiram o jardim e lutaram contra um monstro.",
  ui_story_5053_50530102_113_dialog_content = "Um dos intrusos parecia e se vestia muito como a princesa Veronica, mas não tenho certeza...",
  ui_story_5053_50530102_114_dialog_content = "Verônica? Eu vejo. Você está fazendo um bom trabalho.",
  ui_story_5053_50530201_1_dialog_content = "Então, vocês não querem experimentar esses lanches? Eu vou acabar com eles se você não fizer isso.",
  ui_story_5053_50530201_2_dialog_content = "Não posso acreditar que você ainda está com disposição para isso.",
  ui_story_5053_50530201_3_dialog_content = "Acabamos de lutar no jardim de Lady Joshua. Eu não tenho ideia de como dizer isso a ela.",
  ui_story_5053_50530201_4_dialog_content = "Relaxe, relaxe! Ficar estressado não vai nos levar a lugar nenhum!",
  ui_story_5053_50530201_5_dialog_content = "Eu invejo você por seu otimismo.",
  ui_story_5053_50530201_6_dialog_content = "Joshua não é alguém que receberia punições severas.",
  ui_story_5053_50530201_7_dialog_content = "Desde que ela ordenou que nos trouxessem aqui e até ofereceu sobremesa, isso mostra claramente que ela está nos tratando com respeito, não com hostilidade.",
  ui_story_5053_50530201_8_dialog_content = "Nós realmente devemos nos alegrar.",
  ui_story_5053_50530201_9_dialog_content = "Se <color=#FFB400>alguém</color> também estivesse presente, provavelmente já estaríamos presos.",
  ui_story_5053_50530201_10_dialog_content = "Alguém? De quem você está falando?",
  ui_story_5053_50530201_11_dialog_content = "...",
  ui_story_5053_50530201_12_dialog_content = "Ele quer dizer eu, o eu mais jovem.",
  ui_story_5053_50530201_13_dialog_content = "Você não está tão cheio de si afinal, Senhor Schwartz.",
  ui_story_5053_50530201_14_dialog_content = "A-Enfim, aí vem a Senhora Joshua deste mundo.",
  ui_story_5053_50530201_15_dialog_content = "Isso pelo menos prova que a Escuridão Angel não é senhora Joshua.",
  ui_story_5053_50530201_16_dialog_content = "Não devemos nos preocupar com isso agora. Jakine, você sabe como descobrir quem mais entrou no Cristal?",
  ui_story_5053_50530201_17_dialog_content = "Sempre há um jeito, claro.",
  ui_story_5053_50530201_18_dialog_content = "Só precisamos do Cristal da Memória Eterna para este mundo.",
  ui_story_5053_50530201_19_dialog_content = "Além de usá-lo para voltar no tempo, podemos <color=#FFB400>veja quem é uma ilusão e quem é real com o Cristal</color>.",
  ui_story_5053_50530201_20_dialog_content = "Mesmo que ainda não consiga identificar os locais exatos...",
  ui_story_5053_50530201_21_dialog_content = "Mas o problema com isso é que é demorado. Você só pode verificar uma pessoa por vez.",
  ui_story_5053_50530201_22_dialog_content = "Tem muita gente em Lumópolis...",
  ui_story_5053_50530201_23_dialog_content = "Tudo bem! Contanto que tenhamos o sistema de segurança em mãos, podemos continuar rebobinando para ganhar tempo!",
  ui_story_5053_50530201_24_dialog_content = "Embora isso vá consumir o Lumina mantendo o mundo, então não podemos fazer isso indiscriminadamente.",
  ui_story_5053_50530201_25_dialog_content = "Então nossa prioridade é encontrar o Cristal da Memória Eterna. Devemos colocar o escuro Angel assunto em espera por agora.",
  ui_story_5053_50530201_26_dialog_content = "É isso que você está procurando?",
  ui_story_5053_50530201_27_dialog_content = "É o Cristal da Memória Eterna em sua mão, Senhora Joshua?",
  ui_story_5053_50530201_28_dialog_content = "Você ouviu nossa conversa, senhora Joshua? Como você sabia que estávamos procurando o Cristal?",
  ui_story_5053_50530201_29_dialog_content = "Heheh, não se preocupe com isso, meu querido filho, e confira o Cristal.",
  ui_story_5053_50530201_30_dialog_content = "Espera... Como isso é possível?!",
  ui_story_5053_50530201_31_dialog_content = "Senhora Joshua... Você é um <color=#FFB400>verdadeiro auroriano</color>!",
  ui_story_5053_50530201_32_dialog_content = "!!!",
  ui_story_5053_50530201_33_dialog_content = "Irmã... Mas... É mesmo você?",
  ui_story_5053_50530201_34_dialog_content = "Quem mais eu seria, meu querido gênio?",
  ui_story_5053_50530201_35_dialog_content = "...",
  ui_story_5053_50530201_36_dialog_content = "Tem certeza, Jakine?",
  ui_story_5053_50530201_37_dialog_content = "Certo como sempre estarei! A menos que haja um problema com meus olhos!",
  ui_story_5053_50530201_38_dialog_content = "Mãe... isso é real?",
  ui_story_5053_50530201_39_dialog_content = "Claro que é.",
  ui_story_5053_50530201_40_dialog_content = "Você ainda parece o mesmo de quando se juntou aos cavaleiros, exatamente como eu me lembrava.",
  ui_story_5053_50530201_41_dialog_content = "*Sniff* Isso é... Isso é porque...",
  ui_story_5053_50530201_42_dialog_content = "É porque Forsakin modificou o corpo de Veronica... Mia e a fez fisicamente para sempre.",
  ui_story_5053_50530201_43_dialog_content = "Mas espere, eu vi com meus próprios olhos que você...",
  ui_story_5053_50530201_44_dialog_content = "Como assim?",
  ui_story_5053_50530201_45_dialog_content = "Sobre Schwartz Dia da Família doze anos atrás, os Eclipsitas plantaram uma Semente em Mia... em Veronica, durante uma missão para os cavaleiros.",
  ui_story_5053_50530201_46_dialog_content = "Em seguida, ela foi enviada para um laboratório Illumina para o chamado \"tratamento\", que na verdade era uma armadilha montada por eclipsitas e traidores.",
  ui_story_5053_50530201_47_dialog_content = "Para salvar Verônica, Joshua foi lutar contra eles sozinha.",
  ui_story_5053_50530201_48_dialog_content = "O resgate foi um sucesso, mas de alguma forma eles plantaram uma Semente em Joshua também...",
  ui_story_5053_50530201_49_dialog_content = "Mais tarde, depois de muito sofrimento...",
  ui_story_5053_50530201_50_dialog_content = "Ela <color=#FFB400>escolheu acabar com a própria vida</color>.",
  ui_story_5053_50530201_51_dialog_content = "No entanto, aqui você está no Cristal. Talvez você possa explicar isso.",
  ui_story_5053_50530201_52_dialog_content = "Schwartz, é assim que você fala com a esposa que não vê há doze anos?!",
  ui_story_5053_50530201_53_dialog_content = "Está tudo bem, Calebe. Daniel está fazendo a coisa certa para proteger a todos.",
  ui_story_5053_50530201_54_dialog_content = "Tudo bem, se você diz.",
  ui_story_5053_50530201_55_dialog_content = "Então devo continuar de onde Daniel parou.",
  ui_story_5053_50530201_56_dialog_content = "Era verdade que eu estava atormentado pela agonia...",
  ui_story_5053_50530201_57_dialog_content = "<color=#e8d9bb>Schwartz Manor, alguns anos atrás</color>",
  ui_story_5053_50530201_58_dialog_content = "*Tosse* Apenas me mate, Daniel.",
  ui_story_5053_50530201_59_dialog_content = "Eu não vou ouvir tal pedido de você, Joshua...",
  ui_story_5053_50530201_60_dialog_content = "Quanto mais resisto à Semente, mais ela me tortura.",
  ui_story_5053_50530201_61_dialog_content = "Eu posso sentir que está lutando comigo pelo controle do meu corpo.",
  ui_story_5053_50530201_62_dialog_content = "Existe uma maneira de libertá-lo, acredite em mim!",
  ui_story_5053_50530201_63_dialog_content = "Você se lembra de João, o médico? Sim, podemos pedir-lhe ajuda.",
  ui_story_5053_50530201_64_dialog_content = "Enviarei pessoas para localizá-lo imediatamente!",
  ui_story_5053_50530201_65_dialog_content = "Acalme-se e espere por mim.",
  ui_story_5053_50530201_66_dialog_content = "É inútil, Daniel, inútil...",
  ui_story_5053_50530201_67_dialog_content = "Urgh—",
  ui_story_5053_50530201_68_dialog_content = "Pare de lutar e se entregue a mim.",
  ui_story_5053_50530201_69_dialog_content = "Nunca!",
  ui_story_5053_50530201_70_dialog_content = "Eu nunca vou entregar meu corpo, mesmo que eu tenha que me apunhalar no coração!",
  ui_story_5053_50530201_71_dialog_content = "Não, largue essa adaga!",
  ui_story_5053_50530201_72_dialog_content = "Nunca!",
  ui_story_5053_50530201_73_dialog_content = "Largue!!!",
  ui_story_5053_50530201_74_dialog_content = "Ugh...",
  ui_story_5053_50530201_75_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5053_50530201_76_dialog_content = "O Cristal da Memória Eterna...?",
  ui_story_5053_50530201_77_dialog_content = "O que você está fazendo? Não!!!",
  ui_story_5053_50530201_78_dialog_content = "Revivamos os tempos dourados do passado...",
  ui_story_5053_50530201_79_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5053_50530201_80_dialog_content = "Você está bem, Joshua? O que foi aquele barulho alto?",
  ui_story_5053_50530201_81_dialog_content = "Como você não está respondendo? Pare de me assustar. To entrando.",
  ui_story_5053_50530201_82_dialog_content = "J-Joshua...?",
  ui_story_5053_50530201_83_dialog_content = "<size=50>Irmã!!!</size>",
  ui_story_5053_50530201_84_dialog_content = "A Semente me dividiu em <color=#FFB400>duas personalidades diferentes</color>.",
  ui_story_5053_50530201_85_dialog_content = "Um é o eu normal, mas o outro é um monstro irracional e perturbado.",
  ui_story_5053_50530201_86_dialog_content = "À medida que crescia, começou a tentar me dominar e ferir as pessoas ao meu redor.",
  ui_story_5053_50530201_87_dialog_content = "Eu não podia permitir isso, então comecei a lutar contra isso.",
  ui_story_5053_50530201_88_dialog_content = "O choque constante entre as personalidades estava dilacerando minha mente todos os dias.",
  ui_story_5053_50530201_89_dialog_content = "Não afetou o monstro em nada, então lentamente ganhou vantagem...",
  ui_story_5053_50530201_90_dialog_content = "Eu estava à beira de um colapso e sabia que estava prestes a perder.",
  ui_story_5053_50530201_91_dialog_content = "Então pensei em uma solução que não me deixaria vencer, mas derrotaria completamente o monstro—",
  ui_story_5053_50530201_92_dialog_content = "<color=#FFB400>E isso foi para prender nós dois no Cristal da Memória Eterna</color>.",
  ui_story_5053_50530201_93_dialog_content = "Com um desejo de morte, enviei a mim e ao monstro para este mundo.",
  ui_story_5053_50530201_94_dialog_content = "Somos um, então enquanto eu não for embora tem que ficar aqui comigo.",
  ui_story_5053_50530201_95_dialog_content = "Lutamos um contra o outro por muito, muito tempo.",
  ui_story_5053_50530201_96_dialog_content = "Depois que o relógio bateu meia-noite, nos tornamos parte deste mundo desde que quebramos a regra.",
  ui_story_5053_50530201_97_dialog_content = "Perdemos nossa memória e nos recombinamos para nos tornarmos deste mundo Joshua, e estamos revivendo esse mesmo dia várias vezes durante todo esse tempo.",
  ui_story_5053_50530201_98_dialog_content = "Até você chegar.",
  ui_story_5053_50530201_99_dialog_content = "Sua chegada despertou nossas memórias.",
  ui_story_5053_50530201_100_dialog_content = "O monstro acordado lutou e se separou de mim.",
  ui_story_5053_50530201_101_dialog_content = "<color=#FFB400>Ela me roubou todo o meu poder</color> e fugiu, tentando sair do Cristal.",
  ui_story_5053_50530201_102_dialog_content = "A situação é terrível, mas desta vez...",
  ui_story_5053_50530201_103_dialog_content = "Eu não sou o mesmo eu solitário que costumava ser.",
  ui_story_5053_50530201_104_dialog_content = "...",
  ui_story_5053_50530201_105_dialog_content = "O-Que história maravilhosa... Então o <color=#FFB400>Escuro Angel que nos atacou foi outra Senhora Joshua</color>?",
  ui_story_5053_50530201_106_dialog_content = "Escuro Angel? Você o nomeou...? De qualquer forma, sim, você poderia dizer isso.",
  ui_story_5053_50530201_107_dialog_content = "Apenas Joshua e eu estava a par dessa conversa, e os detalhes correspondiam exatamente.",
  ui_story_5053_50530201_108_dialog_content = "Realmente é você, Joshua...",
  ui_story_5053_50530201_109_dialog_content = "É ótimo que você finalmente acredite em mim.",
  ui_story_5053_50530201_110_dialog_content = "Oh, mãe... Você é real...",
  ui_story_5053_50530201_111_dialog_content = "Você está chorando de novo, pequenino.",
  ui_story_5053_50530201_112_dialog_content = "Eu não posso acreditar que você está aqui, Joshua. Eu tenho procurado... e nunca te encontrei...",
  ui_story_5053_50530201_113_dialog_content = "Como é bom falar com você novamente depois de doze anos...",
  ui_story_5053_50530201_114_dialog_content = "(A Semente, duas personalidades... Isso soa muito parecido com o que aconteceu com Mia.)",
  ui_story_5053_50530201_115_dialog_content = "(As personalidades de Mia são amigas e dependem uma da outra, mas é o oposto de Lady Joshua.)",
  ui_story_5053_50530201_116_dialog_content = "(As sementes têm efeitos tão diferentes em pessoas diferentes.)",
  ui_story_5053_50530201_117_dialog_content = "Falando nisso, você mencionou algo cerca de doze anos atrás.",
  ui_story_5053_50530201_118_dialog_content = "Faz doze anos que estou aqui?",
  ui_story_5053_50530201_119_dialog_content = "Correto.",
  ui_story_5053_50530201_120_dialog_content = "Não é de admirar que você esteja totalmente diferente, Daniel.",
  ui_story_5053_50530201_121_dialog_content = "Eu provavelmente não o reconheceria se não fosse por outros chamando seu nome.",
  ui_story_5053_50530201_122_dialog_content = "Mas o que aconteceu com seus olhos e rosto?",
  ui_story_5053_50530201_123_dialog_content = "Já passei por muitas guerras e turbulências para lembrar as origens de minhas cicatrizes.",
  ui_story_5053_50530201_124_dialog_content = "Mas ainda me lembro do dia em que você me deixou, e de como a adaga em seu peito era fria ao toque...",
  ui_story_5053_50530201_125_dialog_content = "Daniel...",
  ui_story_5053_50530201_126_dialog_content = "Falando nisso, o corpo de Lady Joshua foi enterrado, certo?",
  ui_story_5053_50530201_127_dialog_content = "Pode ela ou o escuro Angel deixar o Cristal então?",
  ui_story_5053_50530201_128_dialog_content = "Sim.",
  ui_story_5053_50530201_129_dialog_content = "Porque o corpo dela <color=#FFB400>nunca foi enterrado</color>.",
  ui_story_5053_50530201_130_dialog_content = "Como assim?",
  ui_story_5053_50530201_131_dialog_content = "Hmph, quando a encontrei, ela ainda não estava morta.",
  ui_story_5053_50530201_132_dialog_content = "Tirei algumas coisas e a trouxe para casa para tratamento.",
  ui_story_5053_50530201_133_dialog_content = "O que? Mas eu ouvi que toda a cidade testemunhou o funeral, então o que você fez...",
  ui_story_5053_50530201_134_dialog_content = "Eu cuidei do funeral de Joshua pessoalmente, então não pode ter havido nenhum erro.",
  ui_story_5053_50530201_135_dialog_content = "A menos que você a tenha exumado.",
  ui_story_5053_50530201_136_dialog_content = "Céus... Diga-me o que você fez, irmãozinho!",
  ui_story_5053_50530201_137_dialog_content = "Já que você pergunta... Sim, eu exumei você.",
  ui_story_5053_50530201_138_dialog_content = "Para evitar a detecção, cavei um túnel até a cripta à distância, para que ninguém soubesse.",
  ui_story_5053_50530201_139_dialog_content = "Você mesmo cavou? Vou ser sincero, não esperava que você fosse capaz de trabalhar assim.",
  ui_story_5053_50530201_140_dialog_content = "Estou disposto a fazer qualquer coisa pela minha irmã.",
  ui_story_5053_50530201_141_dialog_content = "Mas como você enganou o médico e o legista? Você os subornou...?",
  ui_story_5053_50530201_142_dialog_content = "Não, eu só usei uma poção.",
  ui_story_5053_50530201_143_dialog_content = "Fiquei surpreso também, que os grandes médicos em Lumopolis Gardens foram enganados por meus pequenos truques.",
  ui_story_5053_50530201_144_dialog_content = "Não é de admirar que eles não pudessem curar minha irmã.",
  ui_story_5053_50530201_145_dialog_content = "Você nunca foi tão humilde quando estava discutindo com os instrutores em Dawn Academia, Calebe.",
  ui_story_5053_50530201_146_dialog_content = "Você é o tipo de gênio que a Academia encontra talvez uma vez por século. Espero que você aplique sua inteligência nas coisas certas.",
  ui_story_5053_50530201_147_dialog_content = "Por que você teve que agir por sua própria vontade, Caleb...",
  ui_story_5053_50530201_148_dialog_content = "Porque você nunca quis sair Schwartz e as crianças, enquanto ele tornava a vida cada vez mais difícil para você.",
  ui_story_5053_50530201_149_dialog_content = "Eu só queria proteger você.",
  ui_story_5053_50530201_150_dialog_content = "Sinto muito por ter feito você se sentir tão sobrecarregado.",
  ui_story_5053_50530201_151_dialog_content = "Ele é assim porque você sempre o mimou.",
  ui_story_5053_50530201_152_dialog_content = "Voltaremos a isso depois de sairmos daqui, Caleb.",
  ui_story_5053_50530201_153_dialog_content = "Então, podemos sair daqui e reviver a mãe se derrotarmos o Dark Angel?",
  ui_story_5053_50530201_154_dialog_content = "Pelo que reunimos até agora, esse é o caso.",
  ui_story_5053_50530201_155_dialog_content = "Então, como está o corpo de Joshua agora? Pode suportar o choque de um renascimento abrupto?",
  ui_story_5053_50530201_156_dialog_content = "Está perfeitamente preservado, claro. Desde que ela entrou em coma, dediquei todo o meu tempo e esforço a ela.",
  ui_story_5053_50530201_157_dialog_content = "Quanto ao resultado, <color=#FFB400>apenas olhe para mim</color>.",
  ui_story_5053_50530201_158_dialog_content = "Olhe para você? Pelo que?",
  ui_story_5053_50530201_159_dialog_content = "Caleb, mesmo que seja para Joshua, Eu o proíbo de experimentos antiéticos.",
  ui_story_5053_50530201_160_dialog_content = "O que é isso para você?",
  ui_story_5053_50530201_161_dialog_content = "Espere, estou perdido. O que está acontecendo aqui?",
  ui_story_5053_50530201_162_dialog_content = "Quantos anos você acha que eu tenho, Jakine?",
  ui_story_5053_50530201_163_dialog_content = "Vinte e poucos anos?",
  ui_story_5053_50530201_164_dialog_content = "Veja o que quero dizer?",
  ui_story_5053_50530201_165_dialog_content = "Uh, se bem me lembro, o tio deve estar chegando aos 40...",
  ui_story_5053_50530201_166_dialog_content = "Huh-?!",
  ui_story_5053_50530201_167_dialog_content = "O que-?!",
  ui_story_5053_50530201_168_dialog_content = "Aqui eu achava que o tio já tinha nascido assim ou só bom de maquiagem... não esperava que fosse resultado de experimentos...",
  ui_story_5053_50530201_169_dialog_content = "Eu nunca usaria uma poção não testada na minha irmã.",
  ui_story_5053_50530201_170_dialog_content = "Nem machucaria pessoas inocentes como aqueles nobres, então a única escolha era testar em mim mesmo.",
  ui_story_5053_50530201_171_dialog_content = "Nossa, Calebe...",
  ui_story_5053_50530201_172_dialog_content = "Você está bem, mãe? Você não parece bem...",
  ui_story_5053_50530201_173_dialog_content = "Estou bem... estou acostumada, provavelmente...",
  ui_story_5053_50530201_174_dialog_content = "<size=30>Mas PlayerName, Caleb age muito imaturo também, então isso significa que sua pesquisa pode manter as pessoas para sempre jovens, tipo, mentalmente?</size>",
  ui_story_5053_50530201_175_dialog_content = "eu ouvi isso, Jakine!",
  ui_story_5053_50530201_176_dialog_content = "Enquanto seu corpo está bem, o Lumina nela tende a ficar fora de controle.",
  ui_story_5053_50530201_177_dialog_content = "Ainda preciso pesquisar mais sobre isso, pois ainda não encontrei uma solução.",
  ui_story_5053_50530201_178_dialog_content = "Lumina? Então é por isso que você me perguntou onde estava a Lumina de Lady Joshua!",
  ui_story_5053_50530201_179_dialog_content = "Obviamente. Minha intenção era encontrar sua Lumina residual para tratamento experimental.",
  ui_story_5053_50530201_180_dialog_content = "Mas quem poderia imaginar que ela estava no Cristal o tempo todo? E é por isso que a Lumina em seu corpo perdia o controle.",
  ui_story_5053_50530201_181_dialog_content = "Minha teoria estava completamente errada...",
  ui_story_5053_50530201_182_dialog_content = "Você deveria ter me contado sobre isso antes, Caleb.",
  ui_story_5053_50530201_183_dialog_content = "Te disse? Então você poderia continuar a torturá-la?",
  ui_story_5053_50530201_184_dialog_content = "Por que você está discutindo de novo? Não vamos fazer isso na frente dos outros.",
  ui_story_5053_50530201_185_dialog_content = "Desculpe, irmã.",
  ui_story_5053_50530201_186_dialog_content = "Dado que seu corpo ainda está em boas condições, devemos trazê-la para fora o mais rápido possível.",
  ui_story_5053_50530201_187_dialog_content = "Vamos voltar ao assunto e descobrir o que fazer com o Dark Angel.",
  ui_story_5053_50530201_188_dialog_content = "Sim, vamos fazer isso.",
  ui_story_5053_50530201_189_dialog_content = "Eu não posso derrotá-lo sozinho.",
  ui_story_5053_50530201_190_dialog_content = "Porque nós compartilhamos <color=#FFB400>o mesmo corpo e viveram uma vida</color>, apenas um terceiro poderia destruí-lo.",
  ui_story_5053_50530201_191_dialog_content = "Mas você deve ser cauteloso, pois também está caçando você.",
  ui_story_5053_50530201_192_dialog_content = "Nos caçando?",
  ui_story_5053_50530201_193_dialog_content = "Sim. Cansou-se dos nossos conflitos e quer ser independente, tomando para si o meu corpo.",
  ui_story_5053_50530201_194_dialog_content = "Seria muito difícil no mundo real.",
  ui_story_5053_50530201_195_dialog_content = "Mas como uma parte de mim que ativou o Cristal da Memória Eterna, pode <color=#FFB400>mate todas as outras pessoas vivas para que o Lumina se torne inteiro</color> aqui.",
  ui_story_5053_50530201_196_dialog_content = "Isso é verdade, Jakine?",
  ui_story_5053_50530201_197_dialog_content = "Sim. Pode parecer bobagem, mas é possível dentro do Cristal.",
  ui_story_5053_50530201_198_dialog_content = "O Crystal pode parecer um dispositivo de reprodução de memória, mas o princípio por trás dele é muito mais profundo do que isso.",
  ui_story_5053_50530201_199_dialog_content = "É por isso que mamãe só fez um por ordem da Rainha, depois escondeu tudo sobre ele depois...",
  ui_story_5053_50530201_200_dialog_content = "Então, basicamente, existem dois resultados possíveis.",
  ui_story_5053_50530201_201_dialog_content = "Uma é destruirmos o Escuro Angel e traga senhora Joshua conosco fora daqui.",
  ui_story_5053_50530201_202_dialog_content = "O outro é o escuro Angel nos mata e se solta no mundo real?",
  ui_story_5053_50530201_203_dialog_content = "Está correto. Que criança brilhante. Você é PlayerName, certo?",
  ui_story_5053_50530201_204_dialog_content = "Sim. A propósito, você sabe meu nome e o de Jakine, e o nome Mia não parece surpreendê-lo.",
  ui_story_5053_50530201_205_dialog_content = "Você também tem memórias anteriores ao reset?",
  ui_story_5053_50530201_206_dialog_content = "sim, desde <color=#FFB400>Eu estava com você</color> quando aconteceu.",
  ui_story_5053_50530201_207_dialog_content = "E não quero ficar longe da minha família de novo...",
  ui_story_5053_50530201_208_dialog_content = "Eu juro que vou destruir a Escuridão Angel e tirar você daqui, então não se preocupe.",
  ui_story_5053_50530201_209_dialog_content = "Eu também...! Vou libertá-lo deste lugar!",
  ui_story_5053_50530201_210_dialog_content = "Na verdade, eu tenho fé em todos vocês.",
  ui_story_5053_50530201_211_dialog_content = "O escuro Angel carece de habilidades de raciocínio, mas é tortuoso.",
  ui_story_5053_50530201_212_dialog_content = "Precisamos de iscas para atraí-lo.",
  ui_story_5053_50530201_213_dialog_content = "Você se importa, Daniel?",
  ui_story_5053_50530201_214_dialog_content = "Sem problemas. É melhor que eu assuma um papel tão vital e perigoso de qualquer maneira.",
  ui_story_5053_50530201_215_dialog_content = "Mas como faço para atraí-lo para mim?",
  ui_story_5053_50530201_216_dialog_content = "Você não precisa fazer nada, já que aquele monstro... <color=#FFB400>prefiro te odeia</color>.",
  ui_story_5053_50530201_217_dialog_content = "Se você não fosse forte o suficiente para afastá-lo, ele o teria dilacerado.",
  ui_story_5053_50530201_218_dialog_content = "Isso também se aplica ao jovem você neste mundo. É provável que o ataque na celebração.",
  ui_story_5053_50530201_219_dialog_content = "Mesmo que matar uma ilusão não faça nada por ela, ela ainda não consegue resistir.",
  ui_story_5053_50530201_220_dialog_content = "Eu vejo. Nesse caso, eu só tenho que encontrar o eu jovem e esperar que ele apareça.",
  ui_story_5053_50530201_221_dialog_content = "Espere, isso não será perigoso, padre? E se você se machucar?",
  ui_story_5053_50530201_222_dialog_content = "Você está sempre tão preocupado com nossa família, Vonnie.",
  ui_story_5053_50530201_223_dialog_content = "Mas, nossa situação atual é urgente e devemos focar nossas prioridades.",
  ui_story_5053_50530201_224_dialog_content = "Confie no seu pai, certo?",
  ui_story_5053_50530201_225_dialog_content = "Tudo bem...",
  ui_story_5053_50530201_226_dialog_content = "Após o desfile deve ser a cerimônia de abertura na praça.",
  ui_story_5053_50530201_227_dialog_content = "Devemos apostar lá fora?",
  ui_story_5053_50530201_228_dialog_content = "Boa ideia, mas você deve ficar comigo, Jakine.",
  ui_story_5053_50530201_229_dialog_content = "Por que? Não me esnobe, eu sou um lutador muito melhor do que PlayerName!",
  ui_story_5053_50530201_230_dialog_content = "Aham…",
  ui_story_5053_50530201_231_dialog_content = "Sim, eu sei, mas você opera o Cristal.",
  ui_story_5053_50530201_232_dialog_content = "Se os outros se machucarem, sempre podemos voltar no tempo para restaurar tudo.",
  ui_story_5053_50530201_233_dialog_content = "Mas se alguma coisa acontecesse com você, seria irreversível.",
  ui_story_5053_50530201_234_dialog_content = "V-Tem razão...",
  ui_story_5053_50530201_235_dialog_content = "Portanto, temos o City Lord como isca. Mia, PlayerName e eu irei juntos para a praça para parar o Dark Angel.",
  ui_story_5053_50530201_236_dialog_content = "Jakine e minha irmã ficará aqui e aguardará as boas novas.",
  ui_story_5053_50530201_237_dialog_content = "Certifique-se de cuidar bem dela, Jakine.",
  ui_story_5053_50530201_238_dialog_content = "Eu entendi! Por que todos duvidam de mim...",
  ui_story_5053_50530201_239_dialog_content = "Estou surpreso, Caleb. Achei que você insistiria em ficar com sua irmã.",
  ui_story_5053_50530201_240_dialog_content = "Matando a Escuridão Angel e tirar minha irmã daqui é a coisa mais importante agora. Você acha que eu não entendo isso?",
  ui_story_5053_50530201_241_dialog_content = "U-Um, devemos ir.",
  ui_story_5053_50530201_242_dialog_content = "Sim vamos lá!",
  ui_story_5053_50530201_243_dialog_content = "Parem de me empurrar, vocês dois.",
  ui_story_5053_50530201_244_dialog_content = "Tenha uma viagem segura!",
  ui_story_5053_50530201_245_dialog_content = "não vou te perder de novo, Joshua, Eu prometo.",
  ui_story_5053_50530201_246_dialog_content = "Sim, eu acredito em você.",
  ui_story_5053_50530201_247_dialog_content = "Você não vai.",
  ui_story_5053_50530301_1_dialog_content = "O desfile acabou e a celebração começará em breve.",
  ui_story_5053_50530301_2_dialog_content = "Ainda há bons lugares disponíveis para assistir?",
  ui_story_5053_50530301_3_dialog_content = "Depressa, vamos conferir!",
  ui_story_5053_50530301_4_dialog_content = "O que há para ver? É tudo uma farsa.",
  ui_story_5053_50530301_5_dialog_content = "Está lotado em todos os lugares. Como vamos identificar o Dark Angel quando mal podemos ver?",
  ui_story_5053_50530301_6_dialog_content = "Aproxime-se do estande e espere.",
  ui_story_5053_50530301_7_dialog_content = "Já que vocês dois podem atrair o Dark Angel para nós, não teríamos uma chance melhor se vocês dois subissem lá?",
  ui_story_5053_50530301_8_dialog_content = "Bem, acho melhor eu ir, já que as pessoas aqui ainda me reconhecem.",
  ui_story_5053_50530301_9_dialog_content = "Se o Pai for embora, pode causar muito caos...",
  ui_story_5053_50530301_10_dialog_content = "Verdadeiro. Mas se o Angel ataca o estande, você pode lutar sozinho, Mia?",
  ui_story_5053_50530301_11_dialog_content = "Eu... eu não estou sozinho.",
  ui_story_5053_50530301_12_dialog_content = "Pai neste mundo vai me ajudar também.",
  ui_story_5053_50530301_13_dialog_content = "Sem contar que terei uma visão melhor lá de cima. Posso retransmitir a posição do Anjo para você quando o vir...",
  ui_story_5053_50530301_14_dialog_content = "Hmm... Vou me mover para um local onde todos possam me ver e enviar um sinal!",
  ui_story_5053_50530301_15_dialog_content = "Oh, desculpe, padre... Talvez minha ideia seja muito ingênua?",
  ui_story_5053_50530301_16_dialog_content = "Você cobriu tudo. Vamos proceder como você sugeriu.",
  ui_story_5053_50530301_17_dialog_content = "O que? Sério?",
  ui_story_5053_50530301_18_dialog_content = "Obrigado pai. Vou sair agora, é só esperar meu sinal!",
  ui_story_5053_50530301_19_dialog_content = "Faz apenas um dia e Mia já é tão corajosa e independente. É bom ver isso.",
  ui_story_5053_50530301_20_dialog_content = "Não é hora de elogios, PlayerName. Mantenha os olhos abertos para o demônio que arruinou minha irmã!",
  ui_story_5053_50530301_21_dialog_content = "Sim, já vou!",
  ui_story_5053_50530301_22_dialog_content = "A celebração começará em breve, Carleen. Volte para o seu lugar.",
  ui_story_5053_50530301_23_dialog_content = "Sim, Pai.",
  ui_story_5053_50530301_24_dialog_content = "Pai, Carleen.",
  ui_story_5053_50530301_25_dialog_content = "Verônica?! Pai, Veronica está aqui!",
  ui_story_5053_50530301_26_dialog_content = "Verônica? O que você está fazendo aqui?",
  ui_story_5053_50530301_27_dialog_content = "M-Mãe me disse para voltar para casa para a celebração do Dia da Família.",
  ui_story_5053_50530301_28_dialog_content = "Você viu sua mãe?",
  ui_story_5053_50530301_29_dialog_content = "Sim... Ela não estava se sentindo bem, mas disse que não devíamos nos preocupar.",
  ui_story_5053_50530301_30_dialog_content = "Não é a princesa Veronica? Já faz muito tempo. Como vai?",
  ui_story_5053_50530301_31_dialog_content = "A princesa Veronica não se juntou aos cavaleiros e os seguiu até Umbraton?",
  ui_story_5053_50530301_32_dialog_content = "Eu queria voltar para a celebração, então pedi uma folga.",
  ui_story_5053_50530301_33_dialog_content = "Eu vejo. E você deveria, já que é Schwartz Dia da Família, afinal.",
  ui_story_5053_50530301_34_dialog_content = "Pena que minha família ainda está em Umbraton e não tem o privilégio.",
  ui_story_5053_50530301_35_dialog_content = "Veronica é membro da Câmara Schwartz então é direito dela voltar para o nosso Dia da Família!",
  ui_story_5053_50530301_36_dialog_content = "Fique quieto, Carleen, e seja respeitoso com o duque Hermes.",
  ui_story_5053_50530301_37_dialog_content = "não culpe Carleen, Pai. Voltei sem avisar.",
  ui_story_5053_50530301_38_dialog_content = "E já que o Duque Hermes está aqui, como está a Sra. Hermes ultimamente?",
  ui_story_5053_50530301_39_dialog_content = "Ela está indo muito bem, como sempre.",
  ui_story_5053_50530301_40_dialog_content = "Ando muito preocupada desde que seu neto sempre se despedia e dizia que dona Hermes estava muito mal.",
  ui_story_5053_50530301_41_dialog_content = "É bom saber que ela está bem.",
  ui_story_5053_50530301_42_dialog_content = "... Sim, obrigado pela consideração, alteza.",
  ui_story_5053_50530301_43_dialog_content = "De vez em quando, você deveria passar um tempo com sua família, duque Hermes.",
  ui_story_5053_50530301_44_dialog_content = "A princesa Veronica amadureceu. Os Cavaleiros devem tê-la treinado bem.",
  ui_story_5053_50530301_45_dialog_content = "Talvez, mas espero que não lhe suba à cabeça.",
  ui_story_5053_50530301_46_dialog_content = "Oh senhor Schwartz, você não precisa ser tão duro apenas com a princesa Veronica.",
  ui_story_5053_50530301_47_dialog_content = "Obrigado, Duque Troy. Pai está certo, devo permanecer humilde e continuar aprendendo.",
  ui_story_5053_50530301_48_dialog_content = "Entendo, princesa Veronica... Você realmente cresceu trabalhando com os cavaleiros.",
  ui_story_5053_50530301_49_dialog_content = "A celebração está começando. Por favor, sentem-se todos.",
  ui_story_5053_50530301_50_dialog_content = "Você foi tão legal, Verônica! Aqueles nobres do Conselho Ancião não te assustaram nem um pouco!",
  ui_story_5053_50530301_51_dialog_content = "Você acha? Eu estava nervoso, para ser honesto...",
  ui_story_5053_50530301_52_dialog_content = "Você também foi corajoso, Carleen, juntando-se ao desfile com o pai sozinho.",
  ui_story_5053_50530301_53_dialog_content = "Não, eu também não queria me separar de mamãe...",
  ui_story_5053_50530301_54_dialog_content = "Quando subi na carruagem, papai disse que mamãe não estava se sentindo bem e queria que eu fosse à festa sozinha...",
  ui_story_5053_50530301_55_dialog_content = "(Entendo, mamãe usou a doença como desculpa para conseguir Carleen e papai fora para que ela pudesse nos ver.)",
  ui_story_5053_50530301_56_dialog_content = "(Isso deve ter ferido os sentimentos da pequena Carleen, mas pelo menos nada disso é real.)",
  ui_story_5053_50530301_57_dialog_content = "(Prioridades, prioridades... Não, simplesmente não consigo.)",
  ui_story_5053_50530301_58_dialog_content = "Que tal voltarmos para a mãe, Carleen?",
  ui_story_5053_50530301_59_dialog_content = "Nós podemos? Isso não vai perturbá-la?",
  ui_story_5053_50530301_60_dialog_content = "Claro que não. Mamãe te ama e vai melhorar com você por perto.",
  ui_story_5053_50530301_61_dialog_content = "Amo mamãe e você também! E pai!",
  ui_story_5053_50530301_62_dialog_content = "Trarei frutas para ela e contarei sobre o desfile quando voltarmos!",
  ui_story_5053_50530301_63_dialog_content = "Hehe, boa menina.",
  ui_story_5053_50530301_64_dialog_content = "(É tão maravilhoso ver Carleen alegre novamente.)",
  ui_story_5053_50530301_65_dialog_content = "O que você vê?",
  ui_story_5053_50530301_66_dialog_content = "Mia está lá em cima, mas não consigo vê-la agora... Embora jovem Schwartz está pronto para falar.",
  ui_story_5053_50530301_67_dialog_content = "Sem visão do escuro Angel ainda.",
  ui_story_5053_50530301_68_dialog_content = "Mal podemos ver daqui. Devíamos tentar outro lugar.",
  ui_story_5053_50530301_69_dialog_content = "<color=#e8d9bb>Rachadura! Rachadura!</color>",
  ui_story_5053_50530301_70_dialog_content = "Isso soa como...",
  ui_story_5053_50530301_71_dialog_content = "Acho que não precisamos tentar outro lugar, Caleb.",
  ui_story_5053_50530301_72_dialog_content = "Pato, vocês dois!",
  ui_story_5053_50530301_73_dialog_content = "Por aqui!",
  ui_story_5053_50530302_1_dialog_content = "Declaro o início do Schwartz Comemoração do Dia da Família!",
  ui_story_5053_50530302_2_dialog_content = "Agora, vamos começar a cerimônia de confronto!",
  ui_story_5053_50530302_3_dialog_content = "(Como é que eles ainda não apareceram...)",
  ui_story_5053_50530302_4_dialog_content = "(Eles deveriam estar ali, mas não consigo vê-los...)",
  ui_story_5053_50530302_5_dialog_content = "(Não me diga que o Escuro Angel já rastreado PlayerName e os outros para baixo?)",
  ui_story_5053_50530302_6_dialog_content = "(Devo encontrar uma desculpa e sair?)",
  ui_story_5053_50530302_7_dialog_content = "Você está procurando alguma coisa, Vonnie?",
  ui_story_5053_50530302_8_dialog_content = "N-Não, Carleen... Olha, o confronto já começou por lá. Parece que vai ser emocionante.",
  ui_story_5053_50530302_9_dialog_content = "Quando eles vão me deixar participar... Eu sou tão bom quanto eles.",
  ui_story_5053_50530302_10_dialog_content = "Isso é estranho, os dois duelistas simplesmente pararam...",
  ui_story_5053_50530302_11_dialog_content = "E eles estão caminhando em nossa direção...",
  ui_story_5053_50530302_12_dialog_content = "Estamos recebendo um show bônus ou algo assim?",
  ui_story_5053_50530302_13_dialog_content = "O quê?",
  ui_story_5053_50530302_14_dialog_content = "(O pai está confuso, como se não soubesse o que está acontecendo.)",
  ui_story_5053_50530302_15_dialog_content = "(Eu não estava aqui naquela época, então não tenho ideia do que vai acontecer agora, mas isso não parece certo.)",
  ui_story_5053_50530302_16_dialog_content = "...",
  ui_story_5053_50530302_17_dialog_content = "(Este poderia ser...?!)",
  ui_story_5053_50530302_18_dialog_content = "Pai, o assassinato foi adiado!",
  ui_story_5053_50530302_19_dialog_content = "Como você sabe disso? E que é... movido?",
  ui_story_5053_50530302_20_dialog_content = "É uma longa história...",
  ui_story_5053_50530302_21_dialog_content = "O que você está fazendo aqui? Este não é o lugar para você!",
  ui_story_5053_50530302_22_dialog_content = "...",
  ui_story_5053_50530302_23_dialog_content = "Que insolência de sua parte em não me responder!",
  ui_story_5053_50530302_24_dialog_content = "Eles não vêm em paz... Volta, duque Hermes!",
  ui_story_5053_50530302_25_dialog_content = "Manter Carleen segura, Verônica!",
  ui_story_5053_50530302_26_dialog_content = "Cuidado, padre!",
  ui_story_5053_50530302_27_dialog_content = "Rá!",
  ui_story_5053_50530302_28_dialog_content = "Isso é tudo que você tem?",
  ui_story_5053_50530302_29_dialog_content = "Uma barra de soberano!",
  ui_story_5053_50530302_30_dialog_content = "Hum...",
  ui_story_5053_50530302_31_dialog_content = "Gostaria de tentar a sua sorte também?",
  ui_story_5053_50530302_32_dialog_content = "Rá!",
  ui_story_5053_50530302_33_dialog_content = "Toma essa!",
  ui_story_5053_50530302_34_dialog_content = "Hum...",
  ui_story_5053_50530302_35_dialog_content = "Você sobreviveu à minha lâmina? Diga-me, quem te mandou?",
  ui_story_5053_50530302_36_dialog_content = "Espere aí—",
  ui_story_5053_50530302_37_dialog_content = "É tarde demais para implorar por misericórdia agora!",
  ui_story_5053_50530302_38_dialog_content = "Veronica, por que o pai está sussurrando para o bandido?",
  ui_story_5053_50530302_39_dialog_content = "Não, não acho que é o pai que o está ameaçando... ele tem o pai com sua arma.",
  ui_story_5053_50530302_40_dialog_content = "<color=#e8d9bb>Rachadura!</color>",
  ui_story_5053_50530302_41_dialog_content = "Hã?",
  ui_story_5053_50530302_42_dialog_content = "Ha... ha! Breve...",
  ui_story_5053_50530302_43_dialog_content = "Por que seu rosto ficou tão contorcido?",
  ui_story_5053_50530302_44_dialog_content = "E por que ele está rindo quando está ferido? O que está acontecendo...",
  ui_story_5053_50530302_45_dialog_content = "Como é isso... Que tipo de poder é esse? <color=#FFB400>não consigo liberar minha arma</color>!",
  ui_story_5053_50530302_46_dialog_content = "Neste caso, Sovereign...",
  ui_story_5053_50530302_47_dialog_content = "Aqui vem...",
  ui_story_5053_50530302_48_dialog_content = "Olhe para cima, padre! O céu!",
  ui_story_5053_50530302_49_dialog_content = "<size=45><color=#e8d9bb>Rugido-!</color></size>",
  ui_story_5053_50530302_50_dialog_content = "O quê?",
  ui_story_5053_50530302_51_dialog_content = "T-O vento está muito forte! Isso vai me surpreender!",
  ui_story_5053_50530302_52_dialog_content = "Eu estou bem aqui, Carleen!",
  ui_story_5053_50530302_53_dialog_content = "Dragão... Um <color=#FFB400>Dragão</color>? Os Kartimas... Eles vão destruir o estande também?!",
  ui_story_5053_50530302_54_dialog_content = "<size=45><color=#e8d9bb>Rugido-!</color></size>",
  ui_story_5053_50530302_55_dialog_content = "Carleen, Verônica!",
  ui_story_5053_50530302_56_dialog_content = "Corra rápido!",
  ui_story_5053_50530302_57_dialog_content = "<size=45><color=#e8d9bb>Estrondo-!!!</color></size>",
  ui_story_5053_50530401_1_dialog_content = "Afe!",
  ui_story_5053_50530401_2_dialog_content = "Você é pior do que parece!",
  ui_story_5053_50530401_3_dialog_content = "Como uma mera Semente ousa me enganar imitando a voz da minha irmã...",
  ui_story_5053_50530401_4_dialog_content = "Farei com que você pague pelo sofrimento dela com sangue!",
  ui_story_5053_50530401_5_dialog_content = "Rá!",
  ui_story_5053_50530401_6_dialog_content = "...",
  ui_story_5053_50530401_7_dialog_content = "Não seja imprudente, Caleb!",
  ui_story_5053_50530401_8_dialog_content = "Hora de ir!",
  ui_story_5053_50530401_9_dialog_content = "Afe!",
  ui_story_5053_50530401_10_dialog_content = "O quê?!",
  ui_story_5053_50530401_11_dialog_content = "Calebe!!!",
  ui_story_5053_50530401_12_dialog_content = "Ca...lebe...?",
  ui_story_5053_50530401_13_dialog_content = "Mantenha meu nome longe de seus lábios...",
  ui_story_5053_50530401_14_dialog_content = "Agora!",
  ui_story_5053_50530401_15_dialog_content = "Vou sacudir cada estrela—!!!",
  ui_story_5053_50530401_16_dialog_content = "Eca!!!",
  ui_story_5053_50530401_17_dialog_content = "Sch... wartz...",
  ui_story_5053_50530401_18_dialog_content = "Sch...",
  ui_story_5053_50530401_19_dialog_content = "Tudo parece voltar ao normal?",
  ui_story_5053_50530401_20_dialog_content = "Acabou... Isso significa que está morto?",
  ui_story_5053_50530401_21_dialog_content = "Não, algo está errado. Olhe para lá.",
  ui_story_5053_50530401_22_dialog_content = "Argh-!",
  ui_story_5053_50530401_23_dialog_content = "Corra!",
  ui_story_5053_50530401_24_dialog_content = "A multidão está fugindo da praça... A rebelião começou?",
  ui_story_5053_50530401_25_dialog_content = "Não pode ser. Sem a nossa interferência, teria começado depois do assassinato...",
  ui_story_5053_50530401_26_dialog_content = "Não...",
  ui_story_5053_50530401_27_dialog_content = "Olhe para o céu!",
  ui_story_5053_50530401_28_dialog_content = "Rugido-!",
  ui_story_5053_50530401_29_dialog_content = "O dragão Kartima?!",
  ui_story_5053_50530401_30_dialog_content = "O que está fazendo na cidade?",
  ui_story_5053_50530401_31_dialog_content = "Oh céus, o que uma coisa dessas está fazendo em Lumopolis...?",
  ui_story_5053_50530401_32_dialog_content = "Vocês guardas não deveriam nos proteger em tempos como este? O que você está esperando?",
  ui_story_5053_50530401_33_dialog_content = "...",
  ui_story_5053_50530401_34_dialog_content = "E-Ei, o que você está fazendo?",
  ui_story_5053_50530401_35_dialog_content = "Matar... Matar... Matar...",
  ui_story_5053_50530401_36_dialog_content = "Aaah—!",
  ui_story_5053_50530401_37_dialog_content = "A Lâmina do Soberano!",
  ui_story_5053_50530401_38_dialog_content = "Que tipo de cavaleiro você é para ferir pessoas indefesas? É este o nível a que Kartimas se rebaixou?",
  ui_story_5053_50530401_39_dialog_content = "Ai...",
  ui_story_5053_50530401_40_dialog_content = "T-Este ainda está vivo!",
  ui_story_5053_50530401_41_dialog_content = "Mate...",
  ui_story_5053_50530401_42_dialog_content = "Matar? O que você está dizendo?",
  ui_story_5053_50530401_43_dialog_content = "Sch... wartz...",
  ui_story_5053_50530401_44_dialog_content = "Mate... Mate... Mate os intrusos!",
  ui_story_5053_50530401_45_dialog_content = "Fora do caminho, PlayerName!",
  ui_story_5053_50530401_46_dialog_content = "Por que, o que há de errado com ela...?",
  ui_story_5053_50530401_47_dialog_content = "<color=#e8d9bb><size=45>Estrondo!</size></color>",
  ui_story_5053_50530401_48_dialog_content = "Uma onda de choque tão poderosa. E agora?",
  ui_story_5053_50530401_49_dialog_content = "A explosão está vindo do estande!",
  ui_story_5053_50530401_50_dialog_content = "O Senhor da Cidade foi atacado!",
  ui_story_5053_50530401_51_dialog_content = "Corra por suas vidas!",
  ui_story_5053_50530401_52_dialog_content = "Atacado? Mia...!",
  ui_story_5053_50530401_53_dialog_content = "Se Mia ainda estava de pé... Não, não pode ser...",
  ui_story_5053_50530401_54_dialog_content = "Minha irmã ainda está no Schwartz mansão. Se os rebeldes a encontrarem...",
  ui_story_5053_50530401_55_dialog_content = "PlayerName, saia com Caleb!",
  ui_story_5053_50530401_56_dialog_content = "Se eu não voltar com Mia, dizer Jakine para rebobinar imediatamente!",
  ui_story_5053_50530401_57_dialog_content = "Senhor Schwartz!!!",
  ui_story_5053_50530401_58_dialog_content = "(O que está acontecendo? O Cristal da Memória Eterna está quebrado?)",
  ui_story_5053_50530401_59_dialog_content = "(Ou talvez o Escuro Angel ainda está viva e isso é tudo que ela está fazendo...?)",
  ui_story_5053_50530401_60_dialog_content = "Não fique aí parado! Precisamos sair daqui!",
  ui_story_5053_50530401_61_dialog_content = "Matar... Matar... Matar...",
  ui_story_5053_50530402_1_dialog_content = "Rá!",
  ui_story_5053_50530402_2_dialog_content = "Hum...",
  ui_story_5053_50530402_3_dialog_content = "Malditos sejam os rebeldes... Obrigado pela ajuda, velho.",
  ui_story_5053_50530402_4_dialog_content = "Onde estão as altezas?",
  ui_story_5053_50530402_5_dialog_content = "As altezas? Você deveria estar pensando em se manter vivo.",
  ui_story_5053_50530402_6_dialog_content = "O que você quer dizer com isso?",
  ui_story_5053_50530402_7_dialog_content = "Princesa Carleen, Princesa Veronica e o Lorde da Cidade foram atacados pelo dragão... <color=#FFB400>eles estão mortos</color>!",
  ui_story_5053_50530402_8_dialog_content = "Onde? Onde está a princesa Veronica?!",
  ui_story_5053_50530402_9_dialog_content = "Ainda no estande. Não me diga que você quer ir recolher seus restos mortais em um momento como este?",
  ui_story_5053_50530402_10_dialog_content = "Eu agradeço.",
  ui_story_5053_50530402_11_dialog_content = "Tolo... Agarrar-se ao que já perdeu só lhe custará a vida.",
  ui_story_5053_50530402_12_dialog_content = "Joshua!",
  ui_story_5053_50530402_13_dialog_content = "Senhora Joshua! Jakine! Onde você está?",
  ui_story_5053_50530402_14_dialog_content = "Por que não estão respondendo... Joshua!",
  ui_story_5053_50530402_15_dialog_content = "Estou aqui, Calebe.",
  ui_story_5053_50530402_16_dialog_content = "Graças a Deus você está bem! Achei que tinha te perdido de novo...",
  ui_story_5053_50530402_17_dialog_content = "A insurgência foi promovida. Temos que levar você para algum lugar seguro.",
  ui_story_5053_50530402_18_dialog_content = "Onde está a Jakine? Onde no mundo ela foi em um momento como este?",
  ui_story_5053_50530402_19_dialog_content = "Fique calmo, Caleb, uma coisa de cada vez.",
  ui_story_5053_50530402_20_dialog_content = "Você está suando por toda parte, até o colarinho está amassado. Aqui, deixe-me consertar isso para você.",
  ui_story_5053_50530402_21_dialog_content = "Huh? Uh, eu posso lidar com isso sozinho...",
  ui_story_5053_50530402_22_dialog_content = "T-Obrigado, mana.",
  ui_story_5053_50530402_23_dialog_content = "Senhora Joshua está tudo bem, mas onde foi Jakine fugir para?",
  ui_story_5053_50530402_24_dialog_content = "Onde você está, Jakine?!!",
  ui_story_5053_50530402_25_dialog_content = "Hum...",
  ui_story_5053_50530402_26_dialog_content = "Sim... é...?",
  ui_story_5053_50530402_27_dialog_content = "O que há de errado, Calebe?",
  ui_story_5053_50530402_28_dialog_content = "T-Isto...",
  ui_story_5053_50530402_29_dialog_content = "Mas por que?",
  ui_story_5053_50530402_30_dialog_content = "Seu peito, Caleb?!",
  ui_story_5053_50530402_31_dialog_content = "Você se machucou no caminho? N-Não, não pode ser...",
  ui_story_5053_50530402_32_dialog_content = "Por que você ainda gosta de sentar no chão na sua idade?",
  ui_story_5053_50530402_33_dialog_content = "Ainda imaturo como sempre, Caleb.",
  ui_story_5053_50530402_34_dialog_content = "Que decepcionante.",
  ui_story_5053_50530402_35_dialog_content = "Por que...",
  ui_story_5053_50530402_36_dialog_content = "Irmã...",
  ui_story_5053_50530402_37_dialog_content = "Mia...",
  ui_story_5053_50530402_38_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_39_dialog_content = "Eu sei que podemos voltar no tempo...",
  ui_story_5053_50530402_40_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_41_dialog_content = "Mas eu não quero que você passe por isso...",
  ui_story_5053_50530402_42_dialog_content = "Mesmo que você me odeie por mandá-lo para longe de mim, estarei em paz sabendo que você está são e salvo...",
  ui_story_5053_50530402_43_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_44_dialog_content = "<size=45>Rugido-!</size>",
  ui_story_5053_50530402_45_dialog_content = "Ainda quer me matar, depois de matar minha família?",
  ui_story_5053_50530402_46_dialog_content = "Eu retribuirei o dobro da dor que você causou a eles...",
  ui_story_5053_50530402_47_dialog_content = "<size=45>Rugido-!</size>",
  ui_story_5053_50530402_48_dialog_content = "<size=45>Agora morra!!!</size>",
  ui_story_5053_50530402_49_dialog_content = "<color=#e8d9bb>Baque, baque...</color>",
  ui_story_5053_50530402_50_dialog_content = "(Porque porque porque?!)",
  ui_story_5053_50530402_51_dialog_content = "(Por que a senhora Joshua matar Caleb, seu próprio irmão?!)",
  ui_story_5053_50530402_52_dialog_content = "<color=#e8d9bb>Bate, baque, baque...</color>",
  ui_story_5053_50530402_53_dialog_content = "(Todo mundo neste mundo enlouqueceu?)",
  ui_story_5053_50530402_54_dialog_content = "(Ou estou preso em um pesadelo sem fim?)",
  ui_story_5053_50530402_55_dialog_content = "<color=#e8d9bb>Bate, baque, baque...</color>",
  ui_story_5053_50530402_56_dialog_content = "(Ela se foi?)",
  ui_story_5053_50530402_57_dialog_content = "(Mas não posso me esconder embaixo da mesa para sempre... O que vou fazer?)",
  ui_story_5053_50530402_58_dialog_content = "<color=#e8d9bb>Baque, baque.</color>",
  ui_story_5053_50530402_59_dialog_content = "(Os passos pararam...)",
  ui_story_5053_50530402_60_dialog_content = "EU ENCONTREI VOCÊ!",
  ui_story_5053_50530402_61_dialog_content = "O quê?!",
  ui_story_5053_50530402_62_dialog_content = "Oh, querida, nem mesmo Carleen ainda brinca de esconde-esconde.",
  ui_story_5053_50530402_63_dialog_content = "Você não é mais uma criança, PlayerName. Por quanto tempo você quer que eu continue jogando com você?",
  ui_story_5053_50530402_64_dialog_content = "Huff... puff...",
  ui_story_5053_50530402_65_dialog_content = "Pare de correr. Isso só tornará sua morte mais agonizante.",
  ui_story_5053_50530402_66_dialog_content = "Mia, Caleb... A Lumina deles é legal. Nunca me senti tão revigorado.",
  ui_story_5053_50530402_67_dialog_content = "Eu me pergunto o que acontece se eu pegar uma Lumina de Caelestite? Talvez eu possa ler a mente dos outros também?",
  ui_story_5053_50530402_68_dialog_content = "Eu não vou deixar você se safar disso!",
  ui_story_5053_50530402_69_dialog_content = "Bem, eu já posso controlar as pessoas neste mundo.",
  ui_story_5053_50530402_70_dialog_content = "Isso com certeza torna as coisas simples e fáceis, não é?",
  ui_story_5053_50530402_71_dialog_content = "Huff... puff...",
  ui_story_5053_50530402_72_dialog_content = "(Apenas uma porta à minha frente... Por favor, não deixe que seja um beco sem saída!)",
  ui_story_5053_50530402_73_dialog_content = "Isso é... Bem, acho que é o instinto do Último Caelestita.",
  ui_story_5053_50530402_74_dialog_content = "Boa escolha.",
  ui_story_5053_50530402_75_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5053_50530402_76_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_77_dialog_content = "Jakine?!",
  ui_story_5053_50530402_78_dialog_content = "Jakine! Seu corpo está frio e ela não está respirando...",
  ui_story_5053_50530402_79_dialog_content = "Você com certeza sabe como escolher um local, PlayerName.",
  ui_story_5053_50530402_80_dialog_content = "A vidente de Northland podia controlar o Cristal, então, naturalmente, ela foi a primeira que matei.",
  ui_story_5053_50530402_81_dialog_content = "Por que outro motivo eu teria pedido a ela para ficar comigo?",
  ui_story_5053_50530402_82_dialog_content = "Eu não entendo, senhora Joshua, por que você está fazendo isso?",
  ui_story_5053_50530402_83_dialog_content = "Por que você mataria Jakine e seu irmão... E eu também?",
  ui_story_5053_50530402_84_dialog_content = "É tão difícil de entender? Eu preciso de seus poderes.",
  ui_story_5053_50530402_85_dialog_content = "Não tenho nenhuma má vontade, mas seus sacrifícios são necessários.",
  ui_story_5053_50530402_86_dialog_content = "Eu não entendo, você é o verdadeiro Joshua?",
  ui_story_5053_50530402_87_dialog_content = "O que você é, realmente?",
  ui_story_5053_50530402_88_dialog_content = "Eu sou Joshua, o Real Joshua!",
  ui_story_5053_50530402_89_dialog_content = "Abra bem os olhos e olhe bem. Lembre-se disso antes de morrer.",
  ui_story_5053_50530402_90_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5053_50530402_91_dialog_content = "O quê?",
  ui_story_5053_50530402_92_dialog_content = "Venha até mim, PlayerName...",
  ui_story_5053_50530402_93_dialog_content = "Jakine?!",
  ui_story_5053_50530402_94_dialog_content = "Você está vivo? Achei que você fosse...",
  ui_story_5053_50530402_95_dialog_content = "Você esqueceu? Sou uma cartomante errante desde pequena...",
  ui_story_5053_50530402_96_dialog_content = "O que é um pequeno truque? ... (começa a tossir)",
  ui_story_5053_50530402_97_dialog_content = "Jakine!",
  ui_story_5053_50530402_98_dialog_content = "Cadê os outros?",
  ui_story_5053_50530402_99_dialog_content = "...",
  ui_story_5053_50530402_100_dialog_content = "Maldições...!",
  ui_story_5053_50530402_101_dialog_content = "Lançando ilusões com a magia das Terras do Norte... Não é de admirar que vocês pudessem criar algo como o Cristal da Memória Eterna.",
  ui_story_5053_50530402_102_dialog_content = "Que inteligência revoltante.",
  ui_story_5053_50530402_103_dialog_content = "Desculpe, eu sempre fui uma criança travessa.",
  ui_story_5053_50530402_104_dialog_content = "Então permita-me mostrar-lhe um pouco de disciplina!",
  ui_story_5053_50530402_105_dialog_content = "Em guarda, bola de cristal!",
  ui_story_5053_50530402_106_dialog_content = "Pegue aquele Cristal da Memória Eterna aqui, PlayerName.",
  ui_story_5053_50530402_107_dialog_content = "Coloque sua mão sobre ele. Mesmo que eu não consiga...",
  ui_story_5053_50530402_108_dialog_content = "Você não deve deixar ir.",
  ui_story_5053_50530402_109_dialog_content = "Sim!",
  ui_story_5053_50530402_110_dialog_content = "Reditus, reditus, reditus!",
  ui_story_5053_50530402_111_dialog_content = "Rebobinar ao início...",
  ui_story_5053_50530402_112_dialog_content = "Abracadabra — Urgh!",
  ui_story_5053_50530402_113_dialog_content = "Essa não...",
  ui_story_5053_50530402_114_dialog_content = "Jakine... Jakine—!",
  ui_story_5053_50530501_0X_dialog_content = "<color=#e8d9bb>Após a segunda reinicialização—</color>",
  ui_story_5053_50530501_1_dialog_content = "Tudo está definido, meu senhor.",
  ui_story_5053_50530501_2_dialog_content = "A carruagem espera do lado de fora e está pronta para partir a qualquer momento.",
  ui_story_5053_50530501_3_dialog_content = "...",
  ui_story_5053_50530501_4_dialog_content = "Meu senhor, ainda está preocupado com sua esposa?",
  ui_story_5053_50530501_5_dialog_content = "Joshua sempre teve boa saúde e normalmente não reclamava de se sentir indisposta. Especialmente não em um dia como este.",
  ui_story_5053_50530501_6_dialog_content = "Ela tem estado bastante ocupada ultimamente, defendendo as novas políticas para as esposas dos nobres. Imagino que isso a tenha prejudicado.",
  ui_story_5053_50530501_7_dialog_content = "Fique tranquilo, meu senhor. Eu cuidarei bem dela.",
  ui_story_5053_50530501_8_dialog_content = "Ugh...",
  ui_story_5053_50530501_9_dialog_content = "Onde estou...?",
  ui_story_5053_50530501_10_dialog_content = "Espere, este lugar... Ainda é dia lá fora?",
  ui_story_5053_50530501_11_dialog_content = "Eu estava sendo perseguido e me deparei com Jakine, então...",
  ui_story_5053_50530501_12_dialog_content = "(Obrigado por me salvar, Jakine...)",
  ui_story_5053_50530501_13_dialog_content = "(Mas não a vejo em lugar algum por aqui... Será que nos separamos, assim como quando entramos no Cristal?)",
  ui_story_5053_50530501_14_dialog_content = "(E por que Lady Joshua nos atacar assim? É possível que ela não fosse a verdadeira Joshua?)",
  ui_story_5053_50530501_15_dialog_content = "(Não, ela era <color=#FFB400>uma pessoa real</color>, Exatamente como todos nós. Jakine provou isso usando o Cristal da Memória Eterna.)",
  ui_story_5053_50530501_16_dialog_content = "Eu sou Joshua, o Real Joshua.",
  ui_story_5053_50530501_17_dialog_content = "(A maneira como ela enfatizou sua identidade... o que isso deveria significar?)",
  ui_story_5053_50530501_18_dialog_content = "(Estou tão confuso, mas isso não é importante agora. Se algo realmente está errado com Joshua, como é que vamos voltar?)",
  ui_story_5053_50530501_19_dialog_content = "(Aaah... Tem tanta coisa acontecendo que eu não entendo, e porque eu sou o único aqui?!)",
  ui_story_5053_50530501_20_dialog_content = "<color=#e8d9bb>Cova, pat, cova, pat—</color>",
  ui_story_5053_50530501_21_dialog_content = "Aquele som! É aquele...?",
  ui_story_5053_50530501_22_dialog_content = "Aqui...?",
  ui_story_5053_50530501_23_dialog_content = "Como o Escuro Angel encontrar-nos aqui? Achei que tínhamos resetado tudo!",
  ui_story_5053_50530501_24_dialog_content = "E-Essa é a voz da minha irmã...",
  ui_story_5053_50530501_25_dialog_content = "... Aqui!",
  ui_story_5053_50530501_26_dialog_content = "Noite Branca, proteja-nos!",
  ui_story_5053_50530501_27_dialog_content = "Não perca o foco na batalha, Caleb!",
  ui_story_5053_50530501_28_dialog_content = "Aaaah-!",
  ui_story_5053_50530501_29_dialog_content = "A Lâmina do Soberano!",
  ui_story_5053_50530501_30_dialog_content = "Eu odeio...",
  ui_story_5053_50530501_31_dialog_content = "Ugh!",
  ui_story_5053_50530501_32_dialog_content = "É rápido! Tenha cuidado, Senhor Schwartz!",
  ui_story_5053_50530501_33_dialog_content = "Você está tão desesperado para lutar comigo um contra um?",
  ui_story_5053_50530501_34_dialog_content = "Vou conceder o seu desejo, então.",
  ui_story_5053_50530501_35_dialog_content = "Sch... Schwartz...!",
  ui_story_5053_50530501_36_dialog_content = "Mia e os outros estão lutando contra aquela escuridão Angel de novo... Então conseguimos recomeçar a memória!",
  ui_story_5053_50530501_37_dialog_content = "Eu preciso chegar lá e ajudá-los!",
  ui_story_5053_50530501_38_dialog_content = "Você, aí... Pare.",
  ui_story_5053_50530501_39_dialog_content = "Um guarda? No momento ideal! Olha, eu—",
  ui_story_5053_50530501_40_dialog_content = "Suspeite... Extermine...",
  ui_story_5053_50530501_41_dialog_content = "(Hein? Algo parece errado sobre essas pessoas?)",
  ui_story_5053_50530501_42_dialog_content = "Do que vocês estão falando?",
  ui_story_5053_50530501_43_dialog_content = "Senhora Joshua... alguém... intrusos?",
  ui_story_5053_50530501_44_dialog_content = "Intrusos... Devem capturar... e matar!",
  ui_story_5053_50530501_45_dialog_content = "(Algo está definitivamente errado com suas mentes! Eles são como as pessoas da praça central!)",
  ui_story_5053_50530501_46_dialog_content = "Aaaaah!!!",
  ui_story_5053_50530502_1_dialog_content = "<color=#e8d9bb>Bum!!—</color>",
  ui_story_5053_50530502_2_dialog_content = "Urgh... Tosse, tosse...",
  ui_story_5053_50530502_3_dialog_content = "Pra onde ele foi?",
  ui_story_5053_50530502_4_dialog_content = "Provavelmente fugiu por uma trilha para o lado de fora...",
  ui_story_5053_50530502_5_dialog_content = "Isso foi incrível, Senhor Schwartz!",
  ui_story_5053_50530502_6_dialog_content = "O anjo deve estar ferido, por mais poderoso que seja, e provavelmente não pode ir muito longe.",
  ui_story_5053_50530502_7_dialog_content = "...",
  ui_story_5053_50530502_8_dialog_content = "Você ainda está incomodado com o Dark Angel, Tio?",
  ui_story_5053_50530502_9_dialog_content = "Sua voz... Não importa, minha irmã nunca poderia ser um monstro.",
  ui_story_5053_50530502_10_dialog_content = "Espera, não estamos esquecendo de algo? Oh não, onde está PlayerName?!",
  ui_story_5053_50530502_11_dialog_content = "Ei, você está certo! Onde fez PlayerName correr para?!",
  ui_story_5053_50530502_12_dialog_content = "Oh, aí estão vocês!",
  ui_story_5053_50530502_13_dialog_content = "Ufa... Eu os perdi?",
  ui_story_5053_50530502_14_dialog_content = "Ali... Ali!",
  ui_story_5053_50530502_15_dialog_content = "Mate o intruso!",
  ui_story_5053_50530502_16_dialog_content = "(Merda! Mesmo que eles estejam estúpidos agora, esses guardas ainda são impossíveis de abalar!)",
  ui_story_5053_50530502_17_dialog_content = "Não... Bem ali!",
  ui_story_5053_50530502_18_dialog_content = "(... Espere, já entendi!)",
  ui_story_5053_50530502_19_dialog_content = "<color=#e8d9bb>Baque-</color>",
  ui_story_5053_50530502_20_dialog_content = "(O que é esse carrinho, afinal? Deve ser para o feriado... De qualquer forma, acho que eles não vão me ver aqui.)",
  ui_story_5053_50530502_21_dialog_content = "Lá não... Onde?",
  ui_story_5053_50530502_22_dialog_content = "Aquela rua... Vai...",
  ui_story_5053_50530502_23_dialog_content = "Esses guardas estão agindo de forma estranha. Eles estão atrás de alguém?",
  ui_story_5053_50530502_24_dialog_content = "Não tenho certeza, mas quem iria querer criar problemas em um dia como este? O desfile também vai começar!",
  ui_story_5053_50530502_25_dialog_content = "Mal posso esperar para ver!",
  ui_story_5053_50530502_26_dialog_content = "(Ufa! Finalmente consegui perdê-los...)",
  ui_story_5053_50530502_27_dialog_content = "(De acordo com aquela garota, parece que o desfile ainda não começou.)",
  ui_story_5053_50530502_28_dialog_content = "(Ótimo. Isso me dá algum tempo para organizar meus pensamentos e descobrir meu próximo passo.)",
  ui_story_5053_50530502_29_dialog_content = "(Tenho algumas questões sérias a considerar agora...)",
  ui_story_5053_50530502_30_option_content = "A situação atual",
  ui_story_5053_50530502_31_dialog_content = "(O desfile ainda não começou, e todos deveriam ter visto Lady Joshua por enquanto.)",
  ui_story_5053_50530502_32_dialog_content = "(Isso significa que há dois cenários possíveis agora, os quais dependem <color=#FFB400>se todos se lembram ou não da hora redefinida</color>.)",
  ui_story_5053_50530502_33_dialog_content = "(Se todos ainda se lembram, então eles já devem ter lutado contra Lady Joshua e escapou.)",
  ui_story_5053_50530502_34_dialog_content = "(Se for esse o caso, os outros devem estar procurando por mim agora. Ainda não estou muito familiarizado com Lumopolis, então devo apenas manter minha cabeça baixa e esperar que eles me encontrem.)",
  ui_story_5053_50530502_35_dialog_content = "(Mas se ninguém se lembra do tempo reiniciado, provavelmente caiu na armadilha de Joshua...)",
  ui_story_5053_50530502_36_dialog_content = "(Se assim for, tudo deve acontecer exatamente como antes da redefinição. Jakine ficará para trás e os outros seguirão para a praça central.)",
  ui_story_5053_50530502_37_dialog_content = "(Acontece que estou bem perto da praça também. Parece que minha melhor aposta é sentar aqui e esperar que todos cheguem.)",
  ui_story_5053_50530502_38_dialog_content = "(Mas então há Jakine... Droga! Não poderemos resgatá-la até que os outros cheguem aqui!)",
  ui_story_5053_50530502_39_option_content = "A memória\"",
  ui_story_5053_50530502_40_dialog_content = "(De acordo com Jakine, usar adivinhação por qualquer motivo requer um <color=#FFB400>cumprimento estrito de suas regras</color>.)",
  ui_story_5053_50530502_41_dialog_content = "(Durante a primeira reinicialização, Jakine continuou nos dizendo para <color=#FFB400>segure firme nas mãos um do outro</color>.)",
  ui_story_5053_50530502_42_dialog_content = "(Joshua também disse que essa era a razão pela qual ela conseguia se lembrar dos eventos da primeira reinicialização. Foi porque ela estava conosco quando aconteceu.)",
  ui_story_5053_50530502_43_dialog_content = "(Isso significa que ela conseguiu segurar nossas mãos sem que percebêssemos?)",
  ui_story_5053_50530502_44_dialog_content = "(Durante a segunda reinicialização, os únicos segurando o Cristal da Memória Eterna foram Jakine e eu.)",
  ui_story_5053_50530502_45_dialog_content = "(Isso significaria Joshua e os outros não lembram do segundo reset, certo?)",
  ui_story_5053_50530502_46_dialog_content = "(Jakine e eu deveria ser o único que se lembra de tudo o que aconteceu desde que chegamos aqui...)",
  ui_story_5053_50530502_47_dialog_content = "(Ou pelo menos espero que sim.)",
  ui_story_5053_50530502_48_option_content = "O dragão, os soldados e as Trevas Angel",
  ui_story_5053_50530502_49_dialog_content = "(Qual foi o problema com aqueles guardas agora? Por que eles estavam tentando me capturar?)",
  ui_story_5053_50530502_50_dialog_content = "(Eles eram tão loucos quanto as pessoas da praça central. É como se eles tivessem contraído alguma doença misteriosa... Ou eles estavam sendo controlados mentalmente.)",
  ui_story_5053_50530502_51_dialog_content = "(Dado o quão determinados eles estavam em me caçar, eu diria que eles estavam tentando me manter separado dos outros. Eles continuaram me perseguindo, me forçando a deixar a mansão.)",
  ui_story_5053_50530502_52_dialog_content = "(Não posso usar meus poderes psíquicos dentro do Cristal da Memória Eterna, então não tinha como saber o que estava acontecendo lá em cima enquanto todos estavam brigando.)",
  ui_story_5053_50530502_53_dialog_content = "(E acabei perdendo minha chance de reencontrá-los...)",
  ui_story_5053_50530502_54_dialog_content = "(Se Joshua ainda tem suas memórias, então ela deve ter enviado aqueles soldados para me silenciar.)",
  ui_story_5053_50530502_55_dialog_content = "(Mas se ela não o fizer, então ela deve ter ordenado que eles simplesmente matassem quaisquer retardatários.)",
  ui_story_5053_50530502_56_dialog_content = "(Assim como a primeira vez que nos separamos de Jakine.)",
  ui_story_5053_50530502_57_dialog_content = "(Lutando contra as Trevas Angel deve fazer parte do plano dela também. Dessa forma, ela pode nos separar e acabar com Jakine!)",
  ui_story_5053_50530502_58_dialog_content = "(Neste ponto, fica claro que os guardas que me perseguiram estão trabalhando para ela...)",
  ui_story_5053_50530502_59_dialog_content = "(Provavelmente é seguro presumir que as pessoas malucas da praça e aquele dragão negro também estão sob seu controle.)",
  ui_story_5053_50530502_60_dialog_content = "(O que significa que tudo o que passamos desde a primeira reinicialização fazia parte do plano dela ... Que assustador.)",
  ui_story_5053_50530502_61_dialog_content = "(Mas e quanto ao Escuro Angel? Qual é a conexão dela Joshua?)",
  ui_story_5053_50530502_62_dialog_content = "(Os dois estão trabalhando juntos? Ou há mais na história do que isso...?)",
  ui_story_5053_50530502_63_dialog_content = "(Simplesmente não tenho informações suficientes para trabalhar agora.)",
  ui_story_5053_50530502_64_dialog_content = "(Suspiro ... tudo o que foi dito, sentar aqui e esperar pelos outros ainda é meu melhor curso de ação.)",
  ui_story_5053_50530502_65_dialog_content = "(Vou contar a verdade a todos assim que me encontrarem, para que possamos ir salvar Jakine...)",
  ui_story_5053_50530502_66_dialog_content = "(Só espero que estejam todos bem!)",
  ui_story_5053_50530601_1_dialog_content = "Então você está dizendo...",
  ui_story_5053_50530601_2_dialog_content = "Podemos destruir a Escuridão Angel e traga senhora Joshua com a gente fora daqui....",
  ui_story_5053_50530601_3_dialog_content = "... ou o escuro Angel nos mata e fica solto no mundo real?",
  ui_story_5053_50530601_4_dialog_content = "Isso é correto, sim.",
  ui_story_5053_50530601_5_dialog_content = "...",
  ui_story_5053_50530601_6_dialog_content = "Entendo perfeitamente nosso plano de fuga, mas...",
  ui_story_5053_50530601_7_dialog_content = "Onde é PlayerName? Estou realmente começando a me preocupar com ele.",
  ui_story_5053_50530601_8_dialog_content = "Ele está longe de nós há muito tempo. Algo deve ter acontecido com ele!",
  ui_story_5053_50530601_9_dialog_content = "Também não tenho certeza de sua situação atual, mas não se preocupe, enviarei uma equipe de guardas para procurá-lo.",
  ui_story_5053_50530601_10_dialog_content = "Estamos ficando sem tempo. Se quisermos escapar deste lugar com segurança, a prioridade é derrotar aquele monstro.",
  ui_story_5053_50530601_11_dialog_content = "Então vamos caçar aquele Dark Angel!",
  ui_story_5053_50530601_12_dialog_content = "Não, Jakine. Você precisa ficar aqui comigo.",
  ui_story_5053_50530601_13_dialog_content = "Huh? Mas como assim? Minha bola de cristal também é muito útil em uma luta!",
  ui_story_5053_50530601_14_dialog_content = "Sim, eu sei, mas você opera o Cristal.",
  ui_story_5053_50530601_15_dialog_content = "Se os outros se machucarem, sempre podemos voltar no tempo para restaurar tudo.",
  ui_story_5053_50530601_16_dialog_content = "Mas se alguma coisa acontecesse com você, seria irreversível.",
  ui_story_5053_50530601_17_dialog_content = "E-Se você diz...",
  ui_story_5053_50530601_18_dialog_content = "Mãe? I-Se você e Jakine vai ficar aqui, então Carleen deveria voltar também.",
  ui_story_5053_50530601_19_dialog_content = "Não quero que ela e papai se sintam sozinhos sem nós lá.",
  ui_story_5053_50530601_20_dialog_content = "Muito bem. Vou pedir a um guarda que a chame de volta ao quarto para descansar um pouco.",
  ui_story_5053_50530601_21_dialog_content = "Você não a quer aqui conosco, mãe? Ela está ansiosa por esse dia há tanto tempo, por que mandá-la de volta para o quarto sozinha?",
  ui_story_5053_50530601_22_dialog_content = "Ela não vai se sentir mal se perder o desfile...?",
  ui_story_5053_50530601_23_dialog_content = "Meu doce Vonnie... Nada disso é real. O mundo dentro do Cristal da Memória Eterna nada mais é do que uma ilusão.",
  ui_story_5053_50530601_24_dialog_content = "Devemos seguir o curso predeterminado dos eventos. Não deixe que preocupações desnecessárias o distraiam de seu objetivo.",
  ui_story_5053_50530601_25_dialog_content = "Ai...",
  ui_story_5053_50530601_26_dialog_content = "Minha irmã está certa, Mia. Isso tudo é uma fantasia, então não deixe suas emoções levarem a melhor sobre você.",
  ui_story_5053_50530601_27_dialog_content = "A-Tudo bem. Desculpa por ser tão imaturo...",
  ui_story_5053_50530601_28_dialog_content = "...",
  ui_story_5053_50530601_29_dialog_content = "Joshua faz um ponto válido. A segurança de todos deve ser nossa maior prioridade, e é por isso que Caleb também deve ficar aqui.",
  ui_story_5053_50530601_30_dialog_content = "vou procurar PlayerName eu mesmo. Por enquanto, todos os outros devem ficar juntos.",
  ui_story_5053_50530601_31_dialog_content = "Isso não será necessário. Uma equipe de guardas pode encontrar PlayerName com a mesma rapidez, se não mais.",
  ui_story_5053_50530601_32_dialog_content = "Além disso, precisamos da força de todos se quisermos ter uma chance contra aquele monstro.",
  ui_story_5053_50530601_33_dialog_content = "Acho que você sabe tão bem quanto eu qual desses assuntos é mais importante. Use seu bom senso, Daniel.",
  ui_story_5053_50530601_34_dialog_content = "Heh, seu julgamento é tão afiado como sempre, Joshua. Devo dizer que isso realmente me leva de volta aos nossos velhos tempos.",
  ui_story_5053_50530601_35_dialog_content = "...",
  ui_story_5053_50530601_36_dialog_content = "Este é realmente um bom momento para nostalgia, vocês dois? Ainda estamos correndo contra o relógio.",
  ui_story_5053_50530601_37_dialog_content = "De qualquer forma, sou perfeitamente capaz de avaliar as opções por mim mesmo.",
  ui_story_5053_50530601_38_dialog_content = "Vamos lá, Mia.",
  ui_story_5053_50530601_39_dialog_content = "S-Sim, padre.",
  ui_story_5053_50530601_40_dialog_content = "O que há com aquele homem, agindo tão estranhamente de repente?!",
  ui_story_5053_50530601_41_dialog_content = "...",
  ui_story_5053_50530601_42_dialog_content = "é algo sobre Joshua incomodando-te, Mia?",
  ui_story_5053_50530601_43_dialog_content = "Ah! Hum, bem... M-Talvez um pouco...",
  ui_story_5053_50530601_44_dialog_content = "Provavelmente sou só eu, mas... depois de ficar longe dela por tanto tempo, mamãe parece um tanto estranha.",
  ui_story_5053_50530601_45_dialog_content = "Diga-me, que tipo de pessoa é Joshua para você?",
  ui_story_5053_50530601_46_dialog_content = "M-Mãe é... Mãe é a pessoa mais gentil e paciente que já conheci, e ela ama crianças mais do que tudo.",
  ui_story_5053_50530601_47_dialog_content = "Sim o Joshua em meu coração também está uma mulher calorosa e bondosa, uma das pessoas mais firmes e sinceras que já conheci.",
  ui_story_5053_50530601_48_dialog_content = "Pai...!",
  ui_story_5053_50530601_49_dialog_content = "Acredite em si mesmo, Mia. E acredite na linda imagem de sua mãe que você guarda no coração.",
  ui_story_5053_50530601_50_dialog_content = "Acredite em mim?",
  ui_story_5053_50530601_51_dialog_content = "Apesar de sua falta de jeito habitual, você mostrou um lado mais forte e corajoso de si mesmo ao longo desta provação.",
  ui_story_5053_50530601_52_dialog_content = "Acho que é hora de aceitar que você cresceu.",
  ui_story_5053_50530601_53_dialog_content = "De agora em diante, prometo respeitar suas opiniões em vez de dizer como se sentir.",
  ui_story_5053_50530601_54_dialog_content = "Não há necessidade de hesitar mais, Mia. Se tem a ver com sua mãe, ou Carleen, ou qualquer outra coisa...",
  ui_story_5053_50530601_55_dialog_content = "Faça o que achar certo e faça-o com coragem. Sempre terei fé em você.",
  ui_story_5053_50530601_56_dialog_content = "(O Pai está... me encorajando?)",
  ui_story_5053_50530601_57_dialog_content = "(Eu nunca o ouvi dizer algo assim antes. É uma sensação... legal.)",
  ui_story_5053_50530601_58_dialog_content = "Obrigado pai. Prometo ser mais decidida a partir de agora.",
  ui_story_5053_50530601_59_dialog_content = "Estarei de prontidão para vigiar, como planejamos. Se eu vir algum sinal do Escuro Angel, vou avisar a todos.",
  ui_story_5053_50530601_60_dialog_content = "Bom. Esteja em guarda, Mia.",
  ui_story_5053_50530601_61_dialog_content = "(Mia deve estar seguro lá por enquanto. PlayerName, por outro lado... Onde ele poderia estar agora?)",
  ui_story_5053_50530601_62_dialog_content = "(Sua ausência parece extremamente suspeita agora, mas por quê...?)",
  ui_story_5053_50530601_63_dialog_content = "Por aqui...",
  ui_story_5053_50530601_64_dialog_content = "... Aqui!",
  ui_story_5053_50530601_65_dialog_content = "Essa voz...",
  ui_story_5053_50530601_66_dialog_content = "Sch... Schwartz...!!!",
  ui_story_5053_50530601_67_dialog_content = "Aaaaaaaah!!!",
  ui_story_5053_50530601_68_dialog_content = "Então é aqui que você esteve.",
  ui_story_5053_50530601_69_dialog_content = "Bom. Enquanto você estiver aqui, ninguém mais estará em perigo.",
  ui_story_5053_50530601_70_dialog_content = "Machuca! Morra, morra!!!",
  ui_story_5053_50530601_71_dialog_content = "Você não vai me enganar se passando por Joshua.",
  ui_story_5053_50530701_1_dialog_content = "Urgh... Aaaaah!",
  ui_story_5053_50530701_2_dialog_content = "(Sem Mia ou Caleb aqui, parece que estamos empatados. Infelizmente, esses Eclipsites estão inclinando a balança ligeiramente a seu favor.)",
  ui_story_5053_50530701_3_dialog_content = "\"Noite Branca, proteja-nos!\"",
  ui_story_5053_50530701_4_dialog_content = "Eu diria que chegamos a um impasse. Você está satisfeito agora?",
  ui_story_5053_50530701_5_dialog_content = "Sch... Schwartz...!",
  ui_story_5053_50530701_6_dialog_content = "Te odeio...!",
  ui_story_5053_50530701_7_dialog_content = "Por que...",
  ui_story_5053_50530701_8_dialog_content = "Isso machuca muito! Por que... Por que... me trair?!",
  ui_story_5053_50530701_9_dialog_content = "Você disse... Construímos... futuro juntos! Você prometeu...!",
  ui_story_5053_50530701_10_dialog_content = "Então, por que... sacrificar... família?!",
  ui_story_5053_50530701_11_dialog_content = "A dor... é insuportável!!!",
  ui_story_5053_50530701_12_dialog_content = "O que você tá dizendo?",
  ui_story_5053_50530701_13_dialog_content = "Se ao menos... Se ao menos eu soubesse...",
  ui_story_5053_50530701_14_dialog_content = "Eu nunca... amaria...",
  ui_story_5053_50530701_15_dialog_content = "E... escolhi você!!!",
  ui_story_5053_50530701_16_dialog_content = "?!",
  ui_story_5053_50530701_17_dialog_content = "Joshua...?!",
  ui_story_5053_50530701_18_dialog_content = "Mas como isso poderia ser?",
  ui_story_5053_50530701_19_dialog_content = "...!!!",
  ui_story_5053_50530701_20_dialog_content = "Ahh...! m... Mia... perigo...",
  ui_story_5053_50530701_21_dialog_content = "Onde você pensa que está indo?!",
  ui_story_5053_50530701_22_dialog_content = "Graah—!",
  ui_story_5053_50530701_23_dialog_content = "Saia do meu caminho, criaturas nojentas!",
  ui_story_5053_50530701_24_dialog_content = "(Jovem Schwartz acabou de terminar seu discurso, o que significa que o duelo está prestes a começar.)",
  ui_story_5053_50530701_25_dialog_content = "(Se tudo correr como esperado, o dragão aparecerá logo e o povo entrará em pânico, junto com os guardas...)",
  ui_story_5053_50530701_26_dialog_content = "(Quando isso acontecer, posso aproveitar o caos e correr para o estande! Tenho que me encontrar com os outros e contar a eles sobre Joshua antes que seja tarde!)",
  ui_story_5053_50530701_27_dialog_content = "Rugido-!",
  ui_story_5053_50530701_28_dialog_content = "Aaaaah!!!",
  ui_story_5053_50530701_29_dialog_content = "O-O que é isso?!",
  ui_story_5053_50530701_30_dialog_content = "Correr! Me ajude!!!",
  ui_story_5053_50530701_31_dialog_content = "Tudo bem! Agora é minha chance de procurar o Senhor Schwartz e os outros-",
  ui_story_5053_50530701_32_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5053_50530701_33_dialog_content = "Uau...! O-O que foi isso?!",
  ui_story_5053_50530701_34_dialog_content = "Rugido-!",
  ui_story_5053_50530701_35_dialog_content = "<color=#e8d9bb>BUM!</color>",
  ui_story_5053_50530701_36_dialog_content = "Aaaah...! Urg!!!",
  ui_story_5053_50530701_37_dialog_content = "O escuro Angel?! O que está acontecendo?!",
  ui_story_5053_50530701_38_dialog_content = "O que ela está fazendo no céu? Ela está bloqueando o ataque do dragão?",
  ui_story_5053_50530701_39_dialog_content = "Um dragão voador?!",
  ui_story_5053_50530701_40_dialog_content = "Viva o dragão! Viva o dragão!!!",
  ui_story_5053_50530701_41_dialog_content = "Casa Kartima? Então eles são os traidores o tempo todo?",
  ui_story_5053_50530701_42_dialog_content = "Que ousadia da parte deles mostrar suas verdadeiras cores em um momento como este.",
  ui_story_5053_50530701_43_dialog_content = "(Mas o que é aquele outro monstro no céu...?)",
  ui_story_5053_50530701_44_dialog_content = "S-Irmã! O que está acontecendo?",
  ui_story_5053_50530701_45_dialog_content = "Atrás de mim, Carleen!",
  ui_story_5053_50530701_46_dialog_content = "(é o escuro Angel! Mas por que ela está aqui?)",
  ui_story_5053_50530701_47_dialog_content = "O que diabos é...?!",
  ui_story_5053_50530701_48_dialog_content = "Verônica! Carleen! Fique atrás!",
  ui_story_5053_50530701_49_dialog_content = "<color=#e8d9bb>Esmagar-!</color>",
  ui_story_5053_50530701_50_dialog_content = "(Ela foi atingida pelas chamas do dragão! Não, espere... Parece que ela está bloqueando seus ataques!)",
  ui_story_5053_50530701_51_dialog_content = "Mas por que ela...",
  ui_story_5053_50530701_52_dialog_content = "Veronica, parece que ela está nos ajudando a afastar o dragão!",
  ui_story_5053_50530701_53_dialog_content = "D-ela perdeu a consciência?",
  ui_story_5053_50530701_54_dialog_content = "O escuro Angel... Eu não entendo...",
  ui_story_5053_50530701_55_dialog_content = "Mia!!!",
  ui_story_5053_50530701_56_dialog_content = "Mia! Você está bem?!",
  ui_story_5053_50530701_57_dialog_content = "PlayerName? Estou bem, não se preocupe! Onde você esteve todo esse tempo?",
  ui_story_5053_50530701_58_dialog_content = "O-Aqui...!",
  ui_story_5053_50530701_59_dialog_content = "Mate... Mate o intruso!",
  ui_story_5053_50530701_60_dialog_content = "Droga! Não eles de novo!",
  ui_story_5053_50530701_61_dialog_content = "Qual é o problema com esses guardas?!",
  ui_story_5053_50530701_62_dialog_content = "Viva o dragão! Viva o dragão!!!",
  ui_story_5053_50530701_63_dialog_content = "Ataque!",
  ui_story_5053_50530701_64_dialog_content = "Olhe, PlayerName! Os rebeldes também estão se juntando à luta!",
  ui_story_5053_50530701_65_dialog_content = "Vou ter que explicar as coisas mais tarde, Mia. Agora, precisamos nos preparar para a luta!",
  ui_story_5053_50530701_66_dialog_content = "Não importa quantos monstros voadores ou escória traidora decidam mostrar seus rostos hoje! Em nome da casa Schwartz, todos vocês serão punidos por arruinar este dia!",
  ui_story_5053_50530701_67_dialog_content = "Rugido!!!",
  ui_story_5053_50530701_68_dialog_content = "Tome cuidado! Deixe o escuro Angel sozinho por enquanto.",
  ui_story_5053_50530701_69_dialog_content = "Nosso inimigo é diferente de antes. Não espere derrotá-lo tão facilmente.",
  ui_story_5053_50530701_70_dialog_content = "E quem pode ser voce...?",
  ui_story_5053_50530701_71_dialog_content = "Apenas concentre seus ataques no dragão e me ajude a derrubá-lo!",
  ui_story_5053_50530701_72_dialog_content = "Hmph. Mesmo um dragão voador não é páreo para mim.",
  ui_story_5053_50530701_73_dialog_content = "Luz da Noite Branca!",
  ui_story_5053_50530701_74_dialog_content = "Rugido-!!!",
  ui_story_5053_50530701_75_dialog_content = "O que?! Perfurei sua garganta, mas curou quase instantaneamente!!",
  ui_story_5053_50530701_76_dialog_content = "Regeneração rápida... ou algum tipo de invulnerabilidade.",
  ui_story_5053_50530701_77_dialog_content = "Mas como? Quem poderia ter concedido esse tipo de poder a ele? Isso poderia ser obra de Mime?",
  ui_story_5053_50530701_78_dialog_content = "...",
  ui_story_5053_50530701_79_dialog_content = "Em sua guarda! Está se preparando para atacar novamente!",
  ui_story_5053_50530801_1_dialog_content = "Huff... puff...",
  ui_story_5053_50530801_2_dialog_content = "Mate... Mate os intrusos... Mate todos eles!",
  ui_story_5053_50530801_3_dialog_content = "Ahhh! Mate todos!!!",
  ui_story_5053_50530801_4_dialog_content = "Besteira! Por que mais e mais desses guardas malucos estão aparecendo?! Você ainda pode lutar, Mia?",
  ui_story_5053_50530801_5_dialog_content = "Esses caras são horríveis... Seus olhos são completamente brancos e seus rostos estão todos contorcidos!",
  ui_story_5053_50530801_6_dialog_content = "Estou bem, mas os números do inimigo só estão crescendo!",
  ui_story_5053_50530801_7_dialog_content = "As pessoas que estavam fugindo agora se juntaram a eles... Até mesmo os rebeldes caídos estão do lado deles!",
  ui_story_5053_50530801_8_dialog_content = "É como uma espécie de praga...",
  ui_story_5053_50530801_9_dialog_content = "Mantenha distância deles, Mia! O que quer que os esteja controlando parece se espalhar por meio de seus ataques!",
  ui_story_5053_50530801_10_dialog_content = "Mas não vamos durar muito mais nesse ritmo...!",
  ui_story_5053_50530801_11_dialog_content = "Isso também faz parte do plano dela? Senhor Schwartz, nós precisamos de ajuda!",
  ui_story_5053_50530801_12_dialog_content = "Papai está muito ocupado lutando contra o dragão!",
  ui_story_5053_50530801_13_dialog_content = "(Pai... O que devo fazer?)",
  ui_story_5053_50530801_14_dialog_content = "Não há necessidade de hesitar mais, Mia. Se tem a ver com sua mãe, ou Carleen, ou qualquer outra coisa...",
  ui_story_5053_50530801_15_dialog_content = "Faça o que achar certo e faça-o com coragem. Sempre terei fé em você.",
  ui_story_5053_50530801_16_dialog_content = "(Acredite em si mesmo, Mia! Confie em seu julgamento!)",
  ui_story_5053_50530801_17_dialog_content = "Hippoca—!",
  ui_story_5053_50530801_18_dialog_content = "<color=#e8d9bb>BUM!</color>",
  ui_story_5053_50530801_19_dialog_content = "S-Tão poderoso!",
  ui_story_5053_50530801_20_dialog_content = "Hippoca! Obrigado... Obrigado por atender meu chamado! Prometo que nunca mais vou te abandonar!",
  ui_story_5053_50530801_21_dialog_content = "Isso foi incrível, Mia! Você matou cada um daqueles guardas infectados de uma só vez!",
  ui_story_5053_50530801_22_dialog_content = "Estou feliz que funcionou! Vamos, vamos ajudar meu pai!",
  ui_story_5053_50530801_23_dialog_content = "Mia... Espere...",
  ui_story_5053_50530801_24_dialog_content = "Suspiro, suspiro, suspiro...",
  ui_story_5053_50530801_25_dialog_content = "V-Veronica...",
  ui_story_5053_50530801_26_dialog_content = "C-Carleen, sua cabeça está sangrando!!",
  ui_story_5053_50530801_27_dialog_content = "Algum daqueles guardas conseguiu feri-lo, Carleen? Isso significa que ela vai...",
  ui_story_5053_50530801_28_dialog_content = "Afaste-se dela, Mia! Os olhos dela estão começando a ficar brancos, assim como os outros!!",
  ui_story_5053_50530801_29_dialog_content = "Venha aqui, Carleen... Apenas abaixe a lança, certo?",
  ui_story_5053_50530801_30_dialog_content = "Por favor?",
  ui_story_5053_50530801_31_dialog_content = "...",
  ui_story_5053_50530801_32_dialog_content = "Verônica... dói...",
  ui_story_5053_50530801_33_dialog_content = "Não tenha medo, Carleen. Abaixe sua arma e deixe-me cuidar de suas feridas, ok?",
  ui_story_5053_50530801_34_dialog_content = "Não! Minha cabeça... dói...!",
  ui_story_5053_50530801_35_dialog_content = "Há uma voz estranha... Fica me dizendo para te matar! Não, eu não vou fazer isso!",
  ui_story_5053_50530801_36_dialog_content = "Eu sei que você não vai, Carleen. Eu vou te proteger, então não tenha medo!",
  ui_story_5053_50530801_37_dialog_content = "Fique atrás!!",
  ui_story_5053_50530801_38_dialog_content = "eu... eu sou Carleen de Schwartz... Filha orgulhosa de House Schwartz, e defensor de Lumópolis...",
  ui_story_5053_50530801_39_dialog_content = "E eu nunca vou machucar ninguém da minha família! Nunca!",
  ui_story_5053_50530801_40_dialog_content = "Ugh! Não quero te machucar, Veronica! É por isso...",
  ui_story_5053_50530801_41_dialog_content = "Tenho que acabar com isso, aqui e agora... Sinto muito, irmã... Adeus.",
  ui_story_5053_50530801_42_dialog_content = "Não faça isso, Carleen! Abaixe sua arma!!",
  ui_story_5053_50530801_43_dialog_content = "Carleen!",
  ui_story_5053_50530801_44_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530801_45_dialog_content = "Ela perfurou seu pescoço com sua própria lança...",
  ui_story_5053_50530801_46_dialog_content = "Carleen... Como você pode...",
  ui_story_5053_50530801_47_dialog_content = "...",
  ui_story_5053_50530801_48_dialog_content = "Não não...!",
  ui_story_5053_50530801_49_dialog_content = "Aaaaaahhhh!!!!",
  ui_story_5053_50530801_50_dialog_content = "Carleen!! Nãooooooo!!!",
  ui_story_5053_50530801_51_dialog_content = "Sair dessa, Mia! Isso não é real, lembra? O Carleen neste mundo é apenas uma ilusão!",
  ui_story_5053_50530801_52_dialog_content = "Eu não quero te perder, Carleen!!! Por favor... não me deixe sozinho... por favor, Carleen...",
  ui_story_5053_50530801_53_dialog_content = "Acalmar, Mia! Você está me ouvindo?! Ei!!",
  ui_story_5053_50530801_54_dialog_content = "(Mia está muito aflita para me ouvir... Não me diga que ela vai perder o controle de novo?!)",
  ui_story_5053_50530801_55_dialog_content = "Waaaaaaa!!!",
  ui_story_5053_50530801_56_dialog_content = "Isso é quente!!!",
  ui_story_5053_50530801_57_dialog_content = "O poder de Mia está prestes a enlouquecer!!",
  ui_story_5053_50530801_58_dialog_content = "...",
  ui_story_5053_50530801_59_dialog_content = "O-O que você pensa que está fazendo...?!",
  ui_story_5053_50530801_60_dialog_content = "Não chore...",
  ui_story_5053_50530801_61_dialog_content = "Não chore... Meu doce, pequeno... Vonnie...",
  ui_story_5053_50530801_62_dialog_content = "Tudo ficará bem...",
  ui_story_5053_50530801_63_dialog_content = "Ah...",
  ui_story_5053_50530801_64_dialog_content = "Escolha uma rosa... só para o meu bebê... ♪",
  ui_story_5053_50530801_65_dialog_content = "A brisa em seu rosto... seu sorriso é tudo que eu preciso... ♪",
  ui_story_5053_50530801_66_dialog_content = "Escolha um buquê de rosas... para meu querido pai e minha mãe... ♪",
  ui_story_5053_50530801_67_dialog_content = "Ainda que o mundo mude... Nosso amor sempre será o mesmo... ♪",
  ui_story_5053_50530801_68_dialog_content = "Vonnie... Olha... É a mamãe...",
  ui_story_5053_50530801_69_dialog_content = "M-Mãe...? Mãe!",
  ui_story_5053_50530801_70_dialog_content = "Waaaaaaaah!!!",
  ui_story_5053_50530801_71_dialog_content = "Mãe! Isso é Carleen... Ela é ...",
  ui_story_5053_50530801_72_dialog_content = "Suas mãos... suas mãos eram tão quentes... e ali estava o sangue dela...",
  ui_story_5053_50530801_73_dialog_content = "Mãe... Por favor...",
  ui_story_5053_50530801_74_dialog_content = "Isso é... apenas um sonho ruim...",
  ui_story_5053_50530801_75_dialog_content = "Meu pequeno Vonnie... Isso é tudo... apenas um pesadelo...",
  ui_story_5053_50530801_76_dialog_content = "Pode chorar... se quiser...",
  ui_story_5053_50530801_77_dialog_content = "Mamãe... está aqui...",
  ui_story_5053_50530801_78_dialog_content = "...",
  ui_story_5053_50530801_79_dialog_content = "Seu abraço caloroso... e aquela canção de ninar agora mesmo...",
  ui_story_5053_50530801_80_dialog_content = "É mesmo você, mãe...",
  ui_story_5053_50530801_81_dialog_content = "Eu senti tanto sua falta...",
  ui_story_5053_50530801_82_dialog_content = "Assim como eu... meu amor...",
  ui_story_5053_50530801_83_dialog_content = "(O escuro Angel... Ela é reconfortante Mia?!)",
  ui_story_5053_50530801_84_dialog_content = "(Mas eu pensei que ela era apenas um monstro irracional! Não, espere ... Joshua é quem disse isso, e nada do que ela diz pode ser confiável.)",
  ui_story_5053_50530801_85_dialog_content = "... Você está bem, Mia? Você ainda consegue ficar de pé?",
  ui_story_5053_50530801_86_dialog_content = "PlayerName... Me desculpe, eu não consegui me controlar agora.",
  ui_story_5053_50530801_87_dialog_content = "Eu não te machuquei, machuquei...?",
  ui_story_5053_50530801_88_dialog_content = "Claro que não! Ver? Estou perfeitamente bem, e parece que você também está bem.",
  ui_story_5053_50530801_89_dialog_content = "Então, qual é o problema com esse Dark Angel? Estou completamente perdido agora...",
  ui_story_5053_50530801_90_dialog_content = "Ela é minha mãe, sem dúvida.",
  ui_story_5053_50530801_91_dialog_content = "Você está dizendo que esta é a verdadeira Lady Joshua...?!",
  ui_story_5053_50530801_92_dialog_content = "Eu sei que é difícil de entender, mas meu coração me diz que ela é minha verdadeira mãe...",
  ui_story_5053_50530801_93_dialog_content = "O outro nos disse que o Dark Angel não tem consciência e só existe para destruir... Mas o abraço dela agora há pouco me disse o contrário.",
  ui_story_5053_50530801_94_dialog_content = "Quanto à Mãe que conhecemos na mansão, sempre senti algo estranho nela...",
  ui_story_5053_50530801_95_dialog_content = "... Não, eu entendo perfeitamente. Na verdade, isso responderia a muitas perguntas.",
  ui_story_5053_50530801_96_dialog_content = "Huh? O que você quer dizer, PlayerName?",
  ui_story_5053_50530801_97_dialog_content = "Não há tempo suficiente para explicar agora. Jakine está em sério perigo e precisamos salvá-la.",
  ui_story_5053_50530801_98_dialog_content = "Eu vou te contar mais no caminho!",
  ui_story_5053_50530801_99_dialog_content = "Jakine? Acho que você não tem nada com que se preocupar. Tio Caleb está com ela, afinal.",
  ui_story_5053_50530801_100_dialog_content = "Caleb está com ela?",
  ui_story_5053_50530801_101_dialog_content = "Isso mesmo. Papai disse a ele para ficar para trás, mas não tenho certeza do porquê.",
  ui_story_5053_50530801_102_dialog_content = "Quaisquer que sejam suas razões, não fará diferença apenas com Caleb lá.",
  ui_story_5053_50530801_103_dialog_content = "O Joshua da mansão está planejando matar cada um de nós. Ela não é confiável.",
  ui_story_5053_50530801_104_dialog_content = "Do que você está falando?!",
  ui_story_5053_50530801_105_dialog_content = "Não é a primeira vez que tudo isso acontece, Mia!",
  ui_story_5053_50530801_106_dialog_content = "!!!",
  ui_story_5053_50530801_107_dialog_content = "Calebe... Perigo...",
  ui_story_5053_50530801_108_dialog_content = "M... Meu irmão... Calebe...",
  ui_story_5053_50530801_109_dialog_content = "Irmão... perigo...",
  ui_story_5053_50530801_110_dialog_content = "Então você está dizendo que outro reset aconteceu depois do primeiro?",
  ui_story_5053_50530801_111_dialog_content = "Então precisamos encontrar meu pai e voltar imediatamente!!",
  ui_story_5053_50530801_112_dialog_content = "Pai!",
  ui_story_5053_50530801_113_dialog_content = "Senhor Schwartz, Calebe e Jakine estão em grave perigo! Depressa, explico tudo no caminho!",
  ui_story_5053_50530801_114_dialog_content = "Sch... Schwartz...",
  ui_story_5053_50530801_115_dialog_content = "... Parece que as coisas são mais complicadas do que eu imaginava.",
  ui_story_5053_50530801_116_dialog_content = "Infelizmente, não tenho como sair daqui agora.",
  ui_story_5053_50530801_117_dialog_content = "O dragão cura imediatamente quaisquer ferimentos infligidos a ele, mesmo os mais graves.",
  ui_story_5053_50530801_118_dialog_content = "Só posso descrever esse traço sinistro como um tipo de invulnerabilidade.",
  ui_story_5053_50530801_119_dialog_content = "Aquele que só existe dentro do mundo criado pelo Cristal da Memória Eterna.",
  ui_story_5053_50530801_120_dialog_content = "Mas como isso poderia ser...?",
  ui_story_5053_50530801_121_dialog_content = "eu acho que o outro Joshua deve ter algo a ver com isso. Senhor Schwartz, você pode continuar afastando o dragão por enquanto?",
  ui_story_5053_50530801_122_dialog_content = "Joshua... Muito bem, então. Vou deixar o resto em suas mãos.",
  ui_story_5053_50530801_123_dialog_content = "Verônica? Por que você não está se abrigando do dragão?! E quem são essas pessoas...?",
  ui_story_5053_50530801_124_dialog_content = "...",
  ui_story_5053_50530801_125_dialog_content = "Pai... Eu tenho algo urgente para fazer na mansão. Por favor, não tente me impedir.",
  ui_story_5053_50530801_126_dialog_content = "Nada poderia ser mais urgente do que nossa situação atual, Veronica.",
  ui_story_5053_50530801_127_dialog_content = "Além do mais, eu o proíbo de se envolver com esses estranhos.",
  ui_story_5053_50530801_128_dialog_content = "Dificilmente nos considero estranhos, Senhor da Cidade, já que lutamos do mesmo lado há algum tempo.",
  ui_story_5053_50530801_129_dialog_content = "Este não é o momento nem o lugar para exigências paternalistas.",
  ui_story_5053_50530801_130_dialog_content = "...",
  ui_story_5053_50530801_131_dialog_content = "Fique tranquilo, como aliados de Veronica, PlayerName e juro protegê-la a todo custo.",
  ui_story_5053_50530801_132_dialog_content = "Você tem a obrigação de proteger o povo de Lumopolis, e eles precisam de você agora mais do que nunca.",
  ui_story_5053_50530801_133_dialog_content = "Suficiente. Minha sócia, Sra. Rot, é mais do que capaz de defender minha família, e minha esposa também não é estranha em combate. Quase não precisamos de proteção externa, muito menos de estranhos.",
  ui_story_5053_50530801_134_dialog_content = "Além disso, não tenho motivos para confiar em um grupo que considera um monstro um deles.",
  ui_story_5053_50530801_135_dialog_content = "...",
  ui_story_5053_50530801_136_dialog_content = "Isso não é nenhum monstro, disso você pode ter certeza. Ela é minha esposa.",
  ui_story_5053_50530801_137_dialog_content = "Wha...?!",
  ui_story_5053_50530801_138_dialog_content = "...!",
  ui_story_5053_50530801_139_dialog_content = "(O pai também acha que ela é a verdadeira mãe!)",
  ui_story_5053_50530801_140_dialog_content = "Ahem... devo dizer, seus gostos são únicos.",
  ui_story_5053_50530801_141_dialog_content = "Então vamos deixar por isso mesmo.",
  ui_story_5053_50530801_142_dialog_content = "Não há tempo a perder. Mia, PlayerName, O resto é com você. Agora vá!",
  ui_story_5053_50530801_143_dialog_content = "Sim!",
  ui_story_5053_50530801_144_dialog_content = "Calebe...",
  ui_story_5053_50530801_145_dialog_content = "Quer vir também, mãe?",
  ui_story_5053_50530801_146_dialog_content = "Proteja... Calebe...",
  ui_story_5053_50530801_147_dialog_content = "Eu entendo. Faremos isso juntos, agora vamos!",
  ui_story_5053_50530901_1_dialog_content = "Como está lá fora, Caleb?",
  ui_story_5053_50530901_2_dialog_content = "Tenho um pressentimento muito ruim sobre aquele rugido que ouvimos antes.",
  ui_story_5053_50530901_3_dialog_content = "Acordado. Por alguma razão, o dragão apareceu muito antes do esperado.",
  ui_story_5053_50530901_4_dialog_content = "A praça central deve estar em completa desordem agora.",
  ui_story_5053_50530901_5_dialog_content = "Então isso não significaria que todos estão em perigo agora?",
  ui_story_5053_50530901_6_dialog_content = "Senhor Schwartz, Mia, e PlayerName, que ainda não apareceu em lugar nenhum...",
  ui_story_5053_50530901_7_dialog_content = "Não se preocupe. Tenho certeza que Daniel pode lidar com tudo.",
  ui_story_5053_50530901_8_dialog_content = "Quanto a nós... Ótimo, você chegou bem na hora.",
  ui_story_5053_50530901_9_dialog_content = "...",
  ui_story_5053_50530901_10_dialog_content = "Ver? Minha irmã sempre foi do tipo que pensa no futuro e se prepara.",
  ui_story_5053_50530901_11_dialog_content = "Você e os outros estão seguros, Jakine. Eu prometo.",
  ui_story_5053_50530901_12_dialog_content = "Tá bom...",
  ui_story_5053_50530901_13_dialog_content = "Agora então, você poderia ser um querido e trancar a porta para nós, Jakine?",
  ui_story_5053_50530901_14_dialog_content = "Ah com certeza! Afinal, até uma simples fechadura pode fazer maravilhas pela nossa segurança!",
  ui_story_5053_50530901_15_dialog_content = "Deixe-me fazer uma pergunta, Caleb. Por que você quer me resgatar?",
  ui_story_5053_50530901_16_dialog_content = "Hum? Porque você é minha irmã, claro! Que irmão não gostaria de ajudar sua própria irmã?",
  ui_story_5053_50530901_17_dialog_content = "Então é por causa do nosso parentesco... é isso?",
  ui_story_5053_50530901_18_dialog_content = "Isso mesmo. O mundo pode mudar ao nosso redor, mas os laços entre nós... Entre você, nosso pai e eu...",
  ui_story_5053_50530901_19_dialog_content = "Esses nunca vão mudar. Não importa quantos anos passem, sempre me sentirei assim.",
  ui_story_5053_50530901_20_dialog_content = "É assim mesmo? Independentemente de seus motivos, devo agradecê-lo por resgatar meu corpo.",
  ui_story_5053_50530901_21_dialog_content = "Você fez bem, Caleb.",
  ui_story_5053_50530901_22_dialog_content = "Joshua...!",
  ui_story_5053_50530901_23_dialog_content = "É verdade que o mundo é um lugar em constante mudança, mas há algumas coisas que nem mesmo o tempo pode mudar...",
  ui_story_5053_50530901_24_dialog_content = "Diga-me, como é Lumópolis depois de doze anos?",
  ui_story_5053_50530901_25_dialog_content = "Nada mudou. Esses aristocratas parasitas são teimosos e desavergonhados como sempre.",
  ui_story_5053_50530901_26_dialog_content = "Depois de engordar na glória de Lumopolis, tudo o que resta é um sistema apodrecido coberto apenas pelo mais fino dos folheados.",
  ui_story_5053_50530901_27_dialog_content = "Entendo... E quanto a House Schwartz?",
  ui_story_5053_50530901_28_dialog_content = "Schwartz? Ele é o mais repugnante de todos.",
  ui_story_5053_50530901_29_dialog_content = "Ele fez tantas promessas a você no passado que nunca poderia cumprir.",
  ui_story_5053_50530901_30_dialog_content = "Ele até jurou que transformaria Lumopolis em um farol de liberdade e igualdade...",
  ui_story_5053_50530901_31_dialog_content = "Nesse ponto, ele poderia lutar contra a aristocracia corrupta até seu último suspiro, e ainda assim nada mudaria.",
  ui_story_5053_50530901_32_dialog_content = "A fraqueza dele também é a razão pela qual sua família foi deixada em frangalhos. Você e suas filhas nunca deveriam ter sofrido como sofreram, e eu o desprezo ainda mais por isso!",
  ui_story_5053_50530901_33_dialog_content = "Posso não saber muito sobre política, mas você parece um pouco radical, Caleb.",
  ui_story_5053_50530901_34_dialog_content = "eu acho senhor Schwartz merece mais crédito do que isso. Mesmo com todos aqueles nobres codgers constantemente conspirando contra ele, ele ainda mantém uma aparência tão honrosa aos olhos do público.",
  ui_story_5053_50530901_35_dialog_content = "O que você sabe sobre o funcionamento interno de Lumopolis, Jakine? A única coisa que você e o resto do mundo podem ver é a chamada \"aparência honrosa\".",
  ui_story_5053_50530901_36_dialog_content = "B-Mas até Rainha Bethlehem pensa... Ugh, deixa pra lá! Só vou conversar com os guardas!",
  ui_story_5053_50530901_37_dialog_content = "E quanto a mim, Calebe? Você me vê como um fracasso em escolher Daniel como meu marido?",
  ui_story_5053_50530901_38_dialog_content = "N-De jeito nenhum! Você foi apenas mais uma vítima das grandiosas mentiras de Schwartz!",
  ui_story_5053_50530901_39_dialog_content = "E se... veja bem, isso é puramente hipotético, mas se você o deixar... Nossa casa estará sempre aberta para você.",
  ui_story_5053_50530901_40_dialog_content = "E se você se cansasse de Lumopolis e sua sujeira, sempre poderíamos morar em outro lugar!",
  ui_story_5053_50530901_41_dialog_content = "Isso não será necessário, Caleb. Não tenho intenção de deixar Lumopolis para apodrecer. Vou mudar esta cidade durante a minha vida, nem que seja a última coisa que eu faça.",
  ui_story_5053_50530901_42_dialog_content = "...",
  ui_story_5053_50530901_43_dialog_content = "Mas você está correto em dizer que Schwartz está além da economia. Perdi toda a esperança nele.",
  ui_story_5053_50530901_44_dialog_content = "Joshua... Você finalmente está disposta a se divorciar dele?!",
  ui_story_5053_50530901_45_dialog_content = "Caleb, restam tão poucas pessoas que estão dispostas a se opor Schwartz.",
  ui_story_5053_50530901_46_dialog_content = "Afinal, parece que nossos esforços para criá-lo não foram em vão.",
  ui_story_5053_50530901_47_dialog_content = "Nosso? Joshua, talvez você esteja falando sobre nosso pai? O que ele tem a ver com isso? E por que diria tal coisa...?",
  ui_story_5053_50530901_48_dialog_content = "Parece que chegou a hora de contar a verdade, Caleb. Guardas, prendam-na.",
  ui_story_5053_50530901_49_dialog_content = "...",
  ui_story_5053_50530901_50_dialog_content = "Ai!!! Ei, o que vocês estão fazendo?!",
  ui_story_5053_50530901_51_dialog_content = "O que você quer dizer com verdade, Joshua? E o que você está fazendo para Jakine??",
  ui_story_5053_50530901_52_dialog_content = "Calebe... <color=#FFB400>Eu não sou sua irmã de sangue</color>.",
  ui_story_5053_50530901_53_dialog_content = "O quê...?",
  ui_story_5053_50530901_54_dialog_content = "Muitos anos atrás, minha família se recusou a se submeter à Câmara Schwartz e seu governo despótico. Como resultado, minha família foi erradicada pelo pai de Daniel, o antigo senhor da cidade.",
  ui_story_5053_50530901_55_dialog_content = "Muitas outras famílias também compartilharam nosso destino. Apenas alguns de nós sobreviveram e eu era apenas uma criança naquela época.",
  ui_story_5053_50530901_56_dialog_content = "Todos nós passamos a desprezar House Schwartz, e juramos nos vingar de cada um deles.",
  ui_story_5053_50530901_57_dialog_content = "Eventualmente, encontrei meu caminho para os Jardins de Lumopolis. Uma família enlutada de nobres que havia perdido sua filha para a tirania de Schwartz me aceitou como um deles.",
  ui_story_5053_50530901_58_dialog_content = "Espere... Uma família enlutada... Quem <color=#FFB400>perderam a filha para Schwartz</color>...",
  ui_story_5053_50530901_59_dialog_content = "Isso mesmo, foi <color=#FFB400>Joshua</color>, sua irmã. Sua irmã de sangue e sua mãe foram mortas há muito tempo.",
  ui_story_5053_50530901_60_dialog_content = "Eles nunca tiveram nenhuma briga com House Schwartz. Eles estavam simplesmente visitando um amigo, um oponente político de Schwartz cuja família havia sido marcada para eliminação.",
  ui_story_5053_50530901_61_dialog_content = "... E Pai, ele sabia disso...?",
  ui_story_5053_50530901_62_dialog_content = "Claro que sim. Seu pai foi quem me pediu para tomar o lugar de sua filha e buscar vingança contra House Schwartz.",
  ui_story_5053_50530901_63_dialog_content = "I-Impossível! Como pode um homem gentil e honesto como meu pai...",
  ui_story_5053_50530901_64_dialog_content = "O ódio pode levar até mesmo as pessoas mais compassivas a fazerem coisas perversas, Caleb.",
  ui_story_5053_50530901_65_dialog_content = "Foi a vingança, não o amor, que nos motivou a criá-lo no homem que você é hoje.",
  ui_story_5053_50530901_66_dialog_content = "Quando a tentativa de assassinato de seu pai terminou em fracasso, ele tirou a própria vida não apenas para nos proteger, mas para proteger as brasas da vingança.",
  ui_story_5053_50530901_67_dialog_content = "Quando vi a sinceridade de Daniel tantos anos atrás, dei a ele uma última chance de mudar de casa. Schwartz e Lumópolis para melhor.",
  ui_story_5053_50530901_68_dialog_content = "Ofereci a ele meu apoio inabalável em sua campanha para se tornar o próximo Lorde da Cidade.",
  ui_story_5053_50530901_69_dialog_content = "Eu disse a mim mesmo que era melhor que o pai dele, que nunca desceria tão baixo a ponto de matar pessoas inocentes, só para fazer do meu jeito.",
  ui_story_5053_50530901_70_dialog_content = "Mas eu estava errado. Daniel era muito incompetente para mudar qualquer coisa, então percebi que era hora de House Schwartz para sofrer nossa ira.",
  ui_story_5053_50530901_71_dialog_content = "Calebe, disponha <color=#FFB400>Jakine</color>.",
  ui_story_5053_50530901_72_dialog_content = "... O que? O que você está dizendo, Joshua?!",
  ui_story_5053_50530901_73_dialog_content = "Eu preciso que Lumina de forasteiros saia daqui. Ainda tenho um propósito a cumprir lá fora.",
  ui_story_5053_50530901_74_dialog_content = "Não, Joshua... Jakine não tem nada a ver com nada disso! Você mesmo disse, não está disposto a matar pessoas inocentes para fazer o que quer!",
  ui_story_5053_50530901_75_dialog_content = "Sua morte é um sacrifício necessário.",
  ui_story_5053_50530901_76_dialog_content = "O que... Você está louco?! O que aconteceu com a doce e gentil Senhora Joshua de antes?!",
  ui_story_5053_50530901_77_dialog_content = "Eu gostaria de perguntar a mesma coisa! Você me criou não por amor, mas por vingança... Nunca ouvi nada mais ridículo na minha vida! Jakine, tem certeza que essa pessoa não é apenas mais uma ilusão?!",
  ui_story_5053_50530901_78_dialog_content = "Ela não é, confie em mim! E também não lancei nenhum feitiço nela!",
  ui_story_5053_50530901_79_dialog_content = "Por quanto tempo você vai continuar ignorando a verdade, Caleb? Você quer que os sacrifícios de sua família sejam em vão?",
  ui_story_5053_50530901_80_dialog_content = "...",
  ui_story_5053_50530901_81_dialog_content = "Não importa, eu posso me livrar Jakine eu mesmo. Parece que falhamos em educá-lo completamente, Caleb.",
  ui_story_5053_50530901_82_dialog_content = "Darei a você uma última chance de provar sua determinação. Quando chegar a hora, você deve eliminar pessoalmente Schwartz, junto com os outros.",
  ui_story_5053_50530901_83_dialog_content = "Argh, me solte! Você está louco se pensa que pode simplesmente matar todos nós!!!",
  ui_story_5053_50530901_84_dialog_content = "Você não tem ninguém para culpar, mas Schwartz. Adeus, enviado de Northland.",
  ui_story_5053_50530901_85_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5053_50530901_86_dialog_content = "... Você tem razão, Joshua. Embora muito de você tenha se tornado desconhecido para mim, não posso negar que você é minha querida e amada irmã.",
  ui_story_5053_50530901_87_dialog_content = "É por isso que devo impedi-lo! Não vou deixar você viver com o arrependimento de ter feito algo tão terrível!",
  ui_story_5053_50530901_88_dialog_content = "Arrependimento? Nunca me arrependi de nada. Escolhi criá-lo no lugar de seu pai covarde para que você herdasse nosso desejo de vingança.",
  ui_story_5053_50530901_89_dialog_content = "Urgh...!",
  ui_story_5053_50530901_90_dialog_content = "No entanto, você escolheu me trair... Assim como todos os outros!!!",
  ui_story_5053_50530901_91_dialog_content = "Não, Joshua... Eu nunca te trairia!",
  ui_story_5053_50530901_92_dialog_content = "Hmph, então você conseguiu me desarmar... Mas truques mesquinhos não vão te salvar agora!",
  ui_story_5053_50530901_93_dialog_content = "Se formos honestos, também tenho uma confissão a fazer. Todos esses anos, eu disse isso Schwartz não era digno de você, mas a verdade é...",
  ui_story_5053_50530901_94_dialog_content = "Eu me ressenti dele! Com todo o meu coração, eu me ressenti daquele homem e dos filhos que você deu a ele porque eles tiraram você de mim! Levaram a única família que me restava neste mundo!",
  ui_story_5053_50530901_95_dialog_content = "Eu não me importo que não sejamos parentes de sangue... Você me criou desde criança até um adulto, e você sempre será minha amada irmã!",
  ui_story_5053_50530901_96_dialog_content = "Parece que você nunca passará de uma criança chorando, desesperada pela atenção de sua irmã. Agora saia do meu caminho!",
  ui_story_5053_50530901_97_dialog_content = "Isso mesmo! E eu nunca vou mudar, não importa o quanto você me ridicularize!",
  ui_story_5053_50530901_98_dialog_content = "Mas eu sabia... eu sabia o quanto você amava seu marido e suas filhas; nada que eu fizesse poderia mudar isso!",
  ui_story_5053_50530901_99_dialog_content = "Eu disse que era tudo encenação!!",
  ui_story_5053_50530901_100_dialog_content = "Eu... me desculpe, Joshua, mas eu me recuso a acreditar nisso.",
  ui_story_5053_50530901_101_dialog_content = "E eu me recuso a deixar você continuar com isso. Eu protegerei sua preciosa família, mesmo ao custo de minha própria vida!",
  ui_story_5053_50530901_102_dialog_content = "Muito bem, então tanto sua vida quanto sua Lumina estão perdidas.",
  ui_story_5053_50530901_103_dialog_content = "Ugh...?!",
  ui_story_5053_50530901_104_dialog_content = "Não... Nããão!! Calebe!!!",
  ui_story_5053_50530901_105_dialog_content = "... Você fez sua escolha.",
  ui_story_5053_50530901_130_dialog_content = "Calebe!!!",
  ui_story_5053_50530901_131_dialog_content = "<color=#e8d9bb>Esmagar-!</color>",
  ui_story_5053_50530901_132_dialog_content = "<size=45>Aaaaaaah—!</size>",
  ui_story_5053_50530901_133_dialog_content = "Argh!",
  ui_story_5053_50530901_134_dialog_content = "Urg-!",
  ui_story_5053_50530901_135_dialog_content = "?!",
  ui_story_5053_50530901_136_dialog_content = "Oh, criatura nojenta, aparecendo numa hora dessas...!",
  ui_story_5053_50530901_138_dialog_content = "Calebe! Apenas espere, por favor!!!",
  ui_story_5053_50530901_139_dialog_content = "C... Calebe...!!",
  ui_story_5053_50530901_140_dialog_content = "Heh... Me matando com um único golpe... Então ainda há alguma misericórdia em seu coração, afinal...",
  ui_story_5053_50530901_141_dialog_content = "Isso não é bom. A ferida é muito profunda, ele está perdendo muito sangue...",
  ui_story_5053_50530901_143_dialog_content = "Está tão escuro... Não consigo ver nada.",
  ui_story_5053_50530901_145_dialog_content = "Não por favor...",
  ui_story_5053_50530901_146_dialog_content = "Joshua...? Isso é você...?",
  ui_story_5053_50530901_147_dialog_content = "Calebe... Calebe!",
  ui_story_5053_50530901_148_dialog_content = "Eu estou bem aqui...",
  ui_story_5053_50530901_149_dialog_content = "Eu... entendo... Tosse, tosse!!!",
  ui_story_5053_50530901_150_dialog_content = "Você... Você largou sua arma, Joshua?",
  ui_story_5053_50530901_151_dialog_content = "Estou tão feliz...",
  ui_story_5053_50530901_152_dialog_content = "...",
  ui_story_5053_50530901_153_dialog_content = "Calebe?! Calebe!!!",
  ui_story_5053_50530901_155_dialog_content = "Por favor... Calebe!!!",
  ui_story_5053_50530901_156_dialog_content = "Não não...!!",
  ui_story_5053_50530901_157_dialog_content = "<size=50>Hraaaaaaaaaaaaa!!!</size>",
  ui_story_5053_50531001_1_dialog_content = "Huff... Huff...",
  ui_story_5053_50531001_2_dialog_content = "você está bem, PlayerName? Podemos parar e descansar se precisar.",
  ui_story_5053_50531001_3_dialog_content = "Estou bem, não se preocupe. Só estou preocupado porque o Dark Angel decolou tão rapidamente agora.",
  ui_story_5053_50531001_4_dialog_content = "Ela esteve conosco o tempo todo, mas de repente ela voou como se sentisse algo errado...",
  ui_story_5053_50531001_5_dialog_content = "Ela fez exatamente a mesma coisa antes, quando sentiu que você estava em perigo. Estou realmente começando a me preocupar Jakine e Calebe.",
  ui_story_5053_50531001_6_dialog_content = "Estamos quase lá! Espero que ainda estejam bem...",
  ui_story_5053_50531001_7_dialog_content = "Mia, Você está certo disto Jakine não se lembra de nada sobre o segundo reset?",
  ui_story_5053_50531001_8_dialog_content = "Estou certo disso. Nenhum de nós se lembrava de ter acontecido... E é por isso que acreditávamos em tudo o que o outro Joshua nos contou.",
  ui_story_5053_50531001_9_dialog_content = "Para ser honesto, ainda estou tendo dificuldade em acreditar na sua própria história, PlayerName...",
  ui_story_5053_50531001_10_dialog_content = "É por isso que... eu preciso ver a verdade por mim mesmo!",
  ui_story_5053_50531001_11_dialog_content = "(Então por que eu me lembro de tudo, mesmo que Jakine não? Isso não faz sentido...)",
  ui_story_5053_50531001_12_dialog_content = "Algo não parece certo. Onde estão todos os guardas?",
  ui_story_5053_50531001_13_dialog_content = "Parece que o chão está tremendo... Mia, olhe!!",
  ui_story_5053_50531001_14_dialog_content = "?!",
  ui_story_5053_50531001_15_dialog_content = "Intrusos! Traidores! Morrer-!",
  ui_story_5053_50531001_16_dialog_content = "Ahhh-!!!",
  ui_story_5053_50531001_17_dialog_content = "Morrer! Morrer! Morrer!",
  ui_story_5053_50531001_18_dialog_content = "Não aqueles guardas malucos de novo!",
  ui_story_5053_50531001_19_dialog_content = "Ahhhh!!! Alguém me salve!!!",
  ui_story_5053_50531001_20_dialog_content = "Foi isso... Jakine?!",
  ui_story_5053_50531001_21_dialog_content = "Os guardas estão atrás dela! Precisamos abrir caminho através dessa multidão, Mia!",
  ui_story_5053_50531001_22_dialog_content = "Há muitos deles! Hipopótamo-",
  ui_story_5053_50531001_23_dialog_content = "Afaste-se, princesa Veronica—!",
  ui_story_5053_50531001_24_dialog_content = "?!?!",
  ui_story_5053_50531001_25_dialog_content = "<color=#e8d9bb>Zuuup...</color>",
  ui_story_5053_50531001_26_dialog_content = "Ugh...!!",
  ui_story_5053_50531001_27_dialog_content = "Aaaaaaahhh!!!",
  ui_story_5053_50531001_28_dialog_content = "(Ms. Blanc?! Isso foi incrível! Ela dançou por toda a multidão de guardas e derrotou todos eles!)",
  ui_story_5053_50531001_29_dialog_content = "Sra. Rot! Atrás de você!",
  ui_story_5053_50531001_30_dialog_content = "Não se preocupe, princesa Veronica.",
  ui_story_5053_50531001_31_dialog_content = "Como membro da Nightwatch, meu dever é impedir que alguém contamine Lumopolis.",
  ui_story_5053_50531001_32_dialog_content = "Ninguém deve perturbar a paz e a ordem de Lumopolis sob minha guarda!",
  ui_story_5053_50531001_33_dialog_content = "Avante, Noite Branca!",
  ui_story_5053_50531001_34_dialog_content = "Eca-!!",
  ui_story_5053_50531001_35_dialog_content = "Yarrgh!!",
  ui_story_5053_50531001_36_dialog_content = "Princesa Verônica, Senhorita Jakine, você está machucado?",
  ui_story_5053_50531001_37_dialog_content = "Eu... estou bem.",
  ui_story_5053_50531001_38_dialog_content = "Você veio bem na hora. Não acho que poderíamos ter vencido sem você, Sra. Rot.",
  ui_story_5053_50531001_39_dialog_content = "O que no mundo está acontecendo, sua alteza? Esses guardas não estavam agindo como rebeldes comuns.",
  ui_story_5053_50531001_40_dialog_content = "Isso é porque eles não são rebeldes! Toda essa bagunça é toda de Joshua—",
  ui_story_5053_50531001_41_dialog_content = "Silêncio, traidor! Graças a Deus você veio, Sra. Rot.",
  ui_story_5053_50531001_42_dialog_content = "Esses assaltantes estavam em conluio com PlayerName e Jakine, junto com o resto de seu grupo traiçoeiro de forasteiros. Eles até conseguiram fazer uma lavagem cerebral em Veronica para se juntar a eles!",
  ui_story_5053_50531001_43_dialog_content = "Ela está longe demais para ser salva agora. Como mãe dela, não poderia estar mais desapontada.",
  ui_story_5053_50531001_44_dialog_content = "Receio não ter escolha agora. Sra. Rot, eu ordeno que você se livre de todos os três.",
  ui_story_5053_50531001_45_dialog_content = "...",
  ui_story_5053_50531001_46_dialog_content = "O que você está dizendo, mãe?! Então PlayerName estava certo o tempo todo...",
  ui_story_5053_50531001_47_dialog_content = "Ouça-me, Sra. Rot! O \"Joshua\"Na sua frente não passa de um impostor! Ainda não sei exatamente o que está acontecendo...",
  ui_story_5053_50531001_48_dialog_content = "Mas, por favor, acredite em mim quando digo que ela não é a Joshua você sempre soube!",
  ui_story_5053_50531001_49_dialog_content = "PlayerName está falando a verdade! Pela minha honra como membro do Schwartz família, posso atestar isso!",
  ui_story_5053_50531001_50_dialog_content = "Você conhece minha mãe melhor do que ninguém! Como ela pode mandar você fazer algo assim?!",
  ui_story_5053_50531001_51_dialog_content = "...",
  ui_story_5053_50531001_52_dialog_content = "Por que você ainda está hesitando? Você esqueceu tudo que eu te ensinei?",
  ui_story_5053_50531001_53_dialog_content = "Um assassino deve obedecer a seu mestre sem questionar. Eles devem estar prontos para pagar qualquer preço para realizar a vontade justa de seu mestre.",
  ui_story_5053_50531001_54_dialog_content = "Você não está deixando suas emoções anularem seu senso de dever, está? Lembre-se, as emoções nada mais são do que obstáculos no caminho para o futuro próspero de Lumopolis.",
  ui_story_5053_50531001_55_dialog_content = "(O quê? Eu não sabia Ms. Blanc era aluno de Joshua?!)",
  ui_story_5053_50531001_56_dialog_content = "... Você está certo, mestre. Tudo o que faço é para o futuro de Lumopolis.",
  ui_story_5053_50531001_57_dialog_content = "O quê...?!",
  ui_story_5053_50531001_58_dialog_content = "A fim de criar um mundo melhor, no qual as crianças possam rir e coexistir em paz e harmonia... eliminarei qualquer obstáculo em meu caminho, mesmo que esse obstáculo seja você.",
  ui_story_5053_50531001_59_dialog_content = "...",
  ui_story_5053_50531001_60_dialog_content = "Quão notavelmente ousado de sua parte apontar sua lâmina para mim. Acho que não deveria me surpreender.",
  ui_story_5053_50531001_61_dialog_content = "Se esta for sua escolha, então você pode morrer aqui com o resto deles!",
  ui_story_5053_50531001_62_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5053_50531001_63_dialog_content = "Ugh—!",
  ui_story_5053_50531001_64_dialog_content = "(Seus ataques são muito rápidos...!)",
  ui_story_5053_50531001_65_dialog_content = "Sra. Rot?!",
  ui_story_5053_50531001_66_dialog_content = "PlayerName! Leve a princesa Veronica e a senhorita Jakine, e corra!!!",
  ui_story_5053_50531001_67_dialog_content = "Não sei se sou forte o suficiente para derrotá-la, então vocês três devem escapar enquanto podem!",
  ui_story_5053_50531001_68_dialog_content = "M-Mas…",
  ui_story_5053_50531001_69_dialog_content = "Poupe seu fôlego! Sua segurança vem antes de tudo, agora vai!",
  ui_story_5053_50531001_70_dialog_content = "... Desculpe! Mia, Jakine, vamos sair daqui!!",
  ui_story_5053_50531001_71_dialog_content = "(Por favor, tenha cuidado, Sra. Rot...!)",
  ui_story_5053_50531002_1_dialog_content = "Lá! Temos mais alguma coisa para bloquear a porta?",
  ui_story_5053_50531002_2_dialog_content = "Receio que não. Essa cadeira era a única que restava.",
  ui_story_5053_50531002_3_dialog_content = "Argh! Isso tudo é muito estranho!!",
  ui_story_5053_50531002_4_dialog_content = "Se o que PlayerName diz é verdade, então já passamos por uma segunda reinicialização.",
  ui_story_5053_50531002_5_dialog_content = "Todos deram as mãos pela primeira vez, então nos lembramos de tudo. É assim que eu sei que fiz certo.",
  ui_story_5053_50531002_6_dialog_content = "Eu estava lá para a segunda reinicialização, mas não retive nenhuma das minhas memórias...",
  ui_story_5053_50531002_7_dialog_content = "Por que voce acha que isso aconteceu, Jakine?",
  ui_story_5053_50531002_8_dialog_content = "... Acho que tenho uma ideia.",
  ui_story_5053_50531002_9_dialog_content = "O Cristal da Memória Eterna deve estar ficando sem Lumina!",
  ui_story_5053_50531002_10_dialog_content = "O quê?!",
  ui_story_5053_50531002_11_dialog_content = "Ugh... Parece que exageramos na luta contra o inimigo.",
  ui_story_5053_50531002_12_dialog_content = "Com tão pouca Lumina sobrando, o Cristal da Memória Eterna não consegue manter todas as suas funções.",
  ui_story_5053_50531002_13_dialog_content = "Mas então, por que você conseguiu manter todas as suas memórias, PlayerName?",
  ui_story_5053_50531002_14_dialog_content = "E agora há dois Joshuas... As coisas ficam cada vez mais loucas!",
  ui_story_5053_50531002_15_dialog_content = "Talvez o Joshua da mansão realmente é um impostor?",
  ui_story_5053_50531002_16_dialog_content = "Estou tão confuso quanto você, mas meu pai ainda está muito ocupado lutando contra o dragão para nos ajudar. Também estou preocupada com ele...",
  ui_story_5053_50531002_17_dialog_content = "Não temos muitas opções agora. Por que não tentamos realizar outra reinicialização?",
  ui_story_5053_50531002_18_dialog_content = "Você está louco?! Se nenhum de nós conseguir manter nossas memórias, você terá que lutar Joshua sozinho!",
  ui_story_5053_50531002_19_dialog_content = "Ela está certa. Você não teria chance contra ela sozinho.",
  ui_story_5053_50531002_20_dialog_content = "Bloquear a porta com todo esse lixo deveria ter nos dado algum tempo. Deixa eu ver o que tem no livro...",
  ui_story_5053_50531002_21_dialog_content = "\"As artes de adivinhação de Northland se originaram em um antigo assentamento auroriano...\" Antigos aurorianos, hmmm...",
  ui_story_5053_50531002_22_dialog_content = "Espere, é isso! As artes da adivinhação foram projetadas e usadas pelos aurorianos, mas PlayerName é um celestita!",
  ui_story_5053_50531002_23_dialog_content = "Isso poderia afetar outras raças de maneira diferente? Afinal, o livro não menciona nenhum não auroriano usando os feitiços.",
  ui_story_5053_50531002_24_dialog_content = "Entendo... Talvez isso também explique por que minhas habilidades psíquicas são muito mais fracas também?",
  ui_story_5053_50531002_25_dialog_content = "Dizer, PlayerName? Você já jogou algum dos jogos da Illumina?",
  ui_story_5053_50531002_26_dialog_content = "Quando você inicia um game over, os personagens perdem todo o seu progresso, mas o jogador ainda se lembra de tudo o que aconteceu.",
  ui_story_5053_50531002_27_dialog_content = "Você está dizendo que aqui, eu sou o jogador?",
  ui_story_5053_50531002_28_dialog_content = "Bingo! É por isso que você não está sujeito às mesmas regras que o resto de nós!",
  ui_story_5053_50531002_29_dialog_content = "É por isso que precisamos planejar tudo perfeitamente se quisermos zerar o tempo novamente.",
  ui_story_5053_50531002_30_dialog_content = "Concordo. Seria muito perigoso para você voltar no tempo novamente sem estar preparado.",
  ui_story_5053_50531002_31_dialog_content = "Acho que você está certo... Vamos planejar as coisas, então.",
  ui_story_5053_50531002_32_dialog_content = "No momento, nossa maior ameaça é Joshua.",
  ui_story_5053_50531002_33_dialog_content = "Quanto ao motivo pelo qual de repente há dois deles, ainda não tenho certeza.",
  ui_story_5053_50531002_34_dialog_content = "É muito confuso referir-se a ambos como Joshua, já que um deles é Dark Angel...",
  ui_story_5053_50531002_35_dialog_content = "Podemos chamar o outro de Demônio Branco!",
  ui_story_5053_50531002_37_dialog_content = "O Demônio Branco... Não quero chamar mamãe por esse nome, mas é uma maneira adequada de descrevê-la como ela é agora.",
  ui_story_5053_50531002_38_dialog_content = "A julgar pelo comportamento e conhecimento do Demônio Branco, é seguro assumir que ela não é uma impostora.",
  ui_story_5053_50531002_39_dialog_content = "Quando uma semente é plantada em um hospedeiro vivo, ela cria uma personalidade dividida... Dadas minhas próprias experiências, posso me relacionar com a situação dela.",
  ui_story_5053_50531002_40_dialog_content = "E assim como Baba Yaga e eu, não há como determinar qual de nós é bom ou mau.",
  ui_story_5053_50531002_41_dialog_content = "Suas ações podem ser extremas às vezes, mas isso não torna Baba Yaga má. PlayerName também sabe disso.",
  ui_story_5053_50531002_42_dialog_content = "É possível que o Escuro Angel e o Demônio Branco são os mesmos?",
  ui_story_5053_50531002_43_dialog_content = "Apesar de seu comportamento assustador, o Dark Angel nos salvou na praça central.",
  ui_story_5053_50531002_44_dialog_content = "Talvez ela apenas tenha problemas para se controlar?",
  ui_story_5053_50531002_45_dialog_content = "Bem, embora ela compartilhe algumas características com Baba Yaga, não acho que você e o Demônio Branco sejam parecidos, Mia.",
  ui_story_5053_50531002_46_dialog_content = "Ela não passa de uma assassina implacável e de coração frio. você está dizendo senhora Joshua tem um lado assim?",
  ui_story_5053_50531002_47_dialog_content = "Eu também não entendo. Mamãe sempre foi uma pessoa gentil e gentil... Nunca vi um pingo de maldade nela.",
  ui_story_5053_50531002_48_dialog_content = "Er, eu poderia ser capaz de adicionar à história aqui.",
  ui_story_5053_50531002_49_dialog_content = "Ela costumava ser uma assassina. Eu ouvi direto da boca dela um tempo atrás...",
  ui_story_5053_50531002_50_dialog_content = "Muitos anos atrás, minha família se recusou a se submeter à Câmara Schwartz e seu governo despótico. Como resultado, minha família foi erradicada pelo pai de Daniel, o antigo Lorde da Cidade.",
  ui_story_5053_50531002_51_dialog_content = "Muitas outras famílias também compartilharam nosso destino. Apenas alguns de nós sobreviveram e eu era apenas uma criança naquela época.",
  ui_story_5053_50531002_52_dialog_content = "Todos nós passamos a desprezar House Schwartz, e juramos nos vingar de cada um deles.",
  ui_story_5053_50531002_53_dialog_content = "Eventualmente, encontrei meu caminho para os Jardins de Lumopolis. Uma família enlutada de nobres que havia perdido sua filha para a tirania de Schwartz me aceitou como um deles.",
  ui_story_5053_50531002_54_dialog_content = "O que...? M-Mas como pode ser isso?! E-Ela é a esposa de Lord Schwartz!!",
  ui_story_5053_50531002_55_dialog_content = "Você não acha que ela pode estar mentindo?",
  ui_story_5053_50531002_56_dialog_content = "Também é difícil para mim imaginar...",
  ui_story_5053_50531002_57_dialog_content = "...",
  ui_story_5053_50531002_58_dialog_content = "Você não acredita nisso, certo Mia?!",
  ui_story_5053_50531002_59_dialog_content = "Na verdade... Faria muito sentido se ela estivesse falando a verdade.",
  ui_story_5053_50531002_60_dialog_content = "Além de ser uma mãe gentil e compassiva, ela também era uma pessoa incrivelmente poderosa.",
  ui_story_5053_50531002_61_dialog_content = "Apesar de seu status elevado como esposa do senhor da cidade, ela nunca perdeu de vista sua moral. Ela abordou tudo com uma mente racional e um coração gentil...",
  ui_story_5053_50531002_62_dialog_content = "Em nossas vidas particulares, ela cuidava de todos nós, inclusive de meu pai. Em público, ela era a parceira perfeita para o senhor da cidade de Lumopolis.",
  ui_story_5053_50531002_63_dialog_content = "Ela nunca foi motivada por riqueza ou poder. Mesmo nas situações mais terríveis, ela sempre sacrificaria seus próprios interesses pelo bem de outras pessoas.",
  ui_story_5053_50531002_64_dialog_content = "Isso não é algo que qualquer nobre seja capaz de fazer.",
  ui_story_5053_50531002_65_dialog_content = "Um passado cruel e trágico, seguido por uma vida inteira de sacrifício e repressão de suas próprias necessidades, sem ter ninguém para entendê-la...",
  ui_story_5053_50531002_66_dialog_content = "O sofrimento de minha mãe foi um milhão de vezes mais doloroso do que o meu.",
  ui_story_5053_50531002_67_dialog_content = "Eu não a culparia se esse Demônio Branco fosse uma manifestação de seu ressentimento.",
  ui_story_5053_50531002_68_dialog_content = "Entendo...",
  ui_story_5053_50531002_69_dialog_content = "Senhora Joshua... Que existência incrível, mas trágica.",
  ui_story_5053_50531002_70_dialog_content = "Mas se nossa teoria é verdadeira, então por que Baba Yaga e eu não nos separamos também?",
  ui_story_5053_50531002_71_dialog_content = "Você está certo, e isso é uma grande diferença entre você e Lady Joshua.",
  ui_story_5053_50531002_72_dialog_content = "Baba Yaga é sua amiga, Mia. Ela está sempre tentando te proteger.",
  ui_story_5053_50531002_73_dialog_content = "É possível que ela não queira se separar de você. Isso explicaria por que não a vimos desde que entramos no mundo do Cristal.",
  ui_story_5053_50531002_74_dialog_content = "Joshua, por outro lado, é exatamente o oposto. Suas duas metades estão completamente em desacordo uma com a outra.",
  ui_story_5053_50531002_75_dialog_content = "V-você acha? Fico aliviado em ouvir isso... Esse tempo todo, pensei que ela só estava com raiva porque troquei de roupa sem consultá-la.",
  ui_story_5053_50531002_76_dialog_content = "Baba Yaga... Quando voltarmos, terei que agradecê-la por ser tão atenciosa...",
  ui_story_5053_50531002_77_dialog_content = "Vamos voltar ao que o Demônio Branco disse antes.",
  ui_story_5053_50531002_78_dialog_content = "Segundo ela, a única forma de escapar sem machucar ninguém... É trazer os dois conosco.",
  ui_story_5053_50531002_79_dialog_content = "Você não acha que ela estava mentindo quando disse isso, acha...?",
  ui_story_5053_50531002_80_dialog_content = "Eu não acho. Afinal, corresponde ao que aconteceu durante a última reinicialização.",
  ui_story_5053_50531002_81_dialog_content = "O problema é que não sabemos se ela ainda tem algo na manga ou não...",
  ui_story_5053_50531002_82_dialog_content = "...",
  ui_story_5053_50531002_83_dialog_content = "Mia?",
  ui_story_5053_50531002_84_dialog_content = "Desculpe, só estou imaginando como será a mamãe quando voltarmos ao mundo real...",
  ui_story_5053_50531002_85_dialog_content = "Ela continuará sofrendo como antes? Ou pior... Será que ela vai virar um Eclipsite?",
  ui_story_5053_50531002_86_dialog_content = "Acho que devemos tentar ser otimistas por enquanto.",
  ui_story_5053_50531002_87_dialog_content = "Aconteça o que acontecer, estaremos todos lá para ajudar. Senhor Schwartz, Calebe, Jakine... e eu também.",
  ui_story_5053_50531002_88_dialog_content = "Com nossa força combinada, devemos ser capazes de lidar com qualquer coisa que surja em nosso caminho.",
  ui_story_5053_50531002_89_dialog_content = "Mas nada vai mudar a menos que saiamos daqui primeiro!",
  ui_story_5053_50531002_90_dialog_content = "... Você está absolutamente correto!",
  ui_story_5053_50531002_91_dialog_content = "Tirar os dois ao mesmo tempo não será fácil. Duvido que o Demônio Branco apareça silenciosamente.",
  ui_story_5053_50531002_92_dialog_content = "Ela também deixou bem claro que odeia seu outro eu e se recusa a se tornar um com ela novamente...",
  ui_story_5053_50531002_93_dialog_content = "Certo, é por isso que ela está planejando matar todos nós.",
  ui_story_5053_50531002_94_dialog_content = "Nossa única escolha é subjugá-la à força e levá-la conosco.",
  ui_story_5053_50531002_95_dialog_content = "Mas com todos aqueles guardas irracionais e um dragão no caminho...",
  ui_story_5053_50531002_96_dialog_content = "O livro diz alguma coisa sobre por que eles estão agindo de forma tão estranha, Jakine?",
  ui_story_5053_50531002_97_dialog_content = "Deixe-me ver... Pronto! \"Quem primeiro ativar um Cristal da Memória Eterna tem o poder de alterar o curso dos eventos até certo ponto.\"",
  ui_story_5053_50531002_98_dialog_content = "... Espere, é isso? Argh, você não poderia explicar um pouco mais, mãe?!",
  ui_story_5053_50531002_99_dialog_content = "Parece que teremos que encontrar a resposta por nós mesmos. Hmmm...",
  ui_story_5053_50531002_100_dialog_content = "O mundo dentro de um Cristal de Memória Eterna é criado e sustentado por <color=#FFB400>água do lago espelho</color> e <color=#FFB400>o Lumina de quem o ativa</color>.",
  ui_story_5053_50531002_101_dialog_content = "<color=#FFB400>Lumina do ativador</color>... Em outras palavras, a Lumina de Joshua! Todo este mundo ilusório é um produto de sua própria Lumina.",
  ui_story_5053_50531002_102_dialog_content = "Ela mencionou que seu poder havia sido dividido, certo?!",
  ui_story_5053_50531002_103_dialog_content = "Certo...",
  ui_story_5053_50531002_104_dialog_content = "Ela também disse que precisava absorver nossa Lumina para se tornar sua própria pessoa!",
  ui_story_5053_50531002_105_dialog_content = "Isso mesmo! Você não vê?!",
  ui_story_5053_50531002_106_dialog_content = "quando a escuridão Angel se separou do Demônio Branco, ela levou metade de seu poder com ela!",
  ui_story_5053_50531002_107_dialog_content = "Quanto à outra metade, acho que ela não perdeu nada! Acho que ela usou para manipular o Cristal da Memória Eterna!",
  ui_story_5053_50531002_108_dialog_content = "Afinal, o dragão e os guardas são produtos da Lumina de Joshua.",
  ui_story_5053_50531002_109_dialog_content = "Isso significa que ela é a única capaz de interferir com eles... Ou, neste caso, infectá-los!",
  ui_story_5053_50531002_110_dialog_content = "Se for esse o caso, o Demônio Branco está mentindo para nós desde o começo!",
  ui_story_5053_50531002_111_dialog_content = "Isso é realmente possível?! Então a Sra. Rot...",
  ui_story_5053_50531002_112_dialog_content = "... Provavelmente está correndo muito perigo agora.",
  ui_story_5053_50531002_113_dialog_content = "Isso é assustador, ela pode ser tão cruel e calculista...",
  ui_story_5053_50531002_114_dialog_content = "Nunca tive medo de mamãe, mas sem seu lado caloroso e gentil...",
  ui_story_5053_50531002_115_dialog_content = "Esse é realmente o tipo de pessoa que ela se tornaria?",
  ui_story_5053_50531002_116_dialog_content = "Portanto, o dragão e as multidões de loucos são provavelmente os peões do Demônio Branco. Derrotá-los deve diminuir sua força.",
  ui_story_5053_50531002_117_dialog_content = "Além disso, temos alguma outra maneira de lutar contra ela - espere!",
  ui_story_5053_50531002_118_dialog_content = "O escuro Angel! Ela estava em paz com o Senhor Schwartz e o resto de sua família, e o Demônio Branco não pode matá-la por conta própria!",
  ui_story_5053_50531002_119_dialog_content = "Se conseguirmos convencê-la a lutar ao nosso lado, teremos uma chance muito maior de vencer!",
  ui_story_5053_50531002_120_dialog_content = "Esse é um esquema estúpido que você tem aí! Eu sempre soube que você tinha um lado imprudente!",
  ui_story_5053_50531002_121_dialog_content = "Mas eu tenho que avisá-lo, PlayerName...",
  ui_story_5053_50531002_122_dialog_content = "O Cristal da Memória Eterna só tem Lumina suficiente para uma reinicialização final.",
  ui_story_5053_50531002_123_dialog_content = "Isso significa que o fracasso não é uma opção. Você tem que ter sucesso, ou estamos perdidos!",
  ui_story_5053_50531002_124_dialog_content = "Eu tenho que ter sucesso... Entendi...",
  ui_story_5053_50531002_125_dialog_content = "PlayerName? Após a reinicialização final, e se você for direto ao Demônio Branco e a expor imediatamente?",
  ui_story_5053_50531002_126_dialog_content = "Whoa ... Isso é ainda mais selvagem do que PlayerName'lado a! Minha impressão sobre você mudou muito desde que chegamos aqui, Mia.",
  ui_story_5053_50531002_127_dialog_content = "S-Sério?",
  ui_story_5053_50531002_128_dialog_content = "Seria extremamente arriscado, sem dúvida.",
  ui_story_5053_50531002_129_dialog_content = "Não tenho como me defender. O Demônio Branco não teria nenhum problema em se livrar de mim.",
  ui_story_5053_50531002_130_dialog_content = "Nenhum de vocês terá suas memórias também, então você pode não acreditar em minhas acusações imediatamente.",
  ui_story_5053_50531002_131_dialog_content = "Você está certo... Tio Caleb teria muita dificuldade em acreditar em seu testemunho.",
  ui_story_5053_50531002_132_dialog_content = "Mas para ser honesto, PlayerName, Acho que você não precisa se preocupar muito com isso.",
  ui_story_5053_50531002_133_dialog_content = "Meu pai é extremamente perspicaz. Ele tem suas suspeitas sobre o Demônio Branco desde que a conhecemos desta vez.",
  ui_story_5053_50531002_134_dialog_content = "Acho que ele pediu ao tio Caleb para ficar para trás para que ele pudesse ver a verdade com seus próprios olhos...",
  ui_story_5053_50531002_135_dialog_content = "É por isso que você deve focar sua atenção no Dark Angel em vez de.",
  ui_story_5053_50531002_136_dialog_content = "Isso soa como Senhor Schwartz...",
  ui_story_5053_50531002_137_dialog_content = "<color=#e8d9bb>Wham! Wham! Wham!</color>",
  ui_story_5053_50531002_138_dialog_content = "O-O que foi isso?!",
  ui_story_5053_50531002_139_dialog_content = "Oh não, os guardas apanharam!",
  ui_story_5053_50531002_140_dialog_content = "Eu vou segurá-los! Jakine, prepare-se para executar a reinicialização final...",
  ui_story_5053_50531002_141_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5053_50531002_142_dialog_content = "Cuidado, Mia!",
  ui_story_5053_50531002_143_dialog_content = "É aquele...?!",
  ui_story_5053_50531002_144_dialog_content = "...",
  ui_story_5053_50531002_145_dialog_content = "Sra. Rot?!",
  ui_story_5053_50531002_146_dialog_content = "Voltam, Mia!",
  ui_story_5053_50531002_147_dialog_content = "... Não.",
  ui_story_5053_50531002_148_dialog_content = "Você deve estar sentindo muita dor agora, Sra. Rot... Assim como Carleen, quando ela lutou até o fim para manter sua sanidade.",
  ui_story_5053_50531002_149_dialog_content = "... Não vou deixar isso acontecer de novo. Eu não vou deixar você sofrer do jeito Carleen sofreu.",
  ui_story_5053_50531002_150_dialog_content = "Vou livrá-lo de sua dor!",
  ui_story_5053_50531002_151_dialog_content = "Venha até mim!",
  ui_story_5053_50531002_152_dialog_content = "—!",
  ui_story_5053_50531002_153_dialog_content = "Mia...",
  ui_story_5053_50531002_154_dialog_content = "Ela está lutando o máximo que pode para nos ganhar algum tempo, Jakine... Vamos começar a reinicialização.",
  ui_story_5053_50531002_155_dialog_content = "Assim que eu acordar, só tenho que encontrar o Escuro Angel, então se esconda daqueles guardas, e então...",
  ui_story_5053_50531002_156_dialog_content = "PlayerName? Suas mãos estão tremendo...",
  ui_story_5053_50531002_157_dialog_content = "...",
  ui_story_5053_50531002_158_dialog_content = "Eu sei que estamos colocando muito em seus ombros agora. Eu ficaria nervoso se tivesse que fazer tudo sozinho também, mas não tenha medo.",
  ui_story_5053_50531002_159_dialog_content = "Tudo vai ficar bem. Nós acreditamos em você, não importa o que aconteça!",
  ui_story_5053_50531002_160_dialog_content = "Jakine...!",
  ui_story_5053_50531002_161_dialog_content = "Certo! Apenas deixe comigo!",
  ui_story_5053_50531002_162_dialog_content = "Reditus, reditus, reditus! Deixe tudo voltar ao que era antes!",
  ui_story_5053_50531002_163_dialog_content = "Abracadabra!",
  ui_story_5053_50531101_0X_dialog_content = "<color=#e8d9bb>Após a terceira reinicialização—</color>",
  ui_story_5053_50531101_1_dialog_content = "Tudo está definido, meu senhor.",
  ui_story_5053_50531101_2_dialog_content = "A carruagem espera do lado de fora e está pronta para partir a qualquer momento.",
  ui_story_5053_50531101_3_dialog_content = "Entendi.",
  ui_story_5053_50531101_4_dialog_content = "Entra na carruagem, Carleen.",
  ui_story_5053_50531101_5_dialog_content = "Eu... eu quero ficar com a mamãe!",
  ui_story_5053_50531101_6_dialog_content = "Jakine... Mia... Devo...",
  ui_story_5053_50531101_7_dialog_content = "Hmmm... Onde estou...?",
  ui_story_5053_50531101_8_dialog_content = "Isso mesmo, Jakine me mandou de volta no tempo de novo!",
  ui_story_5053_50531101_9_dialog_content = "E ali... o eu mais jovem de Lord Schwartz está escoltando Carleen fora daqui.",
  ui_story_5053_50531101_10_dialog_content = "Parece que a redefinição foi bem-sucedida!",
  ui_story_5053_50531101_11_dialog_content = "Tudo bem, as primeiras coisas primeiro...",
  ui_story_5053_50531101_12_dialog_content = "Pessoa suspeita... deve exterminar...",
  ui_story_5053_50531101_13_dialog_content = "Pessoa suspeita... aqui não...",
  ui_story_5053_50531101_14_dialog_content = "Ufa, consegui desviar dos guardas! Isso cuida disso!",
  ui_story_5053_50531101_15_dialog_content = "(Antes da reinicialização, nós três elaboramos um plano de três etapas para nos tirar daqui.)",
  ui_story_5053_50531101_16_dialog_content = "(Primeiro, encontre o Dark Angel e convencê-la a lutar ao nosso lado.)",
  ui_story_5053_50531101_17_dialog_content = "(E então, evite que o dragão e os guardas infectados lancem seu ataque.)",
  ui_story_5053_50531101_18_dialog_content = "(Por fim, derrube o Demônio Branco antes que alguém se machuque ou pior.)",
  ui_story_5053_50531101_19_dialog_content = "(Mia, Jakine...)",
  ui_story_5053_50531101_20_dialog_content = "(Esta é a nossa última reinicialização. Tenho que fazer isso, ou estamos todos condenados.)",
  ui_story_5053_50531101_21_dialog_content = "Pessoa suspeita... exterminar...",
  ui_story_5053_50531101_22_dialog_content = "!!!",
  ui_story_5053_50531101_23_dialog_content = "Aqui não...",
  ui_story_5053_50531101_24_dialog_content = "(Isso foi por pouco... Com base em meus últimos desentendimentos com esses guardas, eles não vão parar de me perseguir até o fim.)",
  ui_story_5053_50531101_25_dialog_content = "(Estou com pouco tempo, força de combate e mobilidade... O que significa que terei que completar todas as três etapas de uma só vez.)",
  ui_story_5053_50531101_26_dialog_content = "(Eu só tenho uma chance nisso!)",
  ui_story_5053_50531102_1_dialog_content = "<color=#e8d9bb>Bum!!!</color>",
  ui_story_5053_50531102_2_dialog_content = "Urgh... Tosse, tosse...",
  ui_story_5053_50531102_3_dialog_content = "Onde foi que o escuro Angel ir?",
  ui_story_5053_50531102_4_dialog_content = "Parece que ela escapou por um caminho externo.",
  ui_story_5053_50531102_5_dialog_content = "Isso foi incrível, Senhor Schwartz!",
  ui_story_5053_50531102_6_dialog_content = "Estou apenas agradecido por ninguém ter se ferido—",
  ui_story_5053_50531102_7_dialog_content = "Oh, aí estão vocês!",
  ui_story_5053_50531102_8_dialog_content = "Mãe... O que você está fazendo aqui? Você não deveria estar assistindo ao desfile?",
  ui_story_5053_50531102_9_dialog_content = "...",
  ui_story_5053_50531102_10_dialog_content = "... Parece que tivemos um convidado indesejado.",
  ui_story_5053_50531102_11_dialog_content = "Estão todos bem?",
  ui_story_5053_50531102_12_dialog_content = "Joshua? B-mas o escuro Angel agora mesmo...",
  ui_story_5053_50531102_13_dialog_content = "Heheh, então meu pequeno gênio também tem seus momentos de confusão.",
  ui_story_5053_50531102_14_dialog_content = "Vocês todos devem estar cansados de sua batalha. Venha para dentro e descanse, certo?",
  ui_story_5053_50531102_15_dialog_content = "Não se preocupe com esse monstro. Vou enviar meus guardas para caçá-lo momentaneamente.",
  ui_story_5053_50531102_16_dialog_content = "Mãe, só um momento, algo não parece certo...",
  ui_story_5053_50531102_17_dialog_content = "Alguém viu PlayerName?",
  ui_story_5053_50531102_18_dialog_content = "Oh sim! Onde é PlayerName? Não o vejo em lugar nenhum.",
  ui_story_5053_50531102_19_dialog_content = "Ele está desaparecido o tempo todo.",
  ui_story_5053_50531102_20_dialog_content = "O quê...",
  ui_story_5053_50531102_21_dialog_content = "Sinto muito, mãe. Precisamos ir encontrar PlayerName antes que ele corra qualquer perigo...",
  ui_story_5053_50531102_22_dialog_content = "Aquece meu coração ver o quanto você se importa com seu amigo, Vonnie... Mas tenho algo muito importante para compartilhar com todos.",
  ui_story_5053_50531102_23_dialog_content = "Vou enviar uma equipe de guardas para procurar PlayerName. Vamos entrar agora, certo?",
  ui_story_5053_50531102_24_dialog_content = "Huh? Um... O-Ok...",
  ui_story_5053_50531102_25_dialog_content = "... É isso?",
  ui_story_5053_50531102_26_dialog_content = "Não é típico de você falar sobre as circunstâncias de vida ou morte de uma pessoa com tanta indiferença.",
  ui_story_5053_50531102_27_dialog_content = "Oh? É isso que você pensa de mim? Uma senhora nobre comum e fraca? DANIEL.",
  ui_story_5053_50531102_28_dialog_content = "...",
  ui_story_5053_50531102_29_dialog_content = "Daniel? Mas Joshua, como você—poderia ser?!",
  ui_story_5053_50531201_1_dialog_content = "Arf, arf...",
  ui_story_5053_50531201_2_dialog_content = "Eu sei que a vi ir por aqui, mas por que não consigo encontrá-la?",
  ui_story_5053_50531201_3_dialog_content = "Sch... wartz...",
  ui_story_5053_50531201_4_dialog_content = "Lá! Atrás daquela caixa!",
  ui_story_5053_50531201_5_dialog_content = "...!!!",
  ui_story_5053_50531201_6_dialog_content = "Espere, eu não quero lutar com você! Caleb e Veronica estão em perigo e precisam da sua ajuda!",
  ui_story_5053_50531201_7_dialog_content = "Ca... Calebe...? Verônica...?",
  ui_story_5053_50531201_8_dialog_content = "Isso mesmo! Seu irmão Caleb e sua filha Veronica!",
  ui_story_5053_50531201_9_dialog_content = "Eles são sua família, não são?",
  ui_story_5053_50531201_10_dialog_content = "Minha família...",
  ui_story_5053_50531201_11_dialog_content = "Sim, sua família! E eles estão em sério perigo agora!",
  ui_story_5053_50531201_12_dialog_content = "Minha família... em perigo...",
  ui_story_5053_50531201_13_dialog_content = "Algo está errado...?",
  ui_story_5053_50531201_14_dialog_content = "<size=50>Minha família... Schwartz!!!</size>",
  ui_story_5053_50531201_15_dialog_content = "H-Huh?! Ei, mantenha-o baixo! Você vai alertar os guardas!",
  ui_story_5053_50531201_16_dialog_content = "(Quando dissemos que Caleb estava em perigo da última vez, ela estava disposta a nos ajudar. Por que ela está com raiva desta vez?!)",
  ui_story_5053_50531201_17_dialog_content = "(É possível que o Escuro Angel só vai ouvir Mia ou alguém de sua família?)",
  ui_story_5053_50531201_18_dialog_content = "Dor...! Muita dor...!",
  ui_story_5053_50531201_19_dialog_content = "Ah, isso não adianta... Estou ficando sem tempo! O que devo fazer?!",
  ui_story_5053_50531201_20_dialog_content = "Não chore...",
  ui_story_5053_50531201_21_dialog_content = "Não chore... Meu doce, pequeno... Vonnie...",
  ui_story_5053_50531201_22_dialog_content = "Tudo ficará bem...",
  ui_story_5053_50531201_23_dialog_content = "Ah...",
  ui_story_5053_50531201_24_dialog_content = "(Preciso acalmá-la de alguma forma. Então, do jeito que os aurorianos fazem para confortar uns aos outros... a única coisa que significa paz e segurança para as Trevas Angel...)",
  ui_story_5053_50531201_25_dialog_content = "(É minha única chance!)",
  ui_story_5053_50531201_26_dialog_content = "Escolha uma rosa... Só para o meu bebê? ♪",
  ui_story_5053_50531201_27_dialog_content = "Algo, algo... A brisa em seu rosto é tudo que eu preciso? ♪",
  ui_story_5053_50531201_28_dialog_content = "...?",
  ui_story_5053_50531201_29_dialog_content = "...",
  ui_story_5053_50531201_30_dialog_content = "Escolha uma rosa...? Para meu querido pai e mãe... ♪",
  ui_story_5053_50531201_31_dialog_content = "Cale-se.",
  ui_story_5053_50531201_32_dialog_content = "Peço desculpas se meu canto é terrível.",
  ui_story_5053_50531201_33_dialog_content = "Eu ouço essa música na rua de vez em quando. É cativante, mas nunca me lembro das palavras.",
  ui_story_5053_50531201_34_dialog_content = "A melodia me escapa na maioria das vezes também.",
  ui_story_5053_50531201_35_dialog_content = "Um membro da Câmara Schwartz não tem o direito de cantar uma canção de Lower Lumopolis.",
  ui_story_5053_50531201_36_dialog_content = "... Por que você se ressente de House Schwartz muito?",
  ui_story_5053_50531201_37_dialog_content = "O ódio até o obrigou a se mascarar e se sacrificar para se aproximar de mim, tornando-se meu amante.",
  ui_story_5053_50531201_38_dialog_content = "Tudo isso, apenas para que você pudesse assassinar meu pai.",
  ui_story_5053_50531201_39_dialog_content = "...",
  ui_story_5053_50531201_40_dialog_content = "Seu ato foi impecável e sua experiência em combate e academia é incomparável.",
  ui_story_5053_50531201_41_dialog_content = "Diga-me, quanto tempo demorou para aprimorar essas habilidades?",
  ui_story_5053_50531201_42_dialog_content = "Cinco anos? Dez anos? Ou talvez... toda a sua vida?",
  ui_story_5053_50531201_43_dialog_content = "Todo o treinamento e preparativos apenas para realizar um único assassinato de alto perfil.",
  ui_story_5053_50531201_44_dialog_content = "A vida de meu pai era realmente digna do ódio em seu coração e no coração de seus conspiradores?",
  ui_story_5053_50531201_45_dialog_content = "Antes que você chegue à conclusão errada, deixe-me esclarecer uma coisa.",
  ui_story_5053_50531201_46_dialog_content = "Digo essas coisas, não apenas em defesa da honra de meu pai... Mas porque não desejo vê-lo consumido pelo ódio.",
  ui_story_5053_50531201_47_dialog_content = "Casa Schwartz é a personificação da opressão e da tirania.",
  ui_story_5053_50531201_48_dialog_content = "Todas as refeições que você faz e todas as roupas que veste estão manchadas com o sangue de suas vítimas.",
  ui_story_5053_50531201_49_dialog_content = "Vítimas, você diz. Eles estão incluindo a verdadeira irmã de Caleb, bem como sua família real?",
  ui_story_5053_50531201_50_dialog_content = "...",
  ui_story_5053_50531201_51_dialog_content = "Isso é apenas especulação da minha parte, pelo menos por enquanto.",
  ui_story_5053_50531201_52_dialog_content = "Sete anos atrás, a mãe de Caleb foi trágica e acidentalmente morta durante uma operação antirrebelde.",
  ui_story_5053_50531201_53_dialog_content = "Irmã dele, Joshua, também esteve presente durante o ataque.",
  ui_story_5053_50531201_54_dialog_content = "No entanto, de alguma forma, como se por algum milagre, ela emergiu como a única sobrevivente da operação... Mas não foi um milagre, foi?",
  ui_story_5053_50531201_55_dialog_content = "Só então, um inteiramente novo \"Joshua\" como você poderia aparecer. Estou enganado até agora?",
  ui_story_5053_50531201_56_dialog_content = "...",
  ui_story_5053_50531201_57_dialog_content = "Nunca compartilhei minhas suspeitas com ninguém, nem contei a ninguém sobre sua presença aqui.",
  ui_story_5053_50531201_58_dialog_content = "Todos presumiram que você simplesmente tinha ido para casa. Eu até disse isso ao seu pai adotivo.",
  ui_story_5053_50531201_59_dialog_content = "Mas, na verdade, você nunca voltou. Seu pai adotivo também nunca mencionou seu desaparecimento.",
  ui_story_5053_50531201_60_dialog_content = "Claramente, ele sabia por que você estava desaparecido.",
  ui_story_5053_50531201_61_dialog_content = "...",
  ui_story_5053_50531201_62_dialog_content = "Porém, em vez de evitar o assunto, ele se aproximou de mim durante a aula e perguntou como estávamos ultimamente.",
  ui_story_5053_50531201_63_dialog_content = "Traçar a morte de seu soberano é um crime punível com a morte mais horrível, mas naquele momento ele estava mais preocupado com sua segurança do que com a dele.",
  ui_story_5053_50531201_64_dialog_content = "Em vez de escolher o medo ou o ódio, aquele velho sábio gentil escolheu você.",
  ui_story_5053_50531201_65_dialog_content = "Então, por favor... Pelo bem dele, por favor, abandone seu plano de assassinar meu pai.",
  ui_story_5053_50531201_66_dialog_content = "Se o fizer, prometo me comportar como se nada tivesse acontecido e devolvê-lo à sua família.",
  ui_story_5053_50531201_67_dialog_content = "Me poupe do teatro, Schwartz. Eu não vou ouvir, e se ele estivesse aqui agora... Ele também não ouviria.",
  ui_story_5053_50531201_68_dialog_content = "Estamos ligados por nosso ódio mútuo por House Schwartz. Sacrificar-nos em busca de nossas ambições é a maior honra.",
  ui_story_5053_50531201_69_dialog_content = "Hum? Eu não disse que estava apenas fazendo conjecturas? Eu nunca tive nenhuma evidência para provar minhas afirmações.",
  ui_story_5053_50531201_70_dialog_content = "Mas agora que você admitiu ter conspirado contra House Schwartz com o pai de Caleb...",
  ui_story_5053_50531201_71_dialog_content = "Hahaha, parece que esta rodada pertence a mim, Joshua!",
  ui_story_5053_50531201_72_dialog_content = "...",
  ui_story_5053_50531201_73_dialog_content = "Ahem, perdoe-me por esse pouco de regozijo. Eu só queria aliviar um pouco o clima...",
  ui_story_5053_50531201_74_dialog_content = "Em todo caso, posso compreender sua desconfiança.",
  ui_story_5053_50531201_75_dialog_content = "Meu pai sempre foi um homem implacável e determinado. Quando se tratava de silenciar seus inimigos... Ele faria isso indiscriminadamente, ao invés de deixar uma única pessoa escapar.",
  ui_story_5053_50531201_76_dialog_content = "Ele alegou que suas ações eram necessárias para estabelecer uma frente unificada.",
  ui_story_5053_50531201_77_dialog_content = "Todos devem respeitar a Casa Schwartz, e todos devem obedecer a um único governante.",
  ui_story_5053_50531201_78_dialog_content = "Quando cada cidadão for leal a um único líder confiável, os gananciosos e os perversos não terão onde se esconder.",
  ui_story_5053_50531201_79_dialog_content = "E uma vez que sua sujeira foi expurgada da cidade, Lumopolis brilhará sobre o mundo como uma utopia pura e perfeita.",
  ui_story_5053_50531201_80_dialog_content = "A visão do futuro do pai era tão grandiosa quanto ideal. Eu o respeito ainda mais por isso.",
  ui_story_5053_50531201_81_dialog_content = "No entanto... a base para a utopia de meu pai ainda está sendo lançada, e nem todos compartilham de sua visão.",
  ui_story_5053_50531201_82_dialog_content = "Diga-me, você notou a expressão no rosto de todos quando chegou à minha casa?",
  ui_story_5053_50531201_83_dialog_content = "Sempre que eu estava presente, todos me tratavam com adulação nervosa.",
  ui_story_5053_50531201_84_dialog_content = "Só de longe pude ver seus verdadeiros sorrisos... Seus verdadeiros momentos de felicidade.",
  ui_story_5053_50531201_85_dialog_content = "Então perguntei ao meu pai por que eles me tratavam assim.",
  ui_story_5053_50531201_86_dialog_content = "Ele disse que era porque todos eles se acostumaram a viver em pecado vergonhoso.",
  ui_story_5053_50531201_87_dialog_content = "Assim, eles não suportavam olhar para os membros da Câmara Schwartz, que simbolizava justiça e ordem.",
  ui_story_5053_50531201_88_dialog_content = "Era da natureza deles, um mal que nunca poderia ser erradicado... É por isso que eles precisavam de nossa orientação.",
  ui_story_5053_50531201_89_dialog_content = "Era o nobre dever da Casa Schwartz para suportar o peso da governação e corrigir o seu comportamento.",
  ui_story_5053_50531201_90_dialog_content = "... Mas, para ser franco, morar aqui era insuportavelmente sufocante.",
  ui_story_5053_50531201_91_dialog_content = "Por esse motivo, muitas vezes eu me disfarçava e fugia de casa para aproveitar um momento de descanso.",
  ui_story_5053_50531201_92_dialog_content = "Todo esse tempo, eu pensei que você fosse diferente, Joshua. Você era a única pessoa que ria comigo, Joshua.",
  ui_story_5053_50531201_93_dialog_content = "Mas vejo agora que era apenas uma ilusão... E que ainda tenho muito a aprender.",
  ui_story_5053_50531201_94_dialog_content = "... Enganar.",
  ui_story_5053_50531201_95_dialog_content = "Haha... concordo. Se eu nunca tivesse nascido um Schwartz.",
  ui_story_5053_50531201_96_dialog_content = "O que é mais uma razão para eu confrontar sua dor e ódio.",
  ui_story_5053_50531201_97_dialog_content = "Um assassinato perfeito como esse nunca poderia ser feito por apenas algumas pessoas.",
  ui_story_5053_50531201_98_dialog_content = "Eles podem esconder sua verdadeira identidade, treiná-lo ano após ano, obter ajuda de todo o pessoal relevante...",
  ui_story_5053_50531201_99_dialog_content = "Não consigo imaginar quantas pessoas são necessárias para realizar tal façanha, muito menos fazê-lo com precisão perfeita.",
  ui_story_5053_50531201_100_dialog_content = "A pressão exercida pela Câmara Schwartz está longe de erradicar a ganância e a maldade. Em vez disso, nos tornou inimigos de inúmeras pessoas.",
  ui_story_5053_50531201_101_dialog_content = "Essa nunca foi a intenção do meu pai...",
  ui_story_5053_50531201_102_dialog_content = "Não tente me persuadir com seus discursos lamentáveis, Schwartz. Se você reconheceu seus erros, você e seu pai devem aceitar a responsabilidade por eles... E pagar com suas vidas.",
  ui_story_5053_50531201_103_dialog_content = "Morrer pelos próprios erros é evitar assumir a responsabilidade por eles, Joshua.",
  ui_story_5053_50531201_104_dialog_content = "A visão de meu pai não estava totalmente errada. Na verdade, havia muitas qualidades redentoras nele.",
  ui_story_5053_50531201_105_dialog_content = "Este plano de assassinato é uma prova indiscutível disso.",
  ui_story_5053_50531201_106_dialog_content = "...?",
  ui_story_5053_50531201_107_dialog_content = "No passado, posição e linhagem determinavam tudo em Lumopolis.",
  ui_story_5053_50531201_108_dialog_content = "Suborno e peculato eram ocorrências comuns entre a nobreza. Com sua influência política, eles ocuparam todas as posições de poder e usaram a lei para promover seus próprios interesses.",
  ui_story_5053_50531201_109_dialog_content = "Mas sob a pressão exercida por meu pai, o povo de Lower Lumopolis também teve o direito de buscar justiça.",
  ui_story_5053_50531201_110_dialog_content = "Com a ameaça de justiça pairando sobre suas cabeças, os nobres de Lumopolis começaram a confessar seus crimes em troca de clemência.",
  ui_story_5053_50531201_111_dialog_content = "Por meio de um sistema de avaliação, as pessoas começaram a subir também na hierarquia de nossa cidade.",
  ui_story_5053_50531201_112_dialog_content = "Isso estava de acordo com a visão de meu pai: um mundo onde o valor de uma pessoa é decidido por suas habilidades e determinação, e não por seu nascimento.",
  ui_story_5053_50531201_113_dialog_content = "O pai de Caleb não era um estudioso nascido em uma família comum?",
  ui_story_5053_50531201_114_dialog_content = "Se o que eu disse é mentira, então alguém como ele, sem riqueza nem status, nunca poderia ter entrado nos Jardins de Lumopolis apenas por talento.",
  ui_story_5053_50531201_115_dialog_content = "Nem você poderia ter usado seu status de professor para se aproximar de mim.",
  ui_story_5053_50531201_116_dialog_content = "A pessoa que planejou esse assassinato reconheceu essa verdade e baseou todo o seu plano nisso.",
  ui_story_5053_50531201_117_dialog_content = "...",
  ui_story_5053_50531201_118_dialog_content = "Me conta, Joshua. Onde as políticas do meu pai deram errado?",
  ui_story_5053_50531201_119_dialog_content = "É porque Lower Lumopolis ainda é assolada pelo crime? Ou é porque seus expurgos excessivamente decisivos resultaram em incontáveis erros judiciais?",
  ui_story_5053_50531201_120_dialog_content = "Seja o que for, juro que não vou descansar até que a verdade seja revelada.",
  ui_story_5053_50531201_121_dialog_content = "Pode ser impossível compensar a dor que você sente agora...",
  ui_story_5053_50531201_122_dialog_content = "Mas, pelo menos, devemos tentar esclarecer as coisas. Para o bem de todos e também para o nosso.",
  ui_story_5053_50531201_123_dialog_content = "... Você ainda não entendeu.",
  ui_story_5053_50531201_124_dialog_content = "O que as pessoas precisam não é de um governo adequado, mas de liberdade verdadeira e absoluta.",
  ui_story_5053_50531201_125_dialog_content = "Liberdade absoluta?",
  ui_story_5053_50531201_126_dialog_content = "Sim. O direito de viver como bem entenderem, em vez de obedecer a uma hierarquia social.",
  ui_story_5053_50531201_127_dialog_content = "O direito de dizer o que pensam sem medo de perder sua riqueza ou mesmo suas vidas.",
  ui_story_5053_50531201_128_dialog_content = "Isso é liberdade.",
  ui_story_5053_50531201_129_dialog_content = "Aqueles servos tinham tanto medo de você porque sabiam que você poderia tirar tudo deles quando quisesse.",
  ui_story_5053_50531201_130_dialog_content = "\"Um mundo onde o valor de uma pessoa é decidido por suas habilidades e determinação...\" Não me faça rir!",
  ui_story_5053_50531201_131_dialog_content = "Para a Casa Schwartz, não passamos de gado cuja existência depende exclusivamente de sua aprovação!",
  ui_story_5053_50531201_132_dialog_content = "...",
  ui_story_5053_50531201_133_dialog_content = "...",
  ui_story_5053_50531201_134_dialog_content = "Então, matando meu pai e erradicando House Schwartz...",
  ui_story_5053_50531201_135_dialog_content = "Você deseja criar um mundo de liberdade absoluta, um que exista sem House Schwartz?",
  ui_story_5053_50531201_136_dialog_content = "Isso realmente te fará feliz, Joshua?",
  ui_story_5053_50531201_137_dialog_content = "Minha felicidade não está ligada a nada disso.",
  ui_story_5053_50531201_138_dialog_content = "Assim que o assassinato for finalmente realizado, minha vida também estará no fim.",
  ui_story_5053_50531201_139_dialog_content = "Em outras palavras, você escolheu a morte independentemente do resultado?",
  ui_story_5053_50531201_140_dialog_content = "Isso é para proteger seus aliados?",
  ui_story_5053_50531201_141_dialog_content = "Não. Uma vez que minha missão está completa, eu simplesmente não tenho mais razão para existir.",
  ui_story_5053_50531201_142_dialog_content = "Não... Motivo...?",
  ui_story_5053_50531201_143_dialog_content = "Os nobres são movidos por interesse próprio, mas nós somos movidos por nossos ideais.",
  ui_story_5053_50531201_144_dialog_content = "Não vivemos para riqueza nem status, mas para levantar um novo sol no céu, um que brilhe igualmente sobre o mundo.",
  ui_story_5053_50531201_145_dialog_content = "Para derrubar o velho e opressivo sol, estamos mais do que dispostos a nos sacrificar. Não pense que pode nos julgar com seu pensamento utilitarista podre.",
  ui_story_5053_50531201_146_dialog_content = "Heh, embora eu esteja honrado por você ter compartilhado tanto comigo, por que tudo é tão enigmático e obscuro?",
  ui_story_5053_50531201_147_dialog_content = "Então esta é a sua forma preferida de falar...?",
  ui_story_5053_50531201_148_dialog_content = "Se meu pai e seu governo representam o \"velho sol\", esse chamado \"novo sol\" não seria simplesmente outro governante?",
  ui_story_5053_50531201_149_dialog_content = "A pessoa por trás do plano de assassinato... Eles procuram tomar o lugar de meu pai como o novo governante?",
  ui_story_5053_50531201_150_dialog_content = "...",
  ui_story_5053_50531201_151_dialog_content = "... Inacreditável.",
  ui_story_5053_50531201_152_dialog_content = "Eu poderia entender morrer com seu inimigo para proteger sua família e aliados... Mas o que você quer dizer com você não tem razão de existir?",
  ui_story_5053_50531201_153_dialog_content = "E quanto ao seu irmão mais novo, que se opôs a mim dia e noite desde que roubei você dele?",
  ui_story_5053_50531201_154_dialog_content = "E quanto ao seu pai adotivo, que teme por sua segurança e simplesmente deseja que você volte para casa?",
  ui_story_5053_50531201_155_dialog_content = "Eles não são motivos suficientes para viver...?",
  ui_story_5053_50531201_156_dialog_content = "Se você realmente acredita que a Casa Schwartz roubou a liberdade de todos, você só precisa nos destruir para recuperá-la!",
  ui_story_5053_50531201_157_dialog_content = "Então, por que você deve se privar dessa mesma liberdade, mesmo que tenha sucesso?",
  ui_story_5053_50531201_158_dialog_content = "Isso significa que você acabaria com sua própria vida se meu pai falecesse inesperadamente? Seus destinos estão tão entrelaçados?!",
  ui_story_5053_50531201_159_dialog_content = "Eu já provei isso várias vezes, não é? Todo o vínculo e relacionamento com aquele homem e seu filho tolo é apenas um disfarce.",
  ui_story_5053_50531201_160_dialog_content = "Eu sou uma arma cujo único propósito é acabar com o governo da Casa Schwartz.",
  ui_story_5053_50531201_161_dialog_content = "Sem meu inimigo, não tenho razão de existir. A liberdade pertence ao povo, não a mim.",
  ui_story_5053_50531201_162_dialog_content = "... Que hipócrita.",
  ui_story_5053_50531201_163_dialog_content = "Parece que este \"novo sol\" nunca lhe ensinou o verdadeiro significado do amor ou da liberdade.",
  ui_story_5053_50531201_164_dialog_content = "Como você poderia entregar isso ao povo?",
  ui_story_5053_50531201_165_dialog_content = "...",
  ui_story_5053_50531201_166_dialog_content = "... Eu entendo agora.",
  ui_story_5053_50531201_167_dialog_content = "Eu nunca fiz parte do seu mundo. Não tenho como compreender verdadeiramente como as pessoas sofreram sob um governo estrito.",
  ui_story_5053_50531201_168_dialog_content = "Você também nunca fez parte do meu mundo. Você não tem como entender o verdadeiro significado do amor ou da liberdade.",
  ui_story_5053_50531201_169_dialog_content = "Esta é uma lacuna que nunca podemos esperar preencher.",
  ui_story_5053_50531201_170_dialog_content = "Concordo, então desista já...",
  ui_story_5053_50531201_171_dialog_content = "É por isso que devemos trabalhar juntos e compensar as deficiências uns dos outros!",
  ui_story_5053_50531201_172_dialog_content = "Você está louco.",
  ui_story_5053_50531201_173_dialog_content = "Seja nós, ou meu pai, ou mesmo essa pessoa do \"novo sol\"...",
  ui_story_5053_50531201_174_dialog_content = "Ninguém é capaz de ver as coisas do ponto de vista de todos. Não sozinho, pelo menos.",
  ui_story_5053_50531201_175_dialog_content = "Mas se deixarmos de lado nossas diferenças e tentarmos trabalhar juntos...",
  ui_story_5053_50531201_176_dialog_content = "Podemos criar um mundo novo e livre! Um onde a voz de todos pode ser ouvida!",
  ui_story_5053_50531201_177_dialog_content = "Este é o seu objetivo também, não é?",
  ui_story_5053_50531201_178_dialog_content = "...",
  ui_story_5053_50531201_179_dialog_content = "Desde que te interrompi naquele dia, tenho pensado nisso constantemente.",
  ui_story_5053_50531201_180_dialog_content = "É errado confiarmos nossos sonhos aos outros?",
  ui_story_5053_50531201_181_dialog_content = "Seja realizando a visão de meu pai ou matando-o para dar origem a um \"novo sol\"...",
  ui_story_5053_50531201_182_dialog_content = "Talvez tomar nosso destino em nossas próprias mãos seja a melhor maneira de realizar nossos sonhos.",
  ui_story_5053_50531201_183_dialog_content = "Tão confuso e ignorante quanto estou agora...",
  ui_story_5053_50531201_184_dialog_content = "Acredito que, trabalhando juntos, podemos realizar tudo o que desejamos.",
  ui_story_5053_50531201_185_dialog_content = "Tudo o que precisamos fazer é dar o primeiro passo.",
  ui_story_5053_50531201_186_dialog_content = "Você pode abrir meus olhos para o mundo fora dos Jardins Lumopolis.",
  ui_story_5053_50531201_187_dialog_content = "Só então poderei ver as deficiências da política de meu pai.",
  ui_story_5053_50531201_188_dialog_content = "Em troca, vou ajudá-lo a experimentar a vida ao máximo, para que você possa rir do fundo do coração novamente.",
  ui_story_5053_50531201_189_dialog_content = "Quando esse dia chegar, você poderá compartilhar essa alegria com o resto do mundo!",
  ui_story_5053_50531201_190_dialog_content = "... Que inútil.",
  ui_story_5053_50531201_191_dialog_content = "Há muitas outras mulheres que ficariam mais do que felizes em brincar de casinha com você. Por que desperdiçar seu tempo comigo?",
  ui_story_5053_50531201_192_dialog_content = "Bem, para ser honesto...",
  ui_story_5053_50531201_193_dialog_content = "Há tão poucas pessoas dispostas a se opor ao meu pai, e os moradores dos Jardins Lumopolis não conseguem compreender o mundo exterior...",
  ui_story_5053_50531201_194_dialog_content = "E, er... Assim como eu disse quando nos conhecemos—",
  ui_story_5053_50531201_195_dialog_content = "Eu me apaixonei por você à primeira vista!",
  ui_story_5053_50531201_196_dialog_content = "...",
  ui_story_5053_50531201_197_dialog_content = "(O escuro Angel não se move há muito tempo. Ela finalmente se acalmou...?)",
  ui_story_5053_50531201_198_dialog_content = "Ei! Você está finalmente disposto a me ouvir, então?",
  ui_story_5053_50531201_199_dialog_content = "Ouça, o Demônio Branco... quero dizer, o outro você, quer matar Caleb, Veronica e todos os outros.",
  ui_story_5053_50531201_200_dialog_content = "Eles precisam muito da sua...",
  ui_story_5053_50531201_201_dialog_content = "Da... Niel...",
  ui_story_5053_50531201_202_dialog_content = "Hã?",
  ui_story_5053_50531201_203_dialog_content = "Daniel... Por que você... me traiu?!",
  ui_story_5053_50531201_204_dialog_content = "<size=45>Daniel!!!</size>",
  ui_story_5053_50531201_205_dialog_content = "O que-?! Ela está ficando ainda mais furiosa do que antes! P-Por favor, acalme-se! eu não sou senhor Schwartz!",
  ui_story_5053_50531201_206_dialog_content = "<size=45>Daniel! Daniel!</size>",
  ui_story_5053_50531201_207_dialog_content = "(Estou ficando sem tempo, mas pelo menos tenho a atenção dela! Preciso atraí-la até a praça central!)",
  ui_story_5053_50531201_208_dialog_content = "<size=45>Daniel—</size>",
  ui_story_5053_50531301_1_dialog_content = "Minha gratidão vai para todas as pessoas de Lumopolis reunidas aqui hoje para celebrar esta ocasião especial.",
  ui_story_5053_50531301_2_dialog_content = "Casa Schwartz é a joia da coroa da cidade, assim como sua fundação.",
  ui_story_5053_50531301_3_dialog_content = "Erguemos nossos braços em defesa de Lumopolis, empunhando lâminas que foram criadas por seu próprio povo.",
  ui_story_5053_50531301_4_dialog_content = "Hoje, louvamos não só House Schwartz e seu exemplo moral, mas também o povo orgulhoso e justo de Lumopolis!",
  ui_story_5053_50531301_5_dialog_content = "Declaro o início do Schwartz Comemoração do Dia da Família!",
  ui_story_5053_50531301_6_dialog_content = "A celebração está prestes a começar, mas o Dark Angel ainda não apareceu perto do estande.",
  ui_story_5053_50531301_7_dialog_content = "Elimine... Intruso...",
  ui_story_5053_50531301_8_dialog_content = "Hum? Qual é o problema com esses guardas?",
  ui_story_5053_50531301_9_dialog_content = "Se bem me lembro, as pessoas dentro do Cristal da Memória Eterna nada mais são do que ilusões criadas por Lumina.",
  ui_story_5053_50531301_10_dialog_content = "Por que eles se comportariam de repente de forma tão errática? É como se tivessem perdido a consciência...",
  ui_story_5053_50531301_11_dialog_content = "Estarei no estande para ficar de olho. Se eu vir algum sinal do Escuro Angel, vou avisar a todos.",
  ui_story_5053_50531301_12_dialog_content = "Bom. Esteja em guarda, Mia.",
  ui_story_5053_50531301_13_dialog_content = "(Mia deve estar seguro lá por enquanto. PlayerName, por outro lado, onde ele poderia estar agora?)",
  ui_story_5053_50531301_14_dialog_content = "O quê?",
  ui_story_5053_50531301_15_dialog_content = "PlayerName...",
  ui_story_5053_50531301_16_dialog_content = "Deve encontrar... PlayerName...",
  ui_story_5053_50531301_17_dialog_content = "Pare. Vocês claramente não são cavaleiros da Casa Kartima.",
  ui_story_5053_50531301_18_dialog_content = "A Casa Kartima está supervisionando a segurança para a celebração deste ano, então por que você está perambulando assim?",
  ui_story_5053_50531301_19_dialog_content = "(Esses guardas ficam cambaleando e resmungando para si mesmos... Será que eles estão bêbados?)",
  ui_story_5053_50531301_20_dialog_content = "(E por que eles estão tão interessados em encontrar PlayerName?)",
  ui_story_5053_50531301_21_dialog_content = "Deve encontrar... PlayerName...",
  ui_story_5053_50531301_22_dialog_content = "Deve eliminar... PlayerName...",
  ui_story_5053_50531301_23_dialog_content = "Perdão? O que você acabou de dizer é uma violação grave de seus deveres de cavaleiro.",
  ui_story_5053_50531301_24_dialog_content = "Expliquem-se neste instante, todos vocês.",
  ui_story_5053_50531301_25_dialog_content = "Elimine... Intruso...!",
  ui_story_5053_50531301_26_dialog_content = "Eles nem conseguem falar coerentemente, muito menos me dizer quem ou o que está por trás disso. O que há de errado com esses cavaleiros?",
  ui_story_5053_50531301_27_dialog_content = "(Após a reinicialização, ninguém no Cristal da Memória Eterna deve reconhecer PlayerName não mais.)",
  ui_story_5053_50531301_28_dialog_content = "(Eles nem deveriam estar cientes de sua existência, muito menos abrigar intenções assassinas em relação a ele.)",
  ui_story_5053_50531301_29_dialog_content = "Isso não será necessário. Uma equipe de guardas pode encontrar PlayerName com a mesma rapidez, se não mais.",
  ui_story_5053_50531301_30_dialog_content = "Além disso, precisamos da força de todos se quisermos ter uma chance contra aquele monstro.",
  ui_story_5053_50531301_31_dialog_content = "Acho que você sabe tão bem quanto eu qual desses assuntos é mais importante. Use seu bom senso, Daniel.",
  ui_story_5053_50531301_32_dialog_content = "(... Joshua é o único fora do nosso grupo que sabe sobre PlayerName.)",
  ui_story_5053_50531301_33_dialog_content = "(Ela também é a única outra pessoa viva dentro do Cristal da Memória Eterna além de nós.)",
  ui_story_5053_50531301_34_dialog_content = "(Mas por que ela iria querer caçar uma mera criança, alguém que não tem nada a ver com ela?)",
  ui_story_5053_50531301_35_dialog_content = "(Dizer a Caleb para permanecer ao lado dela foi a escolha certa, afinal.)",
  ui_story_5053_50531301_36_dialog_content = "(Eu só rezo para que ele não deixe a alegria de se reunir com sua irmã obscurecer seu julgamento e descobrir a verdade em meu lugar.)",
  ui_story_5053_50531301_37_dialog_content = "Huff... huff... L-Senhor Schwartz! Oh, graças a Deus te encontrei!",
  ui_story_5053_50531301_38_dialog_content = "PlayerName...?",
  ui_story_5053_50531301_39_dialog_content = "Aaaaaaaah—!",
  ui_story_5053_50531301_40_dialog_content = "PlayerName, abaixe-se!",
  ui_story_5053_50531301_41_dialog_content = "Esqueça o escuro Angel! Mia está em perigo! Precisamos chegar ao estande!",
  ui_story_5053_50531301_42_dialog_content = "Como assim?",
  ui_story_5053_50531301_43_dialog_content = "Apenas confie em mim! Agora vamos!!",
  ui_story_5053_50531301_44_dialog_content = "Muito bem...",
  ui_story_5053_50531301_45_dialog_content = "Bwaaah! O-O que é isso?!",
  ui_story_5053_50531301_46_dialog_content = "Segure firme. Vou levá-lo ao estande.",
  ui_story_5053_50531301_47_dialog_content = "?!",
  ui_story_5053_50531301_48_dialog_content = "D... Daniel...? Daniel!!!",
  ui_story_5053_50531301_49_dialog_content = "Ei! Pare de empurrar!",
  ui_story_5053_50531301_50_dialog_content = "O-O que está acontecendo?",
  ui_story_5053_50531301_51_dialog_content = "Monstro! É um monstro!!",
  ui_story_5053_50531301_52_dialog_content = "A multidão está em alvoroço. O que está acontecendo lá embaixo?",
  ui_story_5053_50531301_53_dialog_content = "<size=30> Isso é... Pai e PlayerName! Espere, isso é... o Escuro Angel?!</size>",
  ui_story_5053_50531301_54_dialog_content = "O que é, Verônica?",
  ui_story_5053_50531301_55_dialog_content = "N-Nada, padre...",
  ui_story_5053_50531301_56_dialog_content = "Eles estão forçando seu caminho através da multidão em direção ao estande!",
  ui_story_5053_50531301_57_dialog_content = "Parem eles, guardas!!",
  ui_story_5053_50531301_58_dialog_content = "(O escuro Angel realmente está caçando o Pai... Exatamente como a Mãe disse.)",
  ui_story_5053_50531301_59_dialog_content = "(Não sei por que eles estão correndo para cá, mas tenho que protegê-lo.)",
  ui_story_5053_50531301_60_dialog_content = "(Oh, Hippoca, por favor me responda, eu preciso de você mais do que nunca!)",
  ui_story_5053_50531301_61_dialog_content = "Verônica, o que está acontecendo? Quem são aqueles estranhos lutando no meio da multidão?",
  ui_story_5053_50531301_62_dialog_content = "eu não sei Carleen, mas fique perto de nós.",
  ui_story_5053_50531301_63_dialog_content = "Aquele homem na frente é outra coisa.",
  ui_story_5053_50531301_64_dialog_content = "Ele está desviando de nossos guardas com tanta facilidade, enquanto carrega alguém em seus braços.",
  ui_story_5053_50531301_65_dialog_content = "Na verdade, ele quase se parece com...",
  ui_story_5053_50531301_66_dialog_content = "H-Ele derrubou um dos guardas e o usou para pular no meio da multidão! Ele está vindo em nossa direção!",
  ui_story_5053_50531301_67_dialog_content = "Homens, protejam os outros! Eu mesmo cuido deles.",
  ui_story_5053_50531301_68_dialog_content = "...",
  ui_story_5053_50531301_69_dialog_content = "Quem é você e qual é o seu negócio aqui?",
  ui_story_5053_50531301_70_dialog_content = "Onde está o perigo que você mencionou, PlayerName?",
  ui_story_5053_50531301_71_dialog_content = "Fiz-lhe uma pergunta, senhor!",
  ui_story_5053_50531301_72_dialog_content = "Acima de nós! Estará aqui a qualquer segundo!",
  ui_story_5053_50531301_73_dialog_content = "De onde veio essa criatura nojenta?! Guardas! Me proteja! Guardas!!!",
  ui_story_5053_50531301_74_dialog_content = "D... Daniel? Daniel... Daniel...",
  ui_story_5053_50531301_75_dialog_content = "Aaaaaah—Daniel—!!!",
  ui_story_5053_50531301_76_dialog_content = "Fique longe do meu pai!",
  ui_story_5053_50531301_77_dialog_content = "... Está aqui! O dragão está aqui agora!!",
  ui_story_5053_50531301_78_dialog_content = "<size=50>Rugido-!!!</size>",
  ui_story_5053_50531301_79_dialog_content = "Um dragão voador?",
  ui_story_5053_50531301_80_dialog_content = "Uma aliança gravada na linhagem da Casa Kartima... Mas ainda não é muito cedo?",
  ui_story_5053_50531301_81_dialog_content = "Aconselho-o a concentrar-se no perigo que corre, meu jovem.",
  ui_story_5053_50531301_82_dialog_content = "Traidores de Kartima... Você nunca estará no controle aqui!",
  ui_story_5053_50531301_83_dialog_content = "Concentre-se em seu verdadeiro inimigo! Está vindo para nós!",
  ui_story_5053_50531301_84_dialog_content = "...",
  ui_story_5053_50531301_85_dialog_content = "Th-O dragão! Mas não era para estar aqui ainda!",
  ui_story_5053_50531301_86_dialog_content = "Não se preocupe, Verônica! Eu protegerei você!",
  ui_story_5053_50531301_87_dialog_content = "Não... Os rebeldes colocaram seu plano em ação antes do que pensávamos! Proteja-se, Carleen!",
  ui_story_5053_50531301_88_dialog_content = "Carleen...? Verônica...?",
  ui_story_5053_50531301_89_dialog_content = "Rooooaaaar!!!!!",
  ui_story_5053_50531301_90_dialog_content = "O dragão está prestes a atacar!",
  ui_story_5053_50531301_91_dialog_content = "—!!!",
  ui_story_5053_50531301_92_dialog_content = "De onde veio esse dragão?!",
  ui_story_5053_50531301_93_dialog_content = "Waaaaah! Papai, onde você está?!",
  ui_story_5053_50531301_94_dialog_content = "É cuspir fogo! Correr!!!",
  ui_story_5053_50531301_95_dialog_content = "Filho! Cadê você, meu menino?!",
  ui_story_5053_50531301_96_dialog_content = "...",
  ui_story_5053_50531301_97_dialog_content = "Por favor senhor! Você viu meu garotinho? Ele tem esta altura, e...",
  ui_story_5053_50531301_98_dialog_content = "Elimine... todos eles...",
  ui_story_5053_50531301_99_dialog_content = "Hã? O que você disse?",
  ui_story_5053_50531301_100_dialog_content = "Mais aliados... elimine todos eles...",
  ui_story_5053_50531301_101_dialog_content = "Urk?! O-O que você...",
  ui_story_5053_50531301_102_dialog_content = "Mais aliados... elimine todos eles...",
  ui_story_5053_50531301_103_dialog_content = "*Tosse* Verônica? Pai? Onde você está?",
  ui_story_5053_50531301_104_dialog_content = "Carleen! Você está bem?",
  ui_story_5053_50531301_105_dialog_content = "Estou bem. É que minha garganta dói com toda a poeira.",
  ui_story_5053_50531301_106_dialog_content = "Ah, graças a Deus...",
  ui_story_5053_50531301_107_dialog_content = "Verônica... Carleen...",
  ui_story_5053_50531301_108_dialog_content = "Funcionou! Todos os quatro foram capazes de derrotar o dragão!!",
  ui_story_5053_50531301_109_dialog_content = "(Parece que apenas os membros da família podem acalmar o Dark Angel abaixo. Foi uma grande aposta, mas estou feliz que valeu a pena!",
  ui_story_5053_50531301_110_dialog_content = "Ainda é cedo para comemorar.",
  ui_story_5053_50531301_111_dialog_content = "O dragão apenas recuou para reunir forças para outro ataque de fogo.",
  ui_story_5053_50531301_112_dialog_content = "Ele cairá sobre nós em breve.",
  ui_story_5053_50531301_113_dialog_content = "Isso significa simplesmente que precisamos derrotá-lo antes que ele lance seu próximo ataque.",
  ui_story_5053_50531301_114_dialog_content = "Então é melhor você fazer bem em atingir seu ponto fraco.",
  ui_story_5053_50531301_115_dialog_content = "Mais especificamente, você precisa atacar seu—",
  ui_story_5053_50531301_116_dialog_content = "Eu sei onde atacar a besta.",
  ui_story_5053_50531301_117_dialog_content = "Não vai nos servir de nada! O dragão possui algum tipo de invulnerabilidade, que o permite curar instantaneamente qualquer ferimento.",
  ui_story_5053_50531301_118_dialog_content = "O quê?",
  ui_story_5053_50531301_119_dialog_content = "Senhor Schwartz! A revolta começou!",
  ui_story_5053_50531301_120_dialog_content = "Em seguida, continue com o plano. Reúna mais homens e reprima os rebeldes.",
  ui_story_5053_50531301_121_dialog_content = "Deixe o dragão comigo e faça com que os soldados restantes evacuem as pessoas desta área.",
  ui_story_5053_50531301_122_dialog_content = "Mas meu senhor... Os rebeldes não são os únicos em tumulto! A maioria das pessoas na área, incluindo alguns de nossos próprios soldados, também começaram a atacar!",
  ui_story_5053_50531301_123_dialog_content = "O quê...?!",
  ui_story_5053_50531301_124_dialog_content = "Eles parecem ter perdido o controle de seus corpos e mentes, meu senhor. Eles estão atacando qualquer criatura viva que possam alcançar, sejam eles amigos ou inimigos!",
  ui_story_5053_50531301_125_dialog_content = "Mas o mais perturbador é que sua loucura parece se espalhar para quem eles conseguem ferir! É como se...",
  ui_story_5053_50531301_126_dialog_content = "Como se estivessem sendo infectados e transformados em mortos-vivos, certo?",
  ui_story_5053_50531301_127_dialog_content = "P-Precisamente.",
  ui_story_5053_50531301_128_dialog_content = "Você parece estar bem ciente de nossa situação atual.",
  ui_story_5053_50531301_129_dialog_content = "O tempo não está do nosso lado, então conte-nos o que você sabe.",
  ui_story_5053_50531301_130_dialog_content = "Eu...",
  ui_story_5053_50531301_131_dialog_content = "(Jovem Schwartz está olhando para mim também...)",
  ui_story_5053_50531301_132_dialog_content = "(Se eu não der a ele uma explicação boa o suficiente, ele não vai me deixar ir tão facilmente.)",
  ui_story_5053_50531301_133_dialog_content = "(Mas se eu contar a verdade a ele agora, só vai fazê-lo duvidar de mim! Preciso inventar a desculpa perfeita...)",
  ui_story_5053_50531301_134_dialog_content = "Você está tão relutante em divulgar a verdade diante de mim?",
  ui_story_5053_50531301_135_dialog_content = "Ou pode ser que o culpado esteja entre vocês forasteiros—",
  ui_story_5053_50531301_136_dialog_content = "Como talvez aquele monstro alado ali?",
  ui_story_5053_50531301_137_dialog_content = "Por favor, não a chame assim! Ela não é um monstro, ela é...",
  ui_story_5053_50531301_138_dialog_content = "Lá em cima, o dragão se prepara para descer para outro ataque.",
  ui_story_5053_50531301_139_dialog_content = "Enquanto um exército de mortos-vivos nos cerca por baixo.",
  ui_story_5053_50531301_140_dialog_content = "Tenho certeza que você sabe o que tem precedência em um momento como este, certo?",
  ui_story_5053_50531301_141_dialog_content = "... Claro que eu sei.",
  ui_story_5053_50531301_142_dialog_content = "Guarda, contate Lachon e Otto e diga a eles que os soldados na praça estão sob seu comando agora.",
  ui_story_5053_50531301_143_dialog_content = "Diga a eles para fortalecer as defesas da base e trazer quaisquer sobreviventes não infectados para cá.",
  ui_story_5053_50531301_144_dialog_content = "Sim, meu senhor!",
  ui_story_5053_50531301_145_dialog_content = "(Sorte que Senhor Schwartz foi capaz de tirar seu eu mais jovem das minhas costas. Ele deve ter percebido que tenho minhas razões para não lhe contar a verdade.)",
  ui_story_5053_50531301_146_dialog_content = "(Não posso perder mais um segundo do nosso tempo, não depois de termos chegado tão longe. É hora de voltarmos para Schwartz Mansão!)",
  ui_story_5053_50531301_147_dialog_content = "Veronica... Por que está chamando meu nome?",
  ui_story_5053_50531301_148_dialog_content = "Apenas mantenha distância dela, Carleen.",
  ui_story_5053_50531301_149_dialog_content = "Verônica... Carleen... Você está machucado...?",
  ui_story_5053_50531301_150_dialog_content = "Você está machucado...?",
  ui_story_5053_50531301_151_dialog_content = "Eu vou te abraçar... e cantar...",
  ui_story_5053_50531301_152_dialog_content = "Huh? Eu estou bem, e também Carleen.",
  ui_story_5053_50531301_153_dialog_content = "Afinal, você pode se comunicar conosco... Você faz parte da Mãe, não é?",
  ui_story_5053_50531301_154_dialog_content = "Mãe... Eu sou.. Mãe...",
  ui_story_5053_50531301_155_dialog_content = "Então você poderia, por favor, parar de nos atacar? Você pode, por favor, parar de tentar machucar o pai?",
  ui_story_5053_50531301_156_dialog_content = "Verônica... Pai? Daniel... Daniel...!!!",
  ui_story_5053_50531301_157_dialog_content = "V-Você nunca quis que víssemos vocês dois brigando!",
  ui_story_5053_50531301_158_dialog_content = "Não é mesmo?",
  ui_story_5053_50531301_159_dialog_content = "...",
  ui_story_5053_50531301_160_dialog_content = "Sem mais... Sem mais brigas... Isso assusta as meninas...",
  ui_story_5053_50531301_161_dialog_content = "Chega de brigas... Verônica... não tenha medo...",
  ui_story_5053_50531301_162_dialog_content = "Eu sei, mãe. Obrigado.",
  ui_story_5053_50531301_163_dialog_content = "(Mãe disse que o Escuro Angel nasceu de uma Semente, e que ela não era nada mais do que uma besta irracional.)",
  ui_story_5053_50531301_164_dialog_content = "(Mas não só posso me comunicar com ela... posso até sentir uma certa gentileza vindo dela.)",
  ui_story_5053_50531301_165_dialog_content = "(Uma gentileza que não senti da mãe na mansão. O que diabos está acontecendo...?)",
  ui_story_5053_50531301_166_dialog_content = "<size=30>Ei! Por aqui, Verônica!</size>",
  ui_story_5053_50531301_167_dialog_content = "PlayerName! Pai! Vocês dois estão bem?",
  ui_story_5053_50531301_168_dialog_content = "Shhh! Controle-se!",
  ui_story_5053_50531301_169_dialog_content = "enquanto o jovem Schwartz está ocupado lutando contra o dragão, nós três e o Dark Angel precisa sair.",
  ui_story_5053_50531301_170_dialog_content = "Deixar? Mas para onde? E por que o Escuro Angel tem que vir conosco?",
  ui_story_5053_50531301_171_dialog_content = "Para Schwartz Mansão. Calebe e Jakine estão em sério perigo.",
  ui_story_5053_50531301_172_dialog_content = "Huh? Me desculpe, tudo isso é tão confuso. O que exatamente é...",
  ui_story_5053_50531301_173_dialog_content = "PlayerName prometeu explicar tudo no caminho. Devemos ir enquanto ainda temos chance.",
  ui_story_5053_50531301_174_dialog_content = "S-Sim, então.",
  ui_story_5053_50531301_175_dialog_content = "Daniel...",
  ui_story_5053_50531301_176_dialog_content = "E você tem certeza que ela não vai me atacar de novo, PlayerName?",
  ui_story_5053_50531301_177_dialog_content = "Uh, eu tenho certeza que você está seguro por agora...",
  ui_story_5053_50531301_178_dialog_content = "Ela não vai, pai. Mamãe já me prometeu que não ia, né?",
  ui_story_5053_50531301_179_dialog_content = "Eu prometo...",
  ui_story_5053_50531301_180_dialog_content = "... Multar.",
  ui_story_5053_50531301_181_dialog_content = "A parte de trás do estande deve estar livre de quaisquer curiosos. Devemos partir antes que terminem de fortalecer suas defesas.",
  ui_story_5053_50531301_182_dialog_content = "Onde você está indo, Verônica?",
  ui_story_5053_50531301_183_dialog_content = "Papai nos disse para ficar aqui e esperar que a Sra. Rot nos escoltasse para um local seguro.",
  ui_story_5053_50531301_184_dialog_content = "Desculpe, Carleen, mas não posso ficar. Há algo muito importante que preciso fazer.",
  ui_story_5053_50531301_185_dialog_content = "Mas uma garota corajosa como você não deve ter nenhum problema em esperar pela Sra. Rot sozinha, certo?",
  ui_story_5053_50531301_186_dialog_content = "Vou ficar bem, mas estou mais preocupado com você, Veronica.",
  ui_story_5053_50531301_187_dialog_content = "Quando você sai sozinho, geralmente é para chorar sozinho...",
  ui_story_5053_50531301_188_dialog_content = "Mas não precisa mais chorar, Verônica! Eu prometo que vou ficar mais forte um dia e te proteger, não importa o que aconteça!",
  ui_story_5053_50531301_189_dialog_content = "Heehee... Que pessoa corajosa e madura você se tornou, Carleen.",
  ui_story_5053_50531301_190_dialog_content = "Você também não precisa se preocupar. Não sou tão fraco e indefeso como costumava ser.",
  ui_story_5053_50531301_191_dialog_content = "Sua irmã mais velha ficará perfeitamente bem, eu prometo.",
  ui_story_5053_50531301_192_dialog_content = "Eu sei que sempre estive meio passo atrás de você no passado e dificultei as coisas para todos.",
  ui_story_5053_50531301_193_dialog_content = "Mas de agora em diante, vou trabalhar duro e me tornar uma irmã mais velha confiável que pode ajudá-lo a carregar seu fardo.",
  ui_story_5053_50531301_194_dialog_content = "Verônica...?",
  ui_story_5053_50531301_195_dialog_content = "Então, por favor, apenas confie em mim.",
  ui_story_5053_50531301_196_dialog_content = "Sim. Eu confio em você.",
  ui_story_5053_50531301_197_dialog_content = "Hehehe, obrigado.",
  ui_story_5053_50531301_198_dialog_content = "Até a próxima... Meu doce, pequenino Carleen.",
  ui_story_5053_50531302_1_dialog_content = "... Esta é a situação atual na praça central.",
  ui_story_5053_50531302_2_dialog_content = "Todas as passagens que levam à praça foram completamente fechadas.",
  ui_story_5053_50531302_3_dialog_content = "Sob o comando de Lord Schwartz, o motim está começando a ficar sob controle. Pode ficar tranquilo, alteza.",
  ui_story_5053_50531302_4_dialog_content = "... Entendido. Você pode sair agora.",
  ui_story_5053_50531302_5_dialog_content = "Como desejar.",
  ui_story_5053_50531302_6_dialog_content = "Agora então, você poderia ser um querido e trancar a porta para nós, Jakine?",
  ui_story_5053_50531302_7_dialog_content = "Ah com certeza! Afinal, até uma simples fechadura pode fazer maravilhas pela nossa segurança!",
  ui_story_5053_50531302_8_dialog_content = "Deixe-me fazer uma pergunta, Caleb. Por que você quer me resgatar?",
  ui_story_5053_50531302_9_dialog_content = "Hã?",
  ui_story_5053_50531302_10_dialog_content = "Hum? Porque você é minha irmã, claro! Que irmão não gostaria de ajudar sua própria irmã?",
  ui_story_5053_50531302_11_dialog_content = "<color=#e8d9bb>Bate, baque, baque!</color>",
  ui_story_5053_50531302_12_dialog_content = "Senhora Joshua, Eu vim para escoltá-lo para a segurança. May eu entro?",
  ui_story_5053_50531302_13_dialog_content = "Claro, é só entrar aqui!",
  ui_story_5053_50531302_14_dialog_content = "Jakine, você esqueceu que é um convidado aqui? Minha irmã não tinha acabado de falar!",
  ui_story_5053_50531302_15_dialog_content = "...",
  ui_story_5053_50531302_16_dialog_content = "desculpe a interrupção...",
  ui_story_5053_50531302_17_dialog_content = "O que é, Sra. Rot?",
  ui_story_5053_50531302_18_dialog_content = "Disseram-me que você não estava se sentindo bem hoje. Como tal, Senhor Schwartz ordenou que eu ficasse ao seu lado e garantisse sua segurança.",
  ui_story_5053_50531302_19_dialog_content = "Dada a gravidade da situação, devo pedir-lhe que me siga para outro local seguro.",
  ui_story_5053_50531302_20_dialog_content = "Assim que você se abrigar, eu escoltarei a princesa Carleen para a segurança também. Fique tranquilo, não vou deixar que ela sofra nenhum mal.",
  ui_story_5053_50531302_21_dialog_content = "Eu vejo. Muito gentil da sua parte.",
  ui_story_5053_50531302_22_dialog_content = "No entanto, meus convidados e eu estamos perfeitamente seguros aqui. De qualquer forma, você deveria se preocupar mais com a segurança de Carleen agora.",
  ui_story_5053_50531302_23_dialog_content = "Receio não poder fazer isso.",
  ui_story_5053_50531302_24_dialog_content = "Se eu fosse embora agora... Você não teria nenhum problema em matar seus dois convidados na minha ausência.",
  ui_story_5053_50531302_25_dialog_content = "M-Assassinato?!",
  ui_story_5053_50531302_26_dialog_content = "Qual é o significado disso, Sra. Rot?! Minha irmã nunca...",
  ui_story_5053_50531302_27_dialog_content = "... Joshua?",
  ui_story_5053_50531302_28_dialog_content = "Sim, Calebe. Eu nunca faria nada tão violentamente atroz.",
  ui_story_5053_50531302_29_dialog_content = "Por que diabos você me acusaria disso, Sra. Rot?",
  ui_story_5053_50531302_30_dialog_content = "Você pode dispensar o ato.",
  ui_story_5053_50531302_31_dialog_content = "A adaga está escondida na sua perna, não está? Bastante o método clássico de assassinato.",
  ui_story_5053_50531302_32_dialog_content = "Sua habilidade de esconder armas é incomparável, mas sua mão pairando sobre o cabo torna suas intenções muito óbvias.",
  ui_story_5053_50531302_33_dialog_content = "...",
  ui_story_5053_50531302_34_dialog_content = "Você é um assassino altamente treinado e não pode haver dúvidas.",
  ui_story_5053_50531302_35_dialog_content = "Você é muito parecido com meu mestre, mas não passa de um impostor extremamente atraente.",
  ui_story_5053_50531302_36_dialog_content = "Um impostor? M-Mas sua voz e aparência... Eu nunca poderia confundi-los!",
  ui_story_5053_50531302_37_dialog_content = "Ele está certo, e o Cristal da Memória Eterna mostra claramente que ela também é uma pessoa viva e que respira!",
  ui_story_5053_50531302_38_dialog_content = "Quais são as chances de que outra pessoa esteja aqui se passando por Lady Joshua?!",
  ui_story_5053_50531302_39_dialog_content = "Não sei como vocês dois estão ligados a essa assassina, mas para sua segurança, sugiro que mantenham distância dela.",
  ui_story_5053_50531302_40_dialog_content = "Se eu tivesse que adivinhar, você deve ser outro remanescente dessa organização, alguém que eles também treinaram nas artes de matar.",
  ui_story_5053_50531302_41_dialog_content = "Afinal, a semelhança entre você e meu antigo mestre é incrível.",
  ui_story_5053_50531302_42_dialog_content = "É precisamente por esta razão que você nunca poderia substituí-la. A dama Joshua de hoje é uma esposa amorosa, uma mãe carinhosa e uma irmã carinhosa.",
  ui_story_5053_50531302_43_dialog_content = "Estou correto em dizer isso?",
  ui_story_5053_50531302_44_dialog_content = "...",
  ui_story_5053_50531302_45_dialog_content = "L-Lady Joshua tem uma adaga nas mãos! Como diabos ela tirou isso do nada...?",
  ui_story_5053_50531302_46_dialog_content = "Argh, isso faz! Cadê minha bola de cristal?!",
  ui_story_5053_50531302_47_dialog_content = "Não há como errar, Jakine... Ela realmente é minha irmã. Mas como... Como pode ser isso?!",
  ui_story_5053_50531302_48_dialog_content = "Pare de ficar parado, Caleb! Se você não vai lutar, proteja-se!",
  ui_story_5053_50531302_49_dialog_content = "<size=45>Aaaaaaah—!</size>",
  ui_story_5053_50531302_50_dialog_content = "E-É você—!!",
  ui_story_5053_50531302_51_dialog_content = "é o escuro Angel!",
  ui_story_5053_50531302_52_dialog_content = "O escuro Angel...?",
  ui_story_5053_50531302_53_dialog_content = "Longe... de Calebe...",
  ui_story_5053_50531302_54_dialog_content = "<size=45>Deixe... Caleb... Sozinho!!!</size>",
  ui_story_5053_50531302_55_dialog_content = "O que você está fazendo aqui?!",
  ui_story_5053_50531302_56_dialog_content = "Afaste-se de mim, sua coisa nojenta!",
  ui_story_5053_50531302_57_dialog_content = "Não há escapatória!",
  ui_story_5053_50531302_58_dialog_content = "Primeira dama Joshua quer nos matar, e agora o Dark Angel perseguiu ela...",
  ui_story_5053_50531302_59_dialog_content = "O-O que diabos ainda está acontecendo?! Alguém precisa explicar essa bagunça agora!",
  ui_story_5053_50531302_60_dialog_content = "U-Uau, Hippoca! Parar...!!",
  ui_story_5053_50531302_61_dialog_content = "Bwaaaa! E agora um cavalo-aranha gigante voou pela janela!!!",
  ui_story_5053_50531302_62_dialog_content = "Espere... PlayerName?! Com Mia e Senhor Schwartz!",
  ui_story_5053_50531302_63_dialog_content = "Bom trabalho, Mia. Você parece ter um grande dom quando se trata de usar sua invocação de Lumina como uma montaria.",
  ui_story_5053_50531302_64_dialog_content = "*Ofegante* Para ser sincero... Essa foi a primeira vez que usei o Hippoca assim...",
  ui_story_5053_50531302_65_dialog_content = "Ugh... Nós pulamos tantos prédios nas costas do Hippoca... Acho que vou vomitar...",
  ui_story_5053_50531302_66_dialog_content = "O que vocês três são...",
  ui_story_5053_50531302_67_dialog_content = "Oh bom, parece que Caleb e Jakine ainda estão bem...",
  ui_story_5053_50531302_68_dialog_content = "Ainda bem que chegamos a tempo... Urk...!",
  ui_story_5053_50531401_1_dialog_content = "Então você está dizendo que esse Demônio Branco tem nos feito de tolos o tempo todo.",
  ui_story_5053_50531401_2_dialog_content = "E que ela e a Escuridão Angel ambos são parte de Lady Joshua, mas eles não conseguem chegar a um acordo um com o outro.",
  ui_story_5053_50531401_3_dialog_content = "Então o plano dela é matar todos nós, absorver nossa Lumina e se libertar com ela...",
  ui_story_5053_50531401_4_dialog_content = "Mesmo que pareça tão inacreditável, acho que entendo as circunstâncias dela.",
  ui_story_5053_50531401_5_dialog_content = "A dor de partir a cabeça, o medo de seu outro eu...",
  ui_story_5053_50531401_6_dialog_content = "Mas, embora sejamos tão diferentes, Baba Yaga e eu somos a mesma pessoa.",
  ui_story_5053_50531401_7_dialog_content = "E se eu pudesse aprender a coexistir com ela, certamente mamãe poderia...",
  ui_story_5053_50531401_8_dialog_content = "Você acha que ainda temos chance de convencer o Demônio Branco a desistir de seu esquema maluco, PlayerName?",
  ui_story_5053_50531401_9_dialog_content = "Bem... eu acho que só a verdadeira Lady Joshua saberia disso.",
  ui_story_5053_50531401_10_dialog_content = "Tudo o que sei é que o Cristal da Memória Eterna está quase fora de Lumina.",
  ui_story_5053_50531401_11_dialog_content = "Esta é a nossa última chance de sair daqui. Não podemos perder tempo pensando demais nas coisas.",
  ui_story_5053_50531401_12_dialog_content = "Por favor, perdoe-me, mas não consegui subjugar a outra Senhora Joshua.",
  ui_story_5053_50531401_13_dialog_content = "Um guarda acabou de me alertar que a situação na praça central já está sob controle.",
  ui_story_5053_50531401_14_dialog_content = "No entanto, o dragão continua a ser uma ameaça implacável. Nossas forças não durarão muito mais contra um inimigo imbatível como este.",
  ui_story_5053_50531401_15_dialog_content = "Obrigado por sua ajuda, Sra. Rot. Você pode deixar o resto conosco.",
  ui_story_5053_50531401_16_dialog_content = "Receio ter que recusar.",
  ui_story_5053_50531401_17_dialog_content = "Meu dever é proteger a Casa Schwartz e toda Lumópolis.",
  ui_story_5053_50531401_18_dialog_content = "Se sou ou não apenas uma ilusão, não tem relação com meu dever. Eu sou e sempre serei a Sra. Rot.",
  ui_story_5053_50531401_19_dialog_content = "Mesmo diante de uma crise existencial tão chocante, sua compostura permanece inabalável.",
  ui_story_5053_50531401_20_dialog_content = "Heheh... Honestamente, essa percepção me deu uma sensação de alívio.",
  ui_story_5053_50531401_21_dialog_content = "Agora que sei que não há futuro para mim, não tenho motivos para me preocupar constantemente com isso.",
  ui_story_5053_50531401_22_dialog_content = "Se alguém está sofrendo com a verdade agora, seria o Sr. Caleb.",
  ui_story_5053_50531401_23_dialog_content = "Joshua... Nunca quis que ninguém soubesse a verdade sobre seu passado.",
  ui_story_5053_50531401_24_dialog_content = "Por um lado, revelar seu passado só atrairia mais críticas.",
  ui_story_5053_50531401_25_dialog_content = "No entanto, acredito que o verdadeiro motivo foi que ela não teve coragem de confessar isso ao irmão mais novo.",
  ui_story_5053_50531401_26_dialog_content = "De certa forma, a força e a bondade que ela descobriu ao longo dos anos também deram origem à sua maior fraqueza.",
  ui_story_5053_50531401_27_dialog_content = "Eu sei o que você quer dizer. para senhora Joshua ter crescido e vivenciado tantas emoções é uma coisa positiva.",
  ui_story_5053_50531401_28_dialog_content = "Mas, às vezes, um problema só pode ser resolvido comunicando-se aberta e sinceramente, mesmo quando isso é assustador.",
  ui_story_5053_50531401_29_dialog_content = "quando senhora Joshua finalmente desperta no mundo real, devo pedir que você compartilhe esses pensamentos sinceros com ela também.",
  ui_story_5053_50531401_30_dialog_content = "Caso contrário, ela pode ficar tão furiosa que perderá a consciência novamente.",
  ui_story_5053_50531401_31_dialog_content = "... Vou me lembrar de fazê-lo.",
  ui_story_5053_50531401_32_dialog_content = "Ué, Senhor Schwartz? Você e a Sra. Rot já terminaram de conversar? Ainda precisamos conversar sobre o próximo passo do nosso plano.",
  ui_story_5053_50531401_33_dialog_content = "Certamente.",
  ui_story_5053_50531401_34_dialog_content = "... Espere, onde está Caleb? Ele já está se sentindo melhor?",
  ui_story_5053_50531401_35_dialog_content = "Deixe-o em paz por enquanto.",
  ui_story_5053_50531401_36_dialog_content = "...",
  ui_story_5053_50531401_37_dialog_content = "Você é... realmente minha irmã...?",
  ui_story_5053_50531401_38_dialog_content = "—!",
  ui_story_5053_50531401_39_dialog_content = "Por que você se esconde de mim?",
  ui_story_5053_50531401_40_dialog_content = "O Demônio Branco estava dizendo a verdade? É possível que... você nunca tenha realmente me visto como uma família?",
  ui_story_5053_50531401_41_dialog_content = "... Não...",
  ui_story_5053_50531401_42_dialog_content = "Caleb... estou... com medo...",
  ui_story_5053_50531401_43_dialog_content = "Assustada?",
  ui_story_5053_50531401_44_dialog_content = "Caleb... me amou... confiou em mim...",
  ui_story_5053_50531401_45_dialog_content = "Meu peito... dói... a pressão... não consigo respirar...",
  ui_story_5053_50531401_46_dialog_content = "Pai.. soltou... morreu... para me proteger... Tudo... minha culpa...",
  ui_story_5053_50531401_47_dialog_content = "O que você quer dizer...?",
  ui_story_5053_50531401_48_dialog_content = "A outra parte de você disse que papai cometeu suicídio para preservar as brasas da vingança.",
  ui_story_5053_50531401_49_dialog_content = "No entanto, você está dizendo que ele deixou tudo ir... Eu não posso mais dizer qual é a verdade.",
  ui_story_5053_50531401_50_dialog_content = "Você se passou por minha irmã por todos esses anos, só para poder assassinar o pai de Schwartz.",
  ui_story_5053_50531401_51_dialog_content = "Você me criou e cuidou de mim como uma irmã de verdade... Não, como uma mãe.",
  ui_story_5053_50531401_52_dialog_content = "Todos esses anos me aturando... O estresse deve ter sido insuportável.",
  ui_story_5053_50531401_53_dialog_content = "... Mas isso não importa agora, Joshua. Sua felicidade sempre será minha prioridade, agora e sempre.",
  ui_story_5053_50531401_54_dialog_content = "Assim que voltarmos à realidade, se você realmente não me vê como seu irmão... Então nunca mais vou incomodá-lo. Quero que viva livremente e sem remorsos, como sempre quis.",
  ui_story_5053_50531401_55_dialog_content = "Não... Por favor... não me deixe... Caleb...",
  ui_story_5053_50531401_56_dialog_content = "Eu estava errado... em mentir... mas... eu estava com medo...",
  ui_story_5053_50531401_57_dialog_content = "Com medo... de você... me odiar...",
  ui_story_5053_50531401_58_dialog_content = "...",
  ui_story_5053_50531401_59_dialog_content = "Eu nunca poderia te odiar, Joshua.",
  ui_story_5053_50531401_60_dialog_content = "Você é a irmã mais linda e gentil que alguém poderia desejar.",
  ui_story_5053_50531401_61_dialog_content = "Como eu poderia me ressentir de você de alguma forma?",
  ui_story_5053_50531401_62_dialog_content = "Tudo bem, então deixe-me repassar tudo uma última vez.",
  ui_story_5053_50531401_63_dialog_content = "Do jeito que está, acabamos com o plano anterior do Demônio Branco de nos matar.",
  ui_story_5053_50531401_64_dialog_content = "Sem nenhum outro lugar para ir, há uma boa chance de ela usar o dragão e aquelas pessoas controladas pela mente para lançar um ataque final desesperado.",
  ui_story_5053_50531401_65_dialog_content = "Mesmo que tenhamos a vantagem numérica agora, e os jovens Schwartz ainda está se defendendo do dragão...",
  ui_story_5053_50531401_66_dialog_content = "Ele e suas forças não serão capazes de lutar com força total, não com o pouco Lumina que resta no Cristal da Memória Eterna.",
  ui_story_5053_50531401_67_dialog_content = "Não só isso, restam apenas algumas horas no dia.",
  ui_story_5053_50531401_68_dialog_content = "Precisamos de um método simples e eficaz que nos permita lidar com todos os peões do Demônio Branco no menor tempo possível.",
  ui_story_5053_50531401_69_dialog_content = "É a única maneira de conseguirmos capturá-la.",
  ui_story_5053_50531401_70_dialog_content = "Esse Cristal da Memória Eterna tem alguma outra função que possamos usar, Jakine? Podemos usá-lo para manipular as outras ilusões, assim como o Demônio Branco?",
  ui_story_5053_50531401_71_dialog_content = "Hum... Não! Com o pouco Lumina que resta, o Cristal da Memória Eterna não pode ser usado para nada além de sustentar o mundo ao nosso redor.",
  ui_story_5053_50531401_72_dialog_content = "Além disso, este Cristal de Memória Eterna é apenas um dispositivo à prova de falhas.",
  ui_story_5053_50531401_73_dialog_content = "Em primeiro lugar, nunca deveria ter sido tão usado... Já quebramos regras suficientes desde que pusemos as mãos nele.",
  ui_story_5053_50531401_74_dialog_content = "Mas se eu conseguisse montar um encantamento ainda melhor do que da última vez...!",
  ui_story_5053_50531401_75_dialog_content = "Não, Jakine. Nossa situação é terrível demais para recorrermos a outro de seus feitiços improvisados.",
  ui_story_5053_50531401_76_dialog_content = "Ehehehe... Entendi.",
  ui_story_5053_50531401_77_dialog_content = "Não será necessário.",
  ui_story_5053_50531401_78_dialog_content = "Tudo o que precisamos fazer é deixá-los se destruir.",
  ui_story_5053_50531401_79_dialog_content = "Bem-vindo de volta, Calebe! Você acabou de chorar agora?",
  ui_story_5053_50531401_80_dialog_content = "Eu não estava chorando! Como ousa me tratar como uma criança!",
  ui_story_5053_50531401_81_dialog_content = "O que você quer dizer com isso, Caleb? Por que eles se destruiriam se estivessem todos sob o controle do Demônio Branco?",
  ui_story_5053_50531401_82_dialog_content = "É simples, realmente.",
  ui_story_5053_50531401_83_dialog_content = "Ao interromper o equilíbrio de Lumina em seus corpos, eles perderão a capacidade de se controlar. Dolorosamente, devo acrescentar.",
  ui_story_5053_50531401_84_dialog_content = "O \"equilíbrio de Lumina\"? Eu nunca ouvi falar de nada assim antes.",
  ui_story_5053_50531401_85_dialog_content = "Hmph, os aurorianos comuns nunca entenderiam, mas acredito que nosso amigo celestita saiba exatamente do que estou falando. Não é mesmo?",
  ui_story_5053_50531401_86_dialog_content = "M-Eu? Uh... Bem, eu notei algo diferente sobre suas trilhas de luz...",
  ui_story_5053_50531401_87_dialog_content = "Sua resposta duvidosa é... Bastante decepcionante.",
  ui_story_5053_50531401_88_dialog_content = "<size=30>PlayerName, senti que Caleb estava ficando mais hostil conosco antes. Talvez ele seja realmente uma pessoa podre?</size>",
  ui_story_5053_50531401_89_dialog_content = "<size=30>Bem, sem comentários...</size>",
  ui_story_5053_50531401_90_dialog_content = "Vocês dois! Sem bate-papo enquanto a aula está em sessão!",
  ui_story_5053_50531401_91_dialog_content = "Chega de brincadeiras, Caleb. Conte-nos o seu plano.",
  ui_story_5053_50531401_92_dialog_content = "Posso preparar um certo tipo de droga, uma poção que pode desestabilizar o Lumina do usuário. Pense nisso como um veneno que atinge diretamente Lumina.",
  ui_story_5053_50531401_93_dialog_content = "Tudo dentro do Cristal da Memória Eterna foi criado através de uma combinação da Lumina de Joshua e da água do Espelho do Lago.",
  ui_story_5053_50531401_94_dialog_content = "Como resultado, esta droga deve ser altamente eficaz contra nossos inimigos.",
  ui_story_5053_50531401_95_dialog_content = "Mas com tão poucos ingredientes à mão, proponho que o usemos para combater o dragão.",
  ui_story_5053_50531401_96_dialog_content = "Os fantoches controlados pela mente do Demônio Branco nada mais são do que formigas perniciosas. Se derrubarmos o dragão sobre eles...",
  ui_story_5053_50531401_97_dialog_content = "A dor induzida pela droga fará com que ele pise e se contorça no chão, esmagando nossos adversários no processo.",
  ui_story_5053_50531401_98_dialog_content = "Ah! Então, em outras palavras, se conseguirmos alimentar o dragão com veneno, ele cairá sobre suas cabeças estúpidas!",
  ui_story_5053_50531401_99_dialog_content = "... De certa forma, sim.",
  ui_story_5053_50531401_100_dialog_content = "Devo dizer que seu plano é bastante indicativo de seu estilo habitual. Você sempre gostou de truques simples, mas sinistros como este.",
  ui_story_5053_50531401_101_dialog_content = "Estou surpreso que você ainda se lembre disso, meu senhor. Minha xícara de chá foi realmente tão memorável?",
  ui_story_5053_50531401_102_dialog_content = "(Espere... Caleb envenenou o Senhor Schwartz no passado?!)",
  ui_story_5053_50531401_103_dialog_content = "<size=30>Afinal, você realmente não é uma boa pessoa, Caleb!</size>",
  ui_story_5053_50531401_104_dialog_content = "Affff... Hehehe...",
  ui_story_5053_50531401_105_dialog_content = "Pare de rir, Mia.",
  ui_story_5053_50531401_106_dialog_content = "Me desculpe, eu não pude evitar... Espere, eu não quis dizer isso...",
  ui_story_5053_50531401_107_dialog_content = "Eu só tenho ingredientes suficientes para fazer uma única poção. Vou precisar de alguém poderoso para subjugar o dragão por tempo suficiente para eu administrar a poção. Alguém como você.",
  ui_story_5053_50531401_108_dialog_content = "H-Huh? Meu...?!",
  ui_story_5053_50531401_109_dialog_content = "Sim você. Agora siga-me.",
  ui_story_5053_50531401_110_dialog_content = "E-espere, tio...!",
  ui_story_5053_50531401_111_dialog_content = "Lá vai ele, correndo para fazer suas próprias coisas de novo! Acha que devemos segui-los?",
  ui_story_5053_50531401_112_dialog_content = "Deixe o dragão para Caleb. Eu acredito nele, assim como Mia.",
  ui_story_5053_50531401_113_dialog_content = "Senhor Schwartz...",
  ui_story_5053_50531401_114_dialog_content = "De acordo com você, sempre consigo sobreviver aos esquemas do Demônio Branco até o fim, mas nunca posso mudar o resultado.",
  ui_story_5053_50531401_115_dialog_content = "Vocês, jovens heróis, por outro lado, são muito mais capazes de moldar o futuro do que eu jamais poderia ser.",
  ui_story_5053_50531401_116_dialog_content = "Sempre pensei que poderia proteger tudo com minhas próprias mãos... Mas parece que chegou a hora de deixar de lado meu orgulho teimoso.",
  ui_story_5053_50531401_117_dialog_content = "Então, devemos ficar aqui por enquanto?",
  ui_story_5053_50531401_118_dialog_content = "Sim, Jakine. Ficaremos aqui para reunir nossa inteligência e nossa força.",
  ui_story_5053_50531401_119_dialog_content = "Conhecendo o Demônio Branco, ela aparecerá diante de nós para uma última batalha depois que seu trunfo for derrotado.",
  ui_story_5053_50531401_120_dialog_content = "Esse é o tipo de adversário tenaz que enfrentamos.",
  ui_story_5053_50531401_121_dialog_content = "Ah, uma coisinha...",
  ui_story_5053_50531401_122_dialog_content = "...",
  ui_story_5053_50531401_123_dialog_content = "Ainda preciso convencê-la a partir conosco.",
  ui_story_5053_50531401_125_dialog_content = "Então nos encontramos aqui mais uma vez. Você e eu, de pé nesta mesa à noite.",
  ui_story_5053_50531401_126_dialog_content = "...",
  ui_story_5053_50531401_127_dialog_content = "A última vez que isso aconteceu, tentei mudar o resultado de nosso desentendimento fingindo ser meu eu mais jovem.",
  ui_story_5053_50531401_128_dialog_content = "Eu disse que não queria mais te machucar, mas neste mundo ilusório, minhas ações foram em busca de autossatisfação e nada mais.",
  ui_story_5053_50531401_129_dialog_content = "Ironicamente, você estava diante de mim o tempo todo, testemunhando o meu pior. Não é de admirar que você esteja tão zangado comigo.",
  ui_story_5053_50531401_130_dialog_content = "D... Daniel...",
  ui_story_5053_50531401_131_dialog_content = "Você estava certo. Isso é tudo culpa minha, e sua vingança contra mim é perfeitamente justificada. No entanto, você não pode me matar ainda.",
  ui_story_5053_50531401_132_dialog_content = "Essas crianças são inocentes e não merecem morrer neste lugar.",
  ui_story_5053_50531401_133_dialog_content = "Então, por favor, ajude-nos a capturar sua outra metade para que possamos escapar. O que você diz?",
  ui_story_5053_50531401_134_dialog_content = "As crianças são... o futuro... Devemos... proteger o futuro...",
  ui_story_5053_50531401_135_dialog_content = "Então estamos de acordo. Obrigado, Joshua... Obrigado por acreditar em mim mais uma vez.",
  ui_story_5053_50531401_136_dialog_content = "...",
  ui_story_5053_50531401_137_dialog_content = "Calebe e Mia acabou de sair. Devemos tentar recuperar nossas forças por enquanto.",
  ui_story_5053_50531401_138_dialog_content = "Você ainda se lembra daquela música, Joshua?",
  ui_story_5053_50531401_139_dialog_content = "Sim... Uma canção de... Lower Lumopolis... sobre... uma vida feliz...",
  ui_story_5053_50531401_140_dialog_content = "Sim, essa mesma música. Para falar a verdade, preparei um presente para você há doze anos.",
  ui_story_5053_50531401_141_dialog_content = "Mas no calor do momento, esqueci de dar a você. Se bem me lembro... Deve estar bem aqui.",
  ui_story_5053_50531401_142_dialog_content = "Uma gravação?",
  ui_story_5053_50531401_143_dialog_content = "Isso mesmo. Pedi a alguém que gravasse uma versão dançante dessa mesma música. Você gostaria de ouvi-la? Afinal, há um toca-discos bem aqui.",
  ui_story_5053_50531401_144_dialog_content = "<color=#e8d9bb>...♪</color>",
  ui_story_5053_50531401_145_dialog_content = "...!",
  ui_story_5053_50531401_146_dialog_content = "Fico feliz em ver que você gostou, Joshua.",
  ui_story_5053_50531401_147_dialog_content = "Mas seria um desperdício simplesmente ouvir uma música tão maravilhosa.",
  ui_story_5053_50531401_148_dialog_content = "Bem, minha bela dama? May Eu tenho essa dança?",
  ui_story_5053_50531401_149_dialog_content = "...",
  ui_story_5053_50531401_150_dialog_content = "...",
  ui_story_5053_50531401_151_dialog_content = "Da... Daniel...",
  ui_story_5053_50531401_152_dialog_content = "Sim?",
  ui_story_5053_50531401_153_dialog_content = "Estão todos... bem...?",
  ui_story_5053_50531401_154_dialog_content = "...Sim, muito bem.",
  ui_story_5053_50531401_155_dialog_content = "Carleen agora é Capitão da Guarda de Lumopolis e comanda uma equipe de subordinados exemplares. Além disso, ela também fez muitos amigos confiáveis.",
  ui_story_5053_50531401_156_dialog_content = "Mia continua a viver sob os cuidados e orientação de Istvan. Sua condição melhorou muito; Ouvi dizer que ela pode até sair e brincar durante o dia agora.",
  ui_story_5053_50531401_157_dialog_content = "Quanto a Caleb... Ele parece estar se saindo muito bem no Dawn Academia. Aposto que ele sente sua falta mais do que qualquer outra pessoa no mundo.",
  ui_story_5053_50531401_158_dialog_content = "E você...?",
  ui_story_5053_50531401_159_dialog_content = "Eu?",
  ui_story_5053_50531401_160_dialog_content = "Meu tempo acabou agora, Joshua.",
  ui_story_5053_50531401_161_dialog_content = "Eu era tão impotente no passado e cometi mais erros do que poderia contar, mas agora. Agora, nossos filhos estão sobre meus ombros, alcançando alturas maiores do que jamais saberei.",
  ui_story_5053_50531401_162_dialog_content = "Tudo o que me resta fazer é permanecer neste lugar, apoiando-os enquanto lutam por um futuro melhor.",
  ui_story_5053_50531401_163_dialog_content = "O futuro ideal que você e eu sempre sonhamos.",
  ui_story_5053_50531401_164_dialog_content = "Quando voltarmos, posso providenciar para que você se recupere na segurança e privacidade da casa de Caleb.",
  ui_story_5053_50531401_165_dialog_content = "Depois, farei com que Veronica volte para acompanhá-lo e compartilhar as boas novas com Carleen. Em breve, nossa família estará inteira novamente.",
  ui_story_5053_50531401_166_dialog_content = "Só agora... Bem, como você pode ver, eu envelheci bastante. Posso ser ainda menos digno de sua companhia agora, mas ficaria grato se me permitisse visitá-lo de vez em quando. Isso estaria bem?",
  ui_story_5053_50531401_167_dialog_content = "Quer... Casa...",
  ui_story_5053_50531401_168_dialog_content = "Joshua?",
  ui_story_5053_50531401_169_dialog_content = "Eu quero ir para casa...",
  ui_story_5053_50531401_170_dialog_content = "Eu sei. Prometo que vamos para casa juntos.",
  ui_story_5053_50531401_171_dialog_content = "Joshua... Você se arrepende do nosso casamento?",
  ui_story_5053_50531401_172_dialog_content = "Ter guardado tanta raiva e dor escondida em seu coração... Você se arrepende de ter me escolhido para ser seu marido?",
  ui_story_5053_50531401_173_dialog_content = "Você me ensinou... felicidade e amor.",
  ui_story_5053_50531401_174_dialog_content = "O ódio... é o outro lado... do amor.",
  ui_story_5053_50531401_175_dialog_content = "O ódio é... doloroso... mas nasceu... do amor... Então eu... não me arrependo.",
  ui_story_5053_50531401_176_dialog_content = "...",
  ui_story_5053_50531401_177_dialog_content = "É mesmo?",
  ui_story_5053_50531401_178_dialog_content = "Entendo...",
  ui_story_5053_50531401_179_dialog_content = "Pontos cinco e seis agora estão armados...",
  ui_story_5053_50531401_180_dialog_content = "Bom. Agora só falta um detonador, e nossas bombas estarão prontas para atrair o dragão.",
  ui_story_5053_50531401_181_dialog_content = "Como vão as coisas com os explosivos, Sr. Caleb? Você precisa da minha ajuda?",
  ui_story_5053_50531401_182_dialog_content = "De jeito nenhum. Já terminei de montá-los.",
  ui_story_5053_50531401_183_dialog_content = "Em tão pouco tempo, nada menos. Muito impressionante, senhor.",
  ui_story_5053_50531401_184_dialog_content = "Não há necessidade de bajulação entre parentes, Sra. Rot. Além disso, se alguém merece elogios, é você.",
  ui_story_5053_50531401_185_dialog_content = "Sem você, esses guardas nunca teriam permitido que fizéssemos preparativos tão elaborados.",
  ui_story_5053_50531401_186_dialog_content = "Estou simplesmente cumprindo meus deveres. Tem certeza de que nenhum de vocês precisa da minha ajuda?",
  ui_story_5053_50531401_187_dialog_content = "Como uma ilusão criada pelo Cristal da Memória Eterna, sou muito mais adequado para manter o inimigo afastado.",
  ui_story_5053_50531401_188_dialog_content = "Por favor, não diga isso, Sra. Rot...",
  ui_story_5053_50531401_189_dialog_content = "No entanto, tenho algo importante que gostaria de lhe pedir.",
  ui_story_5053_50531401_190_dialog_content = "Estou às suas ordens, alteza.",
  ui_story_5053_50531401_191_dialog_content = "Você poderia, por favor, ficar ao lado de Carleen no meu lugar? Ela está sozinha agora, e tenho certeza que isso a deixaria tranquila.",
  ui_story_5053_50531401_192_dialog_content = "Como quiser. Mas primeiro, devo perguntar...",
  ui_story_5053_50531401_193_dialog_content = "Por que você está tão preocupado com nossa segurança, apesar do fato de que nenhum de nós é real?",
  ui_story_5053_50531401_194_dialog_content = "Não, Sra. Rot... Vocês ainda são muito reais para mim. Cada um de vocês é um reflexo de alguém com quem me preocupo profundamente. Você compartilha seus rostos, suas personalidades... Até mesmo suas memórias.",
  ui_story_5053_50531401_195_dialog_content = "Mesmo que você exista apenas dentro deste cristal, eu ainda cuido de você exatamente da mesma maneira.",
  ui_story_5053_50531401_196_dialog_content = "A meu ver, nossa preocupação um pelo outro é o que torna nossas interações reais.",
  ui_story_5053_50531401_197_dialog_content = "Além disso, recuso-me a ver os outros como sem importância, ou mesmo dispensáveis...",
  ui_story_5053_50531401_198_dialog_content = "Eu me preocupo que, se o fizer, vou me perder de vista como pessoa.",
  ui_story_5053_50531401_199_dialog_content = "Você sempre se pareceu com sua mãe, a princesa Veronica, mas agora... mal posso diferenciá-la.",
  ui_story_5053_50531401_200_dialog_content = "I-É assim...?",
  ui_story_5053_50531401_201_dialog_content = "Os preparativos estão finalmente completos! Está na hora, Mia!",
  ui_story_5053_50531401_202_dialog_content = "Entendido! Por favor, cuide bem Carleen, Sra. Rot!",
  ui_story_5053_50531401_203_dialog_content = "Parece que minhas preces foram atendidas. O futuro do Schwartz família é tão brilhante quanto o próprio sol.",
  ui_story_5053_50531401_204_dialog_content = "*Inspira* Ufa...",
  ui_story_5053_50531401_205_dialog_content = "Assim que eu apertar este botão, as bombas detonarão em uma sequência, o que deve atrair o dragão até nossa localização em menos de vinte segundos.",
  ui_story_5053_50531401_206_dialog_content = "Você está pronto, Mia?",
  ui_story_5053_50531401_207_dialog_content = "Eu acho que sim...",
  ui_story_5053_50531401_208_dialog_content = "Suspiro... Depois de tudo que passamos, como você ainda está tão inseguro?",
  ui_story_5053_50531401_209_dialog_content = "Junte-se!",
  ui_story_5053_50531401_210_dialog_content = "S-Desculpe! Hum... May Eu te pergunto uma coisa, tio?",
  ui_story_5053_50531401_211_dialog_content = "Seja breve.",
  ui_story_5053_50531401_212_dialog_content = "Por que você me escolheu para ajudá-lo com esta parte do plano?",
  ui_story_5053_50531401_213_dialog_content = "Se você precisasse de alguém poderoso, papai ou a Sra. Rot teria sido uma escolha melhor do que eu.",
  ui_story_5053_50531401_214_dialog_content = "Oh? E o que te faz dizer isso?",
  ui_story_5053_50531401_215_dialog_content = "Nossa aventura até agora me deu uma compreensão clara do seu poder, Mia. Além disso, me disseram que você é capaz de invocar um familiar Lumina. Isso é verdade?",
  ui_story_5053_50531401_216_dialog_content = "Nesse caso, você tem a maior mobilidade de qualquer um de nós, o que o torna um candidato perfeito para este plano.",
  ui_story_5053_50531401_217_dialog_content = "MM-Meu familiar?!",
  ui_story_5053_50531401_218_dialog_content = "Mas eu só convoquei Hippoca algumas vezes até agora! Ainda não sou muito bom em montá-lo...",
  ui_story_5053_50531401_219_dialog_content = "\"Algumas vezes\", você diz? Por que diabos você desperdiçaria um presente tão raro e valioso?!",
  ui_story_5053_50531401_220_dialog_content = "B-Bem... A aparência de Hippoca pode ser um pouco perturbadora. Quando o convoquei pela primeira vez, todos ficaram com medo de Hippoca e disseram que sua existência era um terrível presságio.",
  ui_story_5053_50531401_221_dialog_content = "M-Mas eu não sinto mais isso por ele! Nunca mais vou duvidar de mim mesmo por causa do que as outras pessoas dizem!",
  ui_story_5053_50531401_222_dialog_content = "Ainda assim, a verdade é que Hippoca e eu lutamos juntos apenas algumas vezes... É por isso que não me sinto muito confiante...",
  ui_story_5053_50531401_223_dialog_content = "Se falharmos, então a vida de todos...",
  ui_story_5053_50531401_224_dialog_content = "Entendo. Foi obra de Schwartz, não foi?",
  ui_story_5053_50531401_225_dialog_content = "...",
  ui_story_5053_50531401_226_dialog_content = "Ele o proibiu de convocar seu familiar, tudo por causa daqueles nobres fofoqueiros.",
  ui_story_5053_50531401_227_dialog_content = "Ele honestamente pensou que você seria salvo das críticas ao impedi-lo de invocar Hippoca?",
  ui_story_5053_50531401_228_dialog_content = "Huh? N-Não tio, o pai só estava tentando me proteger... Não estava?",
  ui_story_5053_50531401_229_dialog_content = "<size=45>Esse tolo! Aquele tolo completo e absoluto!</size>",
  ui_story_5053_50531401_230_dialog_content = "O quê...?!",
  ui_story_5053_50531401_231_dialog_content = "Escute-me, Mia! Aqueles nobres idiotas só disseram isso porque estavam com inveja de você! Quanto mais extraordinário você é, mais eles tentam arrastá-lo pela lama!",
  ui_story_5053_50531401_232_dialog_content = "É por isso que você não deve ouvi-los ou a seu pai! Se eles dizem para você não fazer algo, essa é a razão pela qual você deve fazê-lo! A vida de um gênio é repleta de obstáculos!!",
  ui_story_5053_50531401_233_dialog_content = "\"A vida de um gênio\"?! M-Mas ainda acho que devemos ouvir os outros, especialmente nossa família...",
  ui_story_5053_50531401_234_dialog_content = "Não é verdade, Mia. Isso é exatamente o que eles querem que você pense, para que possam continuar segurando você. Deixe-me mostrar-lhe o caminho.",
  ui_story_5053_50531401_235_dialog_content = "Você deve liberar cada grama de seu poder, aqui e agora! Deixe-o fluir por todas as células do seu corpo e libere-o de uma só vez!",
  ui_story_5053_50531401_236_dialog_content = "Huh...?!",
  ui_story_5053_50531401_237_dialog_content = "Somente o remédio mais poderoso irá curá-lo dessa submissão irritante, Mia.",
  ui_story_5053_50531401_238_dialog_content = "E somente compreendendo toda a extensão do seu poder você aprenderá a controlá-lo.",
  ui_story_5053_50531401_239_dialog_content = "Toda a extensão do meu poder...",
  ui_story_5053_50531401_240_dialog_content = "(As pessoas tendem a temer o que não entendem. Nesse aspecto, não sou diferente de ninguém.)",
  ui_story_5053_50531401_241_dialog_content = "(Os métodos do tio podem parecer um pouco extremos... Mas ele está certo. Preciso conhecer a verdadeira profundidade de minha própria força.)",
  ui_story_5053_50531401_242_dialog_content = "Relaxe, eu prometo mantê-lo seguro enquanto você faz isso. Você não pensou que eu era apenas mais um estudioso insignificante, pensou?",
  ui_story_5053_50531401_243_dialog_content = "Th-O pensamento nunca passou pela minha cabeça. Muito bem, tio... Farei o possível!",
  ui_story_5053_50531401_244_dialog_content = "Esse é o espírito!",
  ui_story_5053_50531401_245_dialog_content = "Agora prepare-se para a batalha!",
  ui_story_5053_50531501_1_dialog_content = "<color=#e8d9bb>Rugido-</color>",
  ui_story_5053_50531501_2_dialog_content = "Que rugido monstruoso! Nós poderíamos ouvi-lo todo o caminho até aqui!",
  ui_story_5053_50531501_3_dialog_content = "Já se passaram três minutos desde a primeira explosão. Duas chamas de cores diferentes estão lutando lá fora no céu.",
  ui_story_5053_50531501_4_dialog_content = "o azul é Mia, e o vermelho é o dragão...",
  ui_story_5053_50531501_5_dialog_content = "Olhar! A chama vermelha está descendo! Mia e Caleb fez isso!",
  ui_story_5053_50531501_6_dialog_content = "Parece que chegamos na hora certa.",
  ui_story_5053_50531501_7_dialog_content = "Senhor Schwartz! Eu estava prestes a vir e dizer-lhe!",
  ui_story_5053_50531501_8_dialog_content = "Então vocês dois estão prontos para negociar?",
  ui_story_5053_50531501_9_dialog_content = "Sim, e agora que a situação virou...",
  ui_story_5053_50531501_10_dialog_content = "Tudo o que resta é ver onde a rainha inimiga faz seu movimento final.",
  ui_story_5053_50531501_11_dialog_content = "... Aqui...",
  ui_story_5053_50531501_12_dialog_content = "Huh? O que quer dizer aqui\"?",
  ui_story_5053_50531501_13_dialog_content = "Aqui... Ela está aqui...!",
  ui_story_5053_50531501_14_dialog_content = "Th-O chão está tremendo e rachando!! Isso é coisa do Demônio Branco?!",
  ui_story_5053_50531501_15_dialog_content = "PlayerName!",
  ui_story_5053_50531501_16_dialog_content = "Explosão! O que no mundo está acontecendo?!",
  ui_story_5053_50531501_17_dialog_content = "Mia? Calebe? O que vocês dois estão fazendo de volta tão cedo? Você não acabou de matar o dragão?",
  ui_story_5053_50531501_18_dialog_content = "Não, e também não temos certeza do que aconteceu.",
  ui_story_5053_50531501_19_dialog_content = "Quando o dragão caiu do céu, a praça central começou a entortar e quebrar. Além do meu tio e de mim...",
  ui_story_5053_50531501_20_dialog_content = "Todos na área se transformaram em flashes de luz branca e voaram para o céu.",
  ui_story_5053_50531501_21_dialog_content = "Quando tentamos escapar pela porta da frente de alguém, de repente nos encontramos de volta à mansão.",
  ui_story_5053_50531501_22_dialog_content = "Zzzzz...",
  ui_story_5053_50531501_23_dialog_content = "Acordar, Jakine! Algo terrível está acontecendo!",
  ui_story_5053_50531501_24_dialog_content = "Zzzzz... Hã? Quem está aí?! Tire suas mãos do meu cristal!!!",
  ui_story_5053_50531501_25_dialog_content = "E-Ei... O que aconteceu com o Cristal da Memória Eterna?!",
  ui_story_5053_50531501_26_dialog_content = "O que... Por que...",
  ui_story_5053_50531501_27_dialog_content = "Por que você escolheu ficar do lado daquela criatura nojenta...?",
  ui_story_5053_50531501_28_dialog_content = "Mãe... Seu rosto...",
  ui_story_5053_50531501_29_dialog_content = "Olha as rachaduras aparecendo no rosto dela! Eles são da mesma cor que o Dark Angel!",
  ui_story_5053_50531501_30_dialog_content = "Por que você não me escolheu...?",
  ui_story_5053_50531501_31_dialog_content = "Por que ninguém entende a importância dos meus ideais...?",
  ui_story_5053_50531501_32_dialog_content = "<size=45>POR QUE?!?</size>",
  ui_story_5053_50531501_33_dialog_content = "Sh-Ela está se transformando no escuro Angel!!",
  ui_story_5053_50531501_34_dialog_content = "Então Mia estava certo! Os dois são iguais...",
  ui_story_5053_50531501_35_dialog_content = "Acho que não temos tempo para discutir sua rendição com chá e biscoitos! Vamos pegá-la!",
  ui_story_5053_50531501_36_dialog_content = "M-Mãe... Me desculpe!",
  ui_story_5053_50531501_37_dialog_content = "Joshua...",
  ui_story_5053_50531501_38_dialog_content = "Você está hesitando agora, Caleb?",
  ui_story_5053_50531501_39_dialog_content = "Até minha filha mais velha está mostrando mais coragem do que você agora.",
  ui_story_5053_50531501_40_dialog_content = "Salve-o, Schwartz! Quando se trata dos assuntos da minha irmã, só você não tem o direito de culpar ninguém!",
  ui_story_5053_50531501_41_dialog_content = "Espere até voltarmos ao mundo real!",
  ui_story_5053_50531501_42_dialog_content = "(Garoto tolo. Mesmo depois de todos esses anos, você ainda não consegue controlar seu temperamento.)",
  ui_story_5053_50531501_43_dialog_content = "...",
  ui_story_5053_50531502_1_dialog_content = "Ugh...!!",
  ui_story_5053_50531502_2_dialog_content = "Jakine!",
  ui_story_5053_50531502_3_dialog_content = "Bem à sua frente!!",
  ui_story_5053_50531502_4_dialog_content = "S-Fique para trás...",
  ui_story_5053_50531502_5_dialog_content = "Acabou, Joshua.",
  ui_story_5053_50531502_6_dialog_content = "Nem mais um passo...!",
  ui_story_5053_50531502_7_dialog_content = "Lutar só vai torná-lo mais doloroso.",
  ui_story_5053_50531502_8_dialog_content = "Fique longe de mim!!!",
  ui_story_5053_50531502_9_dialog_content = "Senhor Schwartz!",
  ui_story_5053_50531502_10_dialog_content = "<size=45>A Lâmina do Soberano—</size>",
  ui_story_5053_50531502_11_dialog_content = "Uwaaaa!!",
  ui_story_5053_50531502_12_dialog_content = "É tudo culpa sua...",
  ui_story_5053_50531502_13_dialog_content = "...",
  ui_story_5053_50531502_14_dialog_content = "Você... Me deixou fraca...",
  ui_story_5053_50531502_15_dialog_content = "Verônica e Carleen... Caleb e Blanc... E Schwartz.",
  ui_story_5053_50531502_16_dialog_content = "Eles são escória traidora, cada um deles!!",
  ui_story_5053_50531502_17_dialog_content = "Como você pode entregar seus ideais a eles?! Seu inútil, tolo quebrado—",
  ui_story_5053_50531502_18_dialog_content = "Mia, me ajude a terminar isso. Não podemos deixar minha irmã continuar se machucando.",
  ui_story_5053_50531502_19_dialog_content = "Tá bom...",
  ui_story_5053_50531502_20_dialog_content = "Espere! Não chegue perto dela!",
  ui_story_5053_50531502_21_dialog_content = "Se é assim que deve terminar... Então, em nome da vingança...",
  ui_story_5053_50531502_22_dialog_content = "Eu juro aniquilar cada um de vocês...",
  ui_story_5053_50531502_23_dialog_content = "...Huh? O que há com esse vento?",
  ui_story_5053_50531502_24_dialog_content = "Olhar! Ela está começando a absorver a Lumina dentro do Cristal da Memória Eterna!",
  ui_story_5053_50531502_25_dialog_content = "Ela está... Tentando nos derrubar com ela?!",
  ui_story_5053_50531502_26_dialog_content = "Jakine, prepare-se para nos tirar daqui! O resto de vocês, ajudem-me a dominá-la!",
  ui_story_5053_50531502_27_dialog_content = "O que? Você quer dizer agora?!",
  ui_story_5053_50531502_28_dialog_content = "Você planeja levar minha irmã de volta neste estado?!",
  ui_story_5053_50531502_29_dialog_content = "Se Joshua Se machucasse qualquer um de vocês, isso apenas partiria o coração dela.",
  ui_story_5053_50531502_30_dialog_content = "Todos os que se opõem aos meus ideais devem perecer! Morram, seus traidores imundos!!!",
  ui_story_5053_50531502_31_dialog_content = "Por que deve chegar a isso, mãe? Você poderia realmente ter tanto ódio em seu coração por nós...?",
  ui_story_5053_50531502_32_dialog_content = "Vonnie... Não fique triste...",
  ui_story_5053_50531502_33_dialog_content = "Deixe isso... Para mim...",
  ui_story_5053_50531502_34_dialog_content = "Mãe...?",
  ui_story_5053_50531502_35_dialog_content = "Argh, nossos ataques são inúteis! Mia, pare de ficar parado e concentre-se na batalha!",
  ui_story_5053_50531502_36_dialog_content = "... Joshua? Espere, o que você está fazendo?! Não chegue perto da sua outra metade!!",
  ui_story_5053_50531502_37_dialog_content = "... Confie nela, Caleb.",
  ui_story_5053_50531502_38_dialog_content = "Me deixar ir, Schwartz! Não tente me impedir! Joshua!!!",
  ui_story_5053_50531502_39_dialog_content = "O vento é forte demais para eu abrir os olhos! Não posso usar o Cristal da Memória Eterna assim!",
  ui_story_5053_50531502_40_dialog_content = "H-Huh?! IIII estou ficando deslumbrado! Me ajude-",
  ui_story_5053_50531502_41_dialog_content = "Jakine!",
  ui_story_5053_50531502_42_dialog_content = "Nossa, obrigado PlayerName... Huh?",
  ui_story_5053_50531502_43_dialog_content = "Não tenha medo... Está tudo acabado agora.",
  ui_story_5053_50531502_44_dialog_content = "Lembrem-se de segurar um ao outro com força desta vez, todos.",
  ui_story_5053_50531502_45_dialog_content = "J-Joshua...?",
  ui_story_5053_50531502_46_dialog_content = "Mãe... É você...",
  ui_story_5053_50531502_47_dialog_content = "Não! Fique atrás...",
  ui_story_5053_50531502_48_dialog_content = "É o bastante. É hora de deixar todos irem para casa agora.",
  ui_story_5053_50531502_49_dialog_content = "Não! Não chegue perto de mim... Nããão!!!",
  ui_story_5053_50531502_50_dialog_content = "<size=50>Joshua!!!</size>",
  ui_story_5053_50531601_1_dialog_content = "Eu finalmente encontrei você.",
  ui_story_5053_50531601_2_dialog_content = "É você...! Não! Saia de perto de mim!",
  ui_story_5053_50531601_3_dialog_content = "Você está realmente tão enojado comigo?",
  ui_story_5053_50531601_4_dialog_content = "Claro que sou! Você tem se visto no espelho ultimamente? Quem poderia suportar olhar para alguém tão hediondo, muito menos amá-lo?!",
  ui_story_5053_50531601_5_dialog_content = "Entendo... Eu costumava me sentir assim também.",
  ui_story_5053_50531601_6_dialog_content = "Mas quando vi o quanto minha família e meus amigos se importavam comigo, comecei a ver além da minha auto-aversão e a me amar novamente.",
  ui_story_5053_50531601_7_dialog_content = "Que nojento...",
  ui_story_5053_50531601_8_dialog_content = "Você também já se viu no espelho?",
  ui_story_5053_50531601_9_dialog_content = "Eu tenho. Eu costumava praticar o controle de minhas expressões na frente do espelho por três horas todos os dias. Não tenho mais motivos para me encarar.",
  ui_story_5053_50531601_10_dialog_content = "Isso mesmo, você sempre foi uma guerreira tão corajosa e destemida, que faria qualquer coisa para realizar seus ideais.",
  ui_story_5053_50531601_11_dialog_content = "Mas todo mundo tem algo que temem, e você não é exceção. Para você...",
  ui_story_5053_50531601_12_dialog_content = "Era seu pai morrendo.",
  ui_story_5053_50531601_13_dialog_content = "?!",
  ui_story_5053_50531601_14_dialog_content = "Foram seus filhos e irmão aprendendo a verdade.",
  ui_story_5053_50531601_15_dialog_content = "Pare com isso...",
  ui_story_5053_50531601_16_dialog_content = "Foi seu marido se separando de você.",
  ui_story_5053_50531601_17_dialog_content = "Eu disse pare com isso!!!",
  ui_story_5053_50531601_18_dialog_content = "Quem teme essas coisas é você... Não eu! Você é que insiste em ter essas emoções sem sentido!",
  ui_story_5053_50531601_19_dialog_content = "Não preciso deles... Não preciso de família nem de sentimentos para concretizar as minhas ambições! Eu só preciso me sacrificar!",
  ui_story_5053_50531601_20_dialog_content = "Eu sei. Você só quer viver uma vida simples e descomplicada. Dessa forma, você nunca teria que experimentar a felicidade ou a dor da perda.",
  ui_story_5053_50531601_21_dialog_content = "Foi o medo de conhecer essas emoções que fez você me forçar a sair do seu corpo.",
  ui_story_5053_50531601_22_dialog_content = "Cale a boca... Já chega...",
  ui_story_5053_50531601_23_dialog_content = "Eu nunca posso confiar neles! Eles não me ouvem... Eles só querem me trair...",
  ui_story_5053_50531601_24_dialog_content = "As pessoas não são máquinas. Todo mundo tem seus próprios pensamentos e sentimentos.",
  ui_story_5053_50531601_25_dialog_content = "\"Desde que te interrompi naquele dia, tenho pensado nisso constantemente.\"",
  ui_story_5053_50531601_26_dialog_content = "\"É errado confiarmos nossos sonhos aos outros?\"",
  ui_story_5053_50531601_27_dialog_content = "Daniel disse isso uma vez antes, lembra?",
  ui_story_5053_50531601_28_dialog_content = "Ele não passa de um mentiroso...",
  ui_story_5053_50531601_29_dialog_content = "Nós simplesmente dependíamos demais dele. Forçamos o peso de nossos ideais nos ombros de uma única pessoa.",
  ui_story_5053_50531601_30_dialog_content = "Você sabe melhor do que eu que a família de um senhor da cidade nunca poderia experimentar as alegrias da vida comum... E, no entanto, nunca deixei de esperar por isso.",
  ui_story_5053_50531601_31_dialog_content = "Uma assassina implacável, uma esposa perfeita para um senhor da cidade...",
  ui_story_5053_50531601_32_dialog_content = "Mudamos constantemente entre as identidades que nos foram dadas por outras pessoas, mas nenhuma delas refletia nosso verdadeiro eu.",
  ui_story_5053_50531601_33_dialog_content = "Ainda não sei quem realmente somos...",
  ui_story_5053_50531601_34_dialog_content = "...",
  ui_story_5053_50531601_35_dialog_content = "Mas uma coisa eu sei, é que não quero perder as pessoas que amo. Isso sempre será mais importante do que a verdade.",
  ui_story_5053_50531601_36_dialog_content = "Então venha comigo. É hora de parar de lutar.",
  ui_story_5053_50531601_37_dialog_content = "Argh! Sua mão... Parece que está coberta de espinhos! Mesmo o menor toque dói tanto!",
  ui_story_5053_50531601_38_dialog_content = "E, no entanto, parece tão quente... O que é esse sentimento?",
  ui_story_5053_50531601_39_dialog_content = "Então, é assim <color=#FFB400>amor</color> sentimentos.",
  ui_story_5053_50531601_40_dialog_content = "Mãe! Tosse, tosse... Mãe, cadê você?!",
  ui_story_5053_50531601_41_dialog_content = "Por aqui, Mia! Pegue minha mão!",
  ui_story_5053_50531601_42_dialog_content = "PlayerName... Todos... Para onde foi a mãe?",
  ui_story_5053_50531601_43_dialog_content = "Ela... Depois da explosão...",
  ui_story_5053_50531601_44_dialog_content = "Lance o feitiço, Jakine.",
  ui_story_5053_50531601_45_dialog_content = "Solte-me! Eu me recuso a sair sem minha irmã!!",
  ui_story_5053_50531601_46_dialog_content = "O chão está desmoronando sob nossos pés! Pressa!",
  ui_story_5053_50531601_47_dialog_content = "E-Entendi!",
  ui_story_5053_50531601_48_dialog_content = "Presença de anúncio!",
  ui_story_5053_50531601_49_dialog_content = "Voltemos à realidade!",
  ui_story_5053_50531601_50_dialog_content = "Abracadabra!",
  ui_story_5053_50531601_51_dialog_content = "Joshua! Eu não vou te deixar!! Joshua!!!",
  ui_story_5053_50531601_52_dialog_content = "Pirralho teimoso... Jakine, agarrar Mia!",
  ui_story_5053_50531601_53_dialog_content = "O-O que você disse? Não consigo te ouvir com o vento!!",
  ui_story_5053_50531601_54_dialog_content = "Eu não aguento mais! PlayerName!!",
  ui_story_5053_50531601_55_dialog_content = "Ahh!!!",
  ui_story_5053_50531601_56_dialog_content = "Então segure-se em mim.",
  ui_story_5053_50531601_57_dialog_content = "É você...?",
  ui_story_5053_50531601_58_dialog_content = "\"... Espero que esta carta te encontre bem.\"",
  ui_story_5053_50531601_59_dialog_content = "\"Como você tem passado? Os outros e eu estamos indo bem.\"",
  ui_story_5053_50531601_60_dialog_content = "Escrever uma carta, né? Para quem é?",
  ui_story_5053_50531601_61_dialog_content = "Bwaaaa! J-Jakine! Você me assustou...",
  ui_story_5053_50531601_62_dialog_content = "Heehee, desculpe por isso!",
  ui_story_5053_50531601_63_dialog_content = "Boa tarde, PlayerName.",
  ui_story_5053_50531601_64_dialog_content = "Boa tarde! Vocês com certeza chegaram cedo, pensei Jakine ia atrasar de novo!",
  ui_story_5053_50531601_65_dialog_content = "Ei, não é minha culpa que todos estão morrendo de vontade de saber sobre o meu trabalho! É difícil manter um cronograma quando uma multidão de pessoas está constantemente bombardeando você com perguntas...",
  ui_story_5053_50531601_66_dialog_content = "Oh sim, tenho certeza de que ser uma celebridade no Dawn Academia deve ser tão horrível para Jakine, o \"Acadêmico Visitante\".",
  ui_story_5053_50531601_67_dialog_content = "Heehee, não me chame assim! Você vai me fazer corar...",
  ui_story_5053_50531601_68_dialog_content = "De qualquer forma, você já cuidou das coisas do seu lado, Mia?",
  ui_story_5053_50531601_69_dialog_content = "Sim! Tudo foi tirado!",
  ui_story_5053_50531601_70_dialog_content = "Infelizmente, estávamos tão ocupados que Carleen e eu não tive a chance de dizer adeus um ao outro...",
  ui_story_5053_50531601_71_dialog_content = "Não se preocupe, você sempre pode vir vê-la no Colossus! Avisarei da próxima vez que ela estiver a bordo.",
  ui_story_5053_50531601_72_dialog_content = "Tudo bem, nos veremos novamente quando for a hora certa.",
  ui_story_5053_50531601_73_dialog_content = "Ah, certo...",
  ui_story_5053_50531601_74_dialog_content = "\"Desde então, muita coisa aconteceu aqui, com muitas pessoas tomando decisões inesperadas.\"",
  ui_story_5053_50531601_75_dialog_content = "\"Eu prometi que resolveria toda a história para você, então vamos começar do começo.\"",
  ui_story_5053_50531601_76_dialog_content = "\"Na época, saímos com sucesso do <color=#FFB400>Cristal da Memória Eterna</color>\"",
  ui_story_5053_50531601_77_dialog_content = "\"Antes de termos certeza de que todos estavam bem, Caleb já estava fora de casa e correndo de volta para sua casa.\"",
  ui_story_5053_50531601_78_dialog_content = "\"Não demorou muito para persegui-lo... Apenas para encontrá-lo com Lady Joshua, a quem ele manteve escondido em sua casa todos esses anos.\"",
  ui_story_5053_50531601_79_dialog_content = "Os olhos da mãe apenas se moveram...!",
  ui_story_5053_50531601_80_dialog_content = "Passe-me esse remédio! O da prateleira da esquerda!",
  ui_story_5053_50531601_81_dialog_content = "E-espere, ainda estou procurando a gaze!",
  ui_story_5053_50531601_82_dialog_content = "Eu tenho aqui.",
  ui_story_5053_50531601_83_dialog_content = "\"Depois de um procedimento de emergência estressante, Lady Joshua estava finalmente fora do estado crítico. Alguns dias depois, ela acordou.\"",
  ui_story_5053_50531601_84_dialog_content = "\"Infelizmente... Ela perdeu todas as suas memórias.\"",
  ui_story_5053_50531601_85_dialog_content = "Como... Como isso pode ter acontecido? Ela estava em coma por muito tempo? Ou foi aquela explosão de antes?",
  ui_story_5053_50531601_86_dialog_content = "Seja qual for o caso, parece que minha irmã não sofre mais de dupla personalidade. Mas como...?",
  ui_story_5053_50531601_87_dialog_content = "Poderia ter algo a ver com o Cristal da Memória Eterna, Jakine?",
  ui_story_5053_50531601_88_dialog_content = "Hm... eu não teria tanta certeza.",
  ui_story_5053_50531601_89_dialog_content = "E o que isso quer dizer? Isso é sério, você sabe!",
  ui_story_5053_50531601_90_dialog_content = "\"Para reparar o Cristal da Memória Eterna, bem como ajudar na recuperação de Lady Joshua...\"",
  ui_story_5053_50531601_91_dialog_content = "\"Jakine decidiu ficar em Lumopolis por mais algum tempo, e começou a realizar pesquisas ao lado de Caleb.\"",
  ui_story_5053_50531601_92_dialog_content = "\"Ele até deu a ela o título de \"Visiting Scholar to the Dawn Academy,\" apenas para fazê-la feliz.\"",
  ui_story_5053_50531601_93_dialog_content = "\"Eu não acho que o título carrega qualquer autoridade real, mas contanto que Jakine não descobre...\"",
  ui_story_5053_50531601_94_dialog_content = "No momento, tudo o que sabemos é que, por algum motivo, o Demônio Branco e o Demônio das Trevas Angel fizeram contato um com o outro no final.",
  ui_story_5053_50531601_94X1_dialog_content = "Quando ambas as personalidades conflitantes desapareceram, Lady Joshuaestado mental de voltou ao normal.",
  ui_story_5053_50531601_95_dialog_content = "Quanto à Semente, ainda temos que estudá-la a fundo, mas para isso só podemos contar com Caleb.",
  ui_story_5053_50531601_96_dialog_content = "Muito bem, Emissário Jakine de Northland. Obrigado por ficar em Lumopolis esses vários dias e ajudar Caleb na empreitada.",
  ui_story_5053_50531601_97_dialog_content = "A honra é minha! Não me sinto um estranho depois de tudo que passamos juntos!",
  ui_story_5053_50531601_98_dialog_content = "Além disso, eu deveria reabastecer o Cristal da Memória Eterna com água do Lago Espelho, para não quebrá-lo...",
  ui_story_5053_50531601_99_dialog_content = "Ah, falando nisso, o Cristal está fixo! E agora aquela senhora Joshua está de volta, você pode usá-lo a qualquer momento!",
  ui_story_5053_50531601_100_dialog_content = "Obrigado. Vou mantê-lo seguro para evitar que outros entrem acidentalmente.",
  ui_story_5053_50531601_101_dialog_content = "Sim... Mas na verdade estou um pouco preocupado com Caleb. desde senhora Joshua acordou, ele esteve perto dela o tempo todo!",
  ui_story_5053_50531601_102_dialog_content = "Também ouvi dizer que ele queria se demitir do Dawn Academia para ficar em casa e cuidar da Senhora Joshua em tempo integral... Pergunto-me se ele entendeu as implicações.",
  ui_story_5053_50531601_103_dialog_content = "Quão perpetuamente imaturo da parte dele... Ouvi dizer que você está procurando por um cavaleiro chamado Sharona. Isso é verdade?",
  ui_story_5053_50531601_104_dialog_content = "Eu sou. Vejo que sua rede está com o nariz no chão, meu senhor! Você se importaria de me apresentar a ela?",
  ui_story_5053_50531601_105_dialog_content = "Sinto muito, Jakine, mas Sharona deixou Lumopolis um tempo atrás. Não estou conseguindo atender seu pedido.",
  ui_story_5053_50531601_106_dialog_content = "O que? Mas não é o sonho dela se tornar o cavaleiro mais poderoso...?",
  ui_story_5053_50531601_107_dialog_content = "Você pode procurá-la em Illumina, mas nunca mencione Lumopolis para mim.",
  ui_story_5053_50531601_108_dialog_content = "E não se esqueça que o que aconteceu no Cristal não foi real, por mais forte que seja o vínculo que se formou entre vocês dois...",
  ui_story_5053_50531601_109_dialog_content = "Era apenas uma aspiração. Muita coisa mudou nesses doze anos.",
  ui_story_5053_50531601_110_dialog_content = "Entendo... Está tudo bem, contanto que sejamos fiéis a quem somos, ainda podemos nos tornar amigos!",
  ui_story_5053_50531601_111_dialog_content = "Permanecendo fiel a quem você é, você disse... Você está certo.",
  ui_story_5053_50531601_112_dialog_content = "\"Eu pensei senhora Joshua perder sua memória mergulharia sua família em tristezas novamente.\"",
  ui_story_5053_50531601_113_dialog_content = "\"Só que eles não se sentiram derrotados, mas rapidamente se alegraram com o reencontro após uma breve decepção.\"",
  ui_story_5053_50531601_114_dialog_content = "\"É bom ver a família feliz e inteira... Que vínculo simples, mas impecável, que todos compartilhavam.\"",
  ui_story_5053_50531601_115_dialog_content = "\"Mas o <color=#FFB400>Senhor da cidade e sua família</color> estão muito no centro das atenções para que possam desfrutar da felicidade de uma família normal.",
  ui_story_5053_50531601_116_dialog_content = "<color=#e8d9bb>A Mansão Magnus, Casa de Caleb</color>",
  ui_story_5053_50531601_117_dialog_content = "Estou de volta, mana! Veja isso. É o último chá de frutas da Umbraton. Aposto que você vai adorar!",
  ui_story_5053_50531601_118_dialog_content = "Bem-vindo a casa, tio.",
  ui_story_5053_50531601_119_dialog_content = "Bem vindo de volta. Uh, não é um dia de trabalho hoje? Você não está trabalhando, Caleb?",
  ui_story_5053_50531601_120_dialog_content = "Nenhum trabalho é tão importante quanto você. Apresentei minha demissão ao Dawn Academia já. Estarei com você a partir de agora.",
  ui_story_5053_50531601_121_dialog_content = "O que, você renunciou? Você vai abandonar sua carreira e aspirações por mim?",
  ui_story_5053_50531601_122_dialog_content = "Não coloque dessa forma, mana. Nada é tão grande quanto viver uma vida feliz com sua família.",
  ui_story_5053_50531601_123_dialog_content = "E Mia está querendo voltar para sua família em Lumopolis também. Não é verdade, Mia?",
  ui_story_5053_50531601_124_dialog_content = "Bem... Na verdade, é sobre isso que vim falar com a mamãe. Eu gostaria de ficar em Umbraton.",
  ui_story_5053_50531601_125_dialog_content = "O que? Por que você pensaria isso agora? Fez Schwartz intimidá-lo novamente?",
  ui_story_5053_50531601_126_dialog_content = "Não, foi minha própria decisão. O pai também está por trás disso.",
  ui_story_5053_50531601_127_dialog_content = "Eu era fraco e infeliz no passado, forçado a partir e suportar dificuldades...",
  ui_story_5053_50531601_128_dialog_content = "Mas também pude ver a verdade do mundo fora de Lumopolis e isso me tornou quem sou hoje. No entanto, sinto que isso não é suficiente.",
  ui_story_5053_50531601_129_dialog_content = "Você já deve saber que com você tirando muito tempo de folga e eu indo e vindo de véu, os rumores estão começando a voar nos Jardins de Lumopolis.",
  ui_story_5053_50531601_130_dialog_content = "O pai não podia nem vir aqui ver a mãe por causa disso... embora nós a escondêssemos.",
  ui_story_5053_50531601_131_dialog_content = "Eu sei! E tenho procurado uma solução. Na pior das hipóteses, vamos sair de Lumopolis!",
  ui_story_5053_50531601_132_dialog_content = "E daí se a esposa do City Lord reviveu depois de todos esses anos...",
  ui_story_5053_50531601_133_dialog_content = "Você precisa de poder real para desafiar Schwartz! Confiar apenas em denúncias políticas não serve!",
  ui_story_5053_50531601_134_dialog_content = "Sim, sei que nada disso é culpa da família, mas ainda é algo que temos que suportar.",
  ui_story_5053_50531601_135_dialog_content = "Finalmente entendo como papai se sente agora... É por isso que não cobiço mais o abraço de minha mãe.",
  ui_story_5053_50531601_136_dialog_content = "Já que não posso sobreviver sob os holofotes em Lumopolis, deixe-me ficar no escuro como uma sombra.",
  ui_story_5053_50531601_137_dialog_content = "Eu aprenderei tanto com o Sr. Istvan em Umbraton quanto possível, crescendo de um fraco necessitado de proteção para um valente cavaleiro.",
  ui_story_5053_50531601_138_dialog_content = "Então será minha vez de proteger a todos!",
  ui_story_5053_50531601_139_dialog_content = "Por que você se sente assim? Você não acha que poderia confiar e depender de mim? Fale com ela sobre isso, mana!",
  ui_story_5053_50531601_140_dialog_content = "Caleb, eu sou <color=#FFB400>alguém sem memória</color>. Não tenho passado, nem me demoro nele.",
  ui_story_5053_50531601_141_dialog_content = "Estou muito feliz que você encontrou o seu sonho, Mia. Apenas trabalhe duro, baby, e tenho certeza que você terá um futuro emocionante pela frente.",
  ui_story_5053_50531601_142_dialog_content = "Mãe... Obrigado.",
  ui_story_5053_50531601_143_dialog_content = "Você acabou de me lembrar, Mia, há um mundo excitante lá fora também. Eu deveria ver por mim mesmo.",
  ui_story_5053_50531601_144_dialog_content = "Espere um minuto, o que você quer dizer com isso, mana?",
  ui_story_5053_50531601_145_dialog_content = "\"Sim, depois de tudo que ela passou, Mia ainda escolheu sair.\"",
  ui_story_5053_50531601_146_dialog_content = "\"Ela tomou a decisão sozinha e sinceramente me sinto feliz por ela.\"",
  ui_story_5053_50531601_147_dialog_content = "\"Enquanto isso, a renúncia de Caleb foi recusada.\"",
  ui_story_5053_50531601_148_dialog_content = "\"Parecia que ele costumava apresentar todo tipo de desculpas precipitadas para renunciar, então a Academia simplesmente rejeitou por hábito.\"",
  ui_story_5053_50531601_149_dialog_content = "\"Para senhora Joshua, ela parecia estar inspirada e começou a ter suas próprias ideias.\"",
  ui_story_5053_50531601_150_dialog_content = "\"Ela escapou de Lumopolis em uma jornada solo.\"",
  ui_story_5053_50531601_151_dialog_content = "Obrigado, PlayerName, por me contrabandear no Colossus.",
  ui_story_5053_50531601_152_dialog_content = "Feliz em fazer isso. Mas como você não se despediu deles?",
  ui_story_5053_50531601_153_dialog_content = "Você é mais esperto do que isso. Eles nunca me deixariam ir se soubessem que eu estava indo embora.",
  ui_story_5053_50531601_154_dialog_content = "Mas devo partir, não apenas para protegê-los, mas como uma lição final para eles como mãe e irmã.",
  ui_story_5053_50531601_155_dialog_content = "Você realmente perdeu a memória, senhora Joshua?",
  ui_story_5053_50531601_156_dialog_content = "Claro. Não use seus poderes celestitas para espiar os segredos de uma dama agora!",
  ui_story_5053_50531601_157_dialog_content = "Ok, então direi a eles que você saiu quando eu voltar... Isso não é mentir para seus superiores, é?",
  ui_story_5053_50531601_158_dialog_content = "Bem, é para mim.",
  ui_story_5053_50531601_159_dialog_content = "O quê?!",
  ui_story_5053_50531601_160_dialog_content = "Estou brincando! Daniel provavelmente já descobriu. Não precisamos de muitas palavras para nos comunicar.",
  ui_story_5053_50531601_161_dialog_content = "Quanto a Carleen, ela é muito parecida com o Daniel... Ouvi dizer que você é muito próximo dela, então você deveria saber disso também.",
  ui_story_5053_50531601_162_dialog_content = "Ela parece tão forte e competente quando na verdade está apenas se segurando. É um segredo aberto que todos sabem que não devem contar a ela.",
  ui_story_5053_50531601_163_dialog_content = "Ela certamente é capaz o suficiente para encontrar qualquer verdade que deseja descobrir. Se ela não...",
  ui_story_5053_50531601_164_dialog_content = "Isso significa que ela ainda não está pronta para aceitar a verdade.",
  ui_story_5053_50531601_165_dialog_content = "Apesar de todo esse discurso, porém, também tenho um lado oculto.",
  ui_story_5053_50531601_166_dialog_content = "Se eu não fosse implantado, provavelmente nunca perceberia que tenho reprimido um lado sombrio em mim.",
  ui_story_5053_50531601_167_dialog_content = "Senhora Joshua...",
  ui_story_5053_50531601_168_dialog_content = "Além de aceitar os outros com bondade, também é necessário impulsioná-los com firmeza. Essa é outra forma de mostrar que você se importa, certo?",
  ui_story_5053_50531601_169_dialog_content = "Correto, mesmo um porto seguro pode ser um obstáculo ao crescimento.",
  ui_story_5053_50531601_170_dialog_content = "Carleen agora precisa de amigos confiáveis e que pensam como você mais do que nunca.",
  ui_story_5053_50531601_171_dialog_content = "Então, você vai continuar a progredir ao lado Carleen, PlayerName?",
  ui_story_5053_50531601_X171_option_content = "Sem problemas!",
  ui_story_5053_50531601_X172_option_content = "Quem eu...?",
  ui_story_5053_50531601_X173_dialog_content = "Como membro de uma raça completamente diferente de nós, aurorianos, Last Caelestite, vejo um futuro brilhante à sua frente.",
  ui_story_5053_50531601_X174_dialog_content = "O que também não tem preço e é sempre esquecido em um ambiente fechado como Lumopolis.",
  ui_story_5053_50531601_X175_dialog_content = "Eu acredito plenamente que você pode guiar Carleen... Não, guie mais pessoas para um amanhã melhor.",
  ui_story_5053_50531601_X176_dialog_content = "Sua presença e a coragem de Mia me mostraram o potencial que existe no mundo.",
  ui_story_5053_50531601_X177_dialog_content = "Talvez eu encontre o que realmente estou procurando depois de vê-lo.",
  ui_story_5053_50531601_X178_dialog_content = "Então leve essa iluminação de volta para meus entes queridos algum dia...",
  ui_story_5053_50531601_X179_dialog_content = "\"Assim, eu me despeço de você e trouxe a notícia de sua partida de volta para Lumopolis.\"",
  ui_story_5053_50531601_X180_dialog_content = "\"Alguns sorriram e deram cumprimentos. Alguns aceitaram alegremente depois de se recuperar da surpresa.\"",
  ui_story_5053_50531601_X181_dialog_content = "\"Alguns não conseguiram entender e saíram com raiva. Ainda assim, alguns pareciam ter previsto isso.\"",
  ui_story_5053_50531601_X182_dialog_content = "\"Depois de alguma comoção, todos aceitaram e optaram por não interferir na nova vida do amnésico.\"",
  ui_story_5053_50531601_X183_dialog_content = "\"Quanto a você manter uma correspondência comigo em segredo, deve ser entre nós dois.\"",
  ui_story_5053_50531601_X184_dialog_content = "\"Eu também vou mantê-lo atualizado sobre sua família como prometido.\"",
  ui_story_5053_50531601_172_dialog_content = "\"Na próxima vez que nos encontrarmos, espero que possamos compartilhar nossas aventuras como companheiros de viagem.\"",
  ui_story_5053_50531601_173_dialog_content = "PlayerName! Abaixe a caneta já!!",
  ui_story_5053_50531601_174_dialog_content = "Bwaaaa! V-você me assustou de novo, Jakine!!",
  ui_story_5053_50531601_175_dialog_content = "Oh não, você não pode me culpar desta vez, amigo! Vou voltar para Northland hoje, e você e Mia prometeu se despedir de mim! Agora pare de derramar seu coração e vamos lá!",
  ui_story_5053_50531601_176_dialog_content = "E-espere um segundo, Jakine! Um Mensageiro deve chegar a qualquer minuto para entregar minha carta!",
  ui_story_5053_50531601_177_dialog_content = "Além disso, você nunca se importou em se atrasar antes...",
  ui_story_5053_50531601_178_dialog_content = "Ei! Eu ouvi isso!",
  ui_story_5053_50531601_179_dialog_content = "Heehee, acho que teremos que esperar um pouco mais.",
  ui_story_5053_50531601_180_dialog_content = "Por falar nisso, PlayerName, você recebeu um cartão postal pelo correio recentemente?",
  ui_story_5053_50531601_181_dialog_content = "Um cartão postal?",
  ui_story_5053_50531601_182_dialog_content = "Oh, você quer dizer o cartão postal de Lady Joshua, certo? Eu tenho um também!",
  ui_story_5053_50531601_183_dialog_content = "Ela disse que chegou a uma pequena cidade no meio do nada e até encontrou um pássaro falante!",
  ui_story_5053_50531601_184_dialog_content = "Hmm... Ela deve estar falando de um demi-humano. A mãe disse que eles se tornaram amigos íntimos em pouco tempo... Estou tão feliz por ela!",
  ui_story_5053_50531601_185_dialog_content = "Huh? Só eu que não recebi um postal...?",
  ui_story_5053_50531601_186_dialog_content = "Acho que ela deve gostar mais de nós do que de você, PlayerName! Você fez algo para perturbá-la?",
  ui_story_5053_50531601_187_dialog_content = "O-Claro que não! Tenho certeza que meu cartão postal chegará a qualquer momento, você verá!",
  ui_story_5053_50531601_188_dialog_content = "TOC Toc! Eho o Correio, ao seu serviço!",
  ui_story_5053_50531601_189_dialog_content = "Uau, bom momento!",
  ui_story_5053_50531601_190_dialog_content = "Chegando! Obrigado novamente por entregar minha carta, Eho.",
  ui_story_5053_50531601_191_dialog_content = "Não mencione isso! Vou levar isso... E aqui, este envelope é para você!",
  ui_story_5053_50531601_192_dialog_content = "Para mim? Ei, isso é...!",
  ui_story_5053_50531601_193_dialog_content = "Que coisas divertidas você tem aí?",
  ui_story_5053_50531601_194_dialog_content = "O que foi, PlayerName?",
  ui_story_5053_50531601_195_dialog_content = "Podemos dar uma olhada nele também, PlayerName?",
  ui_story_5053_50531601_196_dialog_content = "Desculpe, mas não posso mostrar para você!",
  ui_story_5053_50531601_197_dialog_content = "\"Querido PlayerName, Espero que você esteja bem?\"",
  ui_story_5053_50531601_198_dialog_content = "\"No momento, estou a caminho de...\"",
  ui_story_5053_50531601_199_dialog_content = "Escolha uma rosa, só para o meu bebê... ♪",
  ui_story_5053_50531601_200_dialog_content = "A brisa em seu rosto e seu sorriso são tudo que eu preciso... ♪",
  ui_story_5053_50531601_201_dialog_content = "Escolha uma rosa para mamãe e papai também... ♪",
  ui_story_5053_50531601_202_dialog_content = "Embora o mundo possa mudar, nosso amor sempre permanecerá o mesmo... ♪"
}
return config
